    function getrotrad(rotation){


        var CanvRotRad = rotation * (Math.PI / 180);

        switch (rotation) {
            case 0:
                CanvRotRad = rotation * (Math.PI / 180);
                break;
            case 90:
                CanvRotRad = (rotation + 180) * (Math.PI / 180);
                break;
            case 270:
                CanvRotRad = (rotation - 180) * (Math.PI / 180);
                break;
            case 180:
                CanvRotRad = rotation * (Math.PI / 180);
                break;
        }

        return CanvRotRad;

    }

    function mouse_rotatedPage(x,y, radrot, centre){

        var transpoint = {x:x,y:y};

        var cosangle = Math.cos(radrot);
        var sinangle = Math.sin(radrot);

        var hw = x - centre.x;
        var hh = y - centre.y;

        var newx = (hw * cosangle) - (hh * sinangle);
        var newy = (hw * sinangle) + (hh * cosangle);

        transpoint = {x:newx,y:newy};
        transpoint.x = centre.x + transpoint.x;
        transpoint.y = centre.y + transpoint.y;

        return transpoint;


    }



