    function blockrectrotated(rect, angle){
        var centercanvX = (canvasowidth / 2);
        var centercanvY = (canvasoheight / 2);
        var width = centercanvX;
        var height = centercanvY;

        var CanvRotRad = 0;

        var transrect = {x : rect.x, y : rect.y, w: rect.w, h : rect.h};

        var CanvRotRad = angle * (Math.PI / 180);

            switch (angle) {
                case 0:
                    CanvRotRad = angle * (Math.PI / 180);

                    break;
                case 90:
                    CanvRotRad = (angle) * (Math.PI / 180);
                    var switchwh = transrect.h;
                    transrect.h = transrect.w;
                    transrect.w = switchwh;

                    break;
                case 270:
                    CanvRotRad = (angle) * (Math.PI / 180);
                    switchwh = transrect.h;
                    transrect.h = transrect.w;
                    transrect.w = switchwh;

                    break;
                case 180:
                    CanvRotRad = angle * (Math.PI / 180);
                    break;
            }





        var cosangle = Math.cos(CanvRotRad);
        var sinangle = Math.sin(CanvRotRad);

        var hw = transrect.x - width;
        var hh = transrect.y - height;

        var newx = (hw * cosangle) - (hh * sinangle);
        var newy = (hw * sinangle) + (hh * cosangle);

        /*var transpoint = {x:newx, y:newy};
        transpoint.x = width + transpoint.x;
        transpoint.y = height + transpoint.y;*/

        transrect = {x:newx,y:newy, w : transrect.w, h : transrect.h};
        transrect.x = centercanvX + transrect.x;
        transrect.y = centercanvY + transrect.y;

        return transrect;


        //return transpoint;


    }

    function zoomrectrotated(rect, angle){
        var centercanvX = (canvasowidth / 2);
        var centercanvY = (canvasoheight / 2);
        var CanvRotRad = 0;
        //var transpoint = {x:rect.x, y: rect.y};
        var transrect = {x : rect.x, y : rect.y, w: rect.w, h : rect.h};


        switch(angle){
            case 0:
                CanvRotRad = angle * (Math.PI / 180);
                return transrect;
                break;
            case 90:
                CanvRotRad = (angle + 180) * (Math.PI / 180);
                var switchwh = transrect.h;
                transrect.h = transrect.w;
                transrect.w = switchwh;

                break;
            case 270:
                CanvRotRad = (angle - 180) * (Math.PI / 180);
                switchwh = transrect.h;
                transrect.h = transrect.w;
                transrect.w = switchwh;

                break;
            case 180:
                CanvRotRad = angle * (Math.PI / 180);
                //switchwh = transrect.h;
                //transrect.w = transrect.h;
                //transrect.h = switchwh;

                break;

        }

        var cosangle = Math.cos(CanvRotRad);
        var sinangle = Math.sin(CanvRotRad);

        var hw = transrect.x - centercanvX;
        var hh = transrect.y - centercanvY;

        var newx = (hw * cosangle) - (hh * sinangle);
        var newy = (hw * sinangle) + (hh * cosangle);

        transrect = {x:newx,y:newy, w : transrect.w, h : transrect.h};
        transrect.x = centercanvX + transrect.x;
        transrect.y = centercanvY + transrect.y;

        return transrect;


    }


    function mouse_rotated(x,y){
        var centercanvX = (canvasowidth / 2);
        var centercanvY = (canvasoheight / 2);
        var CanvRotRad = 0;
        var transpoint = {x:x,y:y};

        var pagerot = DocObj.getCurrentpage().getpageRotation();

        switch(pagerot){
            case 0:
                CanvRotRad = pagerot * (Math.PI / 180);
                return transpoint;
                break;
            case 90:
                CanvRotRad = (pagerot + 180) * (Math.PI / 180);
                break;
            case 270:
                CanvRotRad = (pagerot - 180) * (Math.PI / 180);
                break;
            case 180:
                CanvRotRad = pagerot * (Math.PI / 180);
                break;
        }

        var cosangle = Math.cos(CanvRotRad);
        var sinangle = Math.sin(CanvRotRad);

        var hw = x - centercanvX;
        var hh = y - centercanvY;

        var newx = (hw * cosangle) - (hh * sinangle);
        var newy = (hw * sinangle) + (hh * cosangle);

        transpoint = {x:newx,y:newy};
        transpoint.x = centercanvX + transpoint.x;
        transpoint.y = centercanvY + transpoint.y;

        return transpoint;


    }

    function getrotpoint(width, height, x, y, anglerad){
        var cosangle = Math.cos(anglerad);
        var sinangle = Math.sin(anglerad);

        var hw = x - width;
        var hh = y - height;

        var newx = (hw * cosangle) - (hh * sinangle);
        var newy = (hw * sinangle) + (hh * cosangle);

        var transpoint = {x:newx, y:newy};
        transpoint.x = width + transpoint.x;
        transpoint.y = height + transpoint.y;
        return transpoint;

    }

    function rotate_pointrad(point, originX, originY, radians) {

        //var new_x_point = old_x_point * cos(Angle) - old_y_point * sin(Angle);
        //var new_y_point = old_y_point * cos(Angle) + old_x_point * sin(Angle);

        var transpx = point.x - originX;
        var transpy = point.y - originY;


        return {
            x: (Math.cos(radians) * (transpx) - Math.sin(radians) * (transpy)) + originX,
            y: (Math.sin(radians) * (transpx) + Math.cos(radians) * (transpy)) + originY
        };
    }

    function rotate_point(point, originX, originY, angle) {
        angle = angle * Math.PI / 180.0;
        return {
            x: Math.cos(angle) * (point.x-originX) - Math.sin(angle) * (point.y-originY) + originX,
            y: Math.sin(angle) * (point.x-originX) + Math.cos(angle) * (point.y-originY) + originY
        };
    }


    function colorisHex(color){

        isHex = false;

        var isHex = /^#[0-9A-F]{6}$/i.test(color);

        if(color.length == 9){
            isHex  = /^#[0-9A-F]{6}[0-9a-f]{0,2}$/i.test('#AABBCC80');
        }


        return isHex;
    }

    function getTransp(color){

        if (colorisHex(color)){
            color = convertHex(color, 100);
        }


        var colors = color.split(",");

        if(colors.length == 0){
            var alpha = 1;
        }else{

            var r = colors[0].split("(");

            r = r[1].trim();
            var g = colors[1].trim();
            var b = colors[2].trim();
            alpha = colors[3].trim();

        }

        return alpha;

    }

    function setTransp(color, opacity) {
        var colors = color.split(",");
        var r = colors[0].split("(");

        if(r[1] == undefined){
            return;
        }

        r = r[1].trim();
        var g = colors[1].trim();
        var b = colors[2].trim();
        var alpha = colors[3].trim();

        return "rgba(" + r + "," + g + "," + b + "," + opacity / 100 + ")";


    }

    //Short code
    function matchRuleShort(str, rule) {

        var escape = rule.split("$").join("\\$");

        var lookfor = escape.split("*").join(".*");

        return new RegExp("^" + lookfor + "$", "i").test(str);

        //return new RegExp("^" + rule.split("*").join(".*") + "$").test(str);
    }

    function matchRuleLong(str, rule) {
        return new RegExp("^[a-zA-Z0-9!@#$&()\\-`.+,/\"]*$" + rule.split("*").join(".*") + "$").test(str);
    }

    function rgbToHex(color) {
        var bg = color.match(/^rgb\((\d+),\s*(\d+),\s*(\d+)\)$/);

        function hex(x) {
            return ("0" + parseInt(x).toString(16)).slice(-2);
        }

        return "#" + hex(bg[1]) + hex(bg[2]) + hex(bg[3]);
    }

    function convertHex(hex, opacity) {


        hex = hex.replace('#', '');
        var r = parseInt(hex.substring(0, 2), 16);
        var g = parseInt(hex.substring(2, 4), 16);
        var b = parseInt(hex.substring(4, 6), 16);

        if (hex.length == 8){

            r = parseInt(hex.substring(0, 2), 16);
            g = parseInt(hex.substring(2, 4), 16);
            b = parseInt(hex.substring(4, 6), 16);

            //opacity = parseInt(hex.substring(6, 8), 16);
            //opacity = Math.round((opacity / 255) * 100);


        }

        var result = 'rgba(' + r + ',' + g + ',' + b + ',' + opacity / 100 + ')';
        return result;
    }

    function convertHexrgb(hex) {
        hex = hex.replace('#', '');
        var r = parseInt(hex.substring(0, 2), 16);
        var g = parseInt(hex.substring(2, 4), 16);
        var b = parseInt(hex.substring(4, 6), 16);

        return {
            r : r,
            g : g,
            b : b
        };

    }


//sharpen canvas image

function sharpen(ctx, w, h, mix) {

    var weights =  [0, -1, 0,  -1, 5, -1,  0, -1, 0],
        katet = Math.round(Math.sqrt(weights.length)),
        half = (katet * 0.5) |0,
        dstData = ctx.createImageData(w, h),
        dstBuff = dstData.data,
        srcBuff = ctx.getImageData(0, 0, w, h).data,
        y = h,
        x = w;

    while(y--) {

        x = w;

        while(x--) {

            var sy = y,
                sx = x,
                dstOff = (y * w + x) * 4,
                r = 0, g = 0, b = 0, a = 0;

            for (var cy = 0; cy < katet; cy++) {
                for (var cx = 0; cx < katet; cx++) {

                    var scy = sy + cy - half;
                    var scx = sx + cx - half;

                    if (scy >= 0 && scy < h && scx >= 0 && scx < w) {

                        var srcOff = (scy * w + scx) * 4;
                        var wt = weights[cy * katet + cx];

                        r += srcBuff[srcOff] * wt;
                        g += srcBuff[srcOff + 1] * wt;
                        b += srcBuff[srcOff + 2] * wt;
                        a += srcBuff[srcOff + 3] * wt;
                    }
                }
            }

            dstBuff[dstOff] = r * mix + srcBuff[dstOff] * (1 - mix);
            dstBuff[dstOff + 1] = g * mix + srcBuff[dstOff + 1] * (1 - mix);
            dstBuff[dstOff + 2] = b * mix + srcBuff[dstOff + 2] * (1 - mix)
            dstBuff[dstOff + 3] = srcBuff[dstOff + 3];
        }
    }

    ctx.putImageData(dstData, 0, 0);
}


// scales the canvas by (float) scale < 1
// returns a new canvas containing the scaled image.




function downScaleCanvas(cv, scale) {
    if (!(scale < 1) || !(scale > 0)) throw ('scale must be a positive number <1 ');
    var sqScale = scale * scale; // square scale = area of source pixel within target
    var sw = cv.width; // source image width
    var sh = cv.height; // source image height
    var tw = Math.ceil(sw * scale); // target image width
    var th = Math.ceil(sh * scale); // target image height
    var sx = 0, sy = 0, sIndex = 0; // source x,y, index within source array
    var tx = 0, ty = 0, yIndex = 0, tIndex = 0; // target x,y, x,y index within target array
    var tX = 0, tY = 0; // rounded tx, ty
    var w = 0, nw = 0, wx = 0, nwx = 0, wy = 0, nwy = 0; // weight / next weight x / y
    // weight is weight of current source point within target.
    // next weight is weight of current source point within next target's point.
    var crossX = false; // does scaled px cross its current px right border ?
    var crossY = false; // does scaled px cross its current px bottom border ?
    var sBuffer = cv.getContext('2d').getImageData(0, 0, sw, sh).data; // source buffer 8 bit rgba
    var tBuffer = new Float32Array(4 * sw * sh); // target buffer Float32 rgb
    var sR = 0, sG = 0,  sB = 0; // source's current point r,g,b
    // untested !
    var sA = 0;  //source alpha

    for (sy = 0; sy < sh; sy++) {
        ty = sy * scale; // y src position within target
        tY = 0 | ty;     // rounded : target pixel's y
        yIndex = 4 * tY * tw;  // line index within target array
        crossY = (tY != (0 | ty + scale));
        if (crossY) { // if pixel is crossing botton target pixel
            wy = (tY + 1 - ty); // weight of point within target pixel
            nwy = (ty + scale - tY - 1); // ... within y+1 target pixel
        }
        for (sx = 0; sx < sw; sx++, sIndex += 4) {
            tx = sx * scale; // x src position within target
            tX = 0 |  tx;    // rounded : target pixel's x
            tIndex = yIndex + tX * 4; // target pixel index within target array
            crossX = (tX != (0 | tx + scale));
            if (crossX) { // if pixel is crossing target pixel's right
                wx = (tX + 1 - tx); // weight of point within target pixel
                nwx = (tx + scale - tX - 1); // ... within x+1 target pixel
            }
            sR = sBuffer[sIndex    ];   // retrieving r,g,b for curr src px.
            sG = sBuffer[sIndex + 1];
            sB = sBuffer[sIndex + 2];
            sA = sBuffer[sIndex + 3];

            if (!crossX && !crossY) { // pixel does not cross
                // just add components weighted by squared scale.
                tBuffer[tIndex    ] += sR * sqScale;
                tBuffer[tIndex + 1] += sG * sqScale;
                tBuffer[tIndex + 2] += sB * sqScale;
                tBuffer[tIndex + 3] += sA * sqScale;
            } else if (crossX && !crossY) { // cross on X only
                w = wx * scale;
                // add weighted component for current px
                tBuffer[tIndex    ] += sR * w;
                tBuffer[tIndex + 1] += sG * w;
                tBuffer[tIndex + 2] += sB * w;
                tBuffer[tIndex + 3] += sA * w;
                // add weighted component for next (tX+1) px
                nw = nwx * scale
                tBuffer[tIndex + 4] += sR * nw; // not 3
                tBuffer[tIndex + 5] += sG * nw; // not 4
                tBuffer[tIndex + 6] += sB * nw; // not 5
                tBuffer[tIndex + 7] += sA * nw; // not 6
            } else if (crossY && !crossX) { // cross on Y only
                w = wy * scale;
                // add weighted component for current px
                tBuffer[tIndex    ] += sR * w;
                tBuffer[tIndex + 1] += sG * w;
                tBuffer[tIndex + 2] += sB * w;
                tBuffer[tIndex + 3] += sA * w;
                // add weighted component for next (tY+1) px
                nw = nwy * scale
                tBuffer[tIndex + 4 * tw    ] += sR * nw; // *4, not 3
                tBuffer[tIndex + 4 * tw + 1] += sG * nw; // *4, not 3
                tBuffer[tIndex + 4 * tw + 2] += sB * nw; // *4, not 3
                tBuffer[tIndex + 4 * tw + 3] += sA * nw; // *4, not 3
            } else { // crosses both x and y : four target points involved
                // add weighted component for current px
                w = wx * wy;
                tBuffer[tIndex    ] += sR * w;
                tBuffer[tIndex + 1] += sG * w;
                tBuffer[tIndex + 2] += sB * w;
                tBuffer[tIndex + 3] += sA * w;
                // for tX + 1; tY px
                nw = nwx * wy;
                tBuffer[tIndex + 4] += sR * nw; // same for x
                tBuffer[tIndex + 5] += sG * nw;
                tBuffer[tIndex + 6] += sB * nw;
                tBuffer[tIndex + 7] += sA * nw;
                // for tX ; tY + 1 px
                nw = wx * nwy;
                tBuffer[tIndex + 4 * tw    ] += sR * nw; // same for mul
                tBuffer[tIndex + 4 * tw + 1] += sG * nw;
                tBuffer[tIndex + 4 * tw + 2] += sB * nw;
                tBuffer[tIndex + 4 * tw + 3] += sA * nw;
                // for tX + 1 ; tY +1 px
                nw = nwx * nwy;
                tBuffer[tIndex + 4 * tw + 4] += sR * nw; // same for both x and y
                tBuffer[tIndex + 4 * tw + 5] += sG * nw;
                tBuffer[tIndex + 4 * tw + 6] += sB * nw;
                tBuffer[tIndex + 4 * tw + 7] += sA * nw;
            }
        } // end for sx
    } // end for sy

    // create result canvas
    var resCV = document.createElement('canvas');
    resCV.width = tw;
    resCV.height = th;
    var resCtx = resCV.getContext('2d');

    //setSmoothingEnabledEx(false, resCtx);

    var imgRes = resCtx.getImageData(0, 0, tw, th);
    var tByteBuffer = imgRes.data;
    // convert float32 array into a UInt8Clamped Array
    var pxIndex = 0; //
    for (sIndex = 0, tIndex = 0; pxIndex < tw * th; sIndex += 4, tIndex += 4, pxIndex++) {
        tByteBuffer[tIndex] = Math.ceil(tBuffer[sIndex]);
        tByteBuffer[tIndex + 1] = Math.ceil(tBuffer[sIndex + 1]);
        tByteBuffer[tIndex + 2] = Math.ceil(tBuffer[sIndex + 2]);
        tByteBuffer[tIndex + 3] = Math.ceil(tBuffer[sIndex + 3]);
    }
    // writing result to canvas.
    resCtx.putImageData(imgRes, 0, 0);
    //sharpen(resCtx, tw, th, 0.8);
    sBuffer = null;
    tByteBuffer = null;
    tBuffer = null;
    return resCV;
}

    function getBase64ImageString(img){
        // Create an empty canvas element
        var canvas = document.createElement("canvas");
        canvas.width = img.width;
        canvas.height = img.height;

        // Copy the image contents to the canvas
        var ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0);

        // Get the data-URL formatted image
        // Firefox supports PNG and JPEG. You could check img.src to
        // guess the original format, but be aware the using "image/jpg"
        // will re-encode the image.
        var dataURL = canvas.toDataURL("image/png");

        //var pos = "data:image/png;base64,"
        //return dataURL.replace(/^data:image\/(png|jpg);base64,/, "");

        return dataURL;

    }

