    function wrapText (context, text, x, y, maxWidth, lineHeight) {

        var bNeedsplit = true;
        var line = '',
            lineCount = 0,
            i,
            test,
            metrics;

        var crlines = text.split('\n');
        var words = [];
        var splitwords = [];

        for (var crn = 0;crn < crlines.length;crn++){
            line = '';
            lineCount = 0;
            i = 0;
            var metrics = context.measureText(crlines[crn]);
            if (metrics.width > maxWidth ){
                words = words.concat(crlines[crn].split(' '));
                words.push('\n');
            }else{
                words.push(crlines[crn]);
                words.push('\n');

            }


        }

        for (i = 0; i < words.length; i++) {

            if(words[i] != '\n'){
                var splitresult = splitstring(context, words[i], maxWidth,splitwords);

                while(splitresult.bNeedSplit){
                    splitresult = splitstring(context, splitresult.remainer, maxWidth,splitwords);
                }
            }else{
                splitwords.push(words[i]);
            }


        }

        var bConcat = true;
        for (i = 0; i < splitwords.length; i++) {
            if(splitwords[i] != '\n'){

                test = line + splitwords[i] + ' ';

                metrics = context.measureText(test);

                if (metrics.width > maxWidth && i > 0) {
                    context.fillText(line, x, y);
                    line = splitwords[i] + ' ';
                    y += lineHeight;
                    lineCount++;
                }
                else {
                    line = test;
                }

            }else{
                bConcat = false;
                context.fillText(line, x, y);
                line = '';
                y += lineHeight;

            }

        }

        /*context.fillText(line, x, y);
        y += lineHeight;*/

        //var words = text.split(' ');


    }



    function wordWrap(str, maxWidth) {
        var newLineStr = "\n";
        var done = false;
        var res = '';
        do {
            var found = false;
            // Inserts new line at first whitespace of the line
            for (var i = maxWidth - 1; i >= 0; i--) {
                if (testWhite(str.charAt(i))) {
                    res = res + [str.slice(0, i), newLineStr].join('');
                    str = str.slice(i + 1);
                    found = true;
                    break;
                }
            }
            // Inserts new line at maxWidth position, the word is too long to wrap
            if (!found) {
                res += [str.slice(0, maxWidth), newLineStr].join('');
                str = str.slice(maxWidth);
            }

            if (str.length < maxWidth)
                done = true;
        } while (!done);

        return res + str;
    }

    function testWhite(x) {
        var white = new RegExp(/^\s$/);
        return white.test(x.charAt(0));
    }

