    function decimalToHex(d) {
        var hex = Number(d).toString(16);
        hex = "000000".substr(0, 6 - hex.length) + hex;
        hex = hex.toUpperCase();
        hex = "#" + hex;
        return hex;
    }

    function getDiagonal(width, height){
        var dimwsq = Math.pow(width, 2);
        var dimhsq = Math.pow(height, 2);
        var dimdiag = Math.sqrt((dimwsq + dimhsq));

        return dimdiag;

    }

    function getCalloutBox(x,y, scale, arrowpos){



        //if (markupobject.arrowTextPos == TextArrowPosLeft){

        if (scale){
            var textbh = ((defaultFont.height * scale) / 0.75);
            var nCalloutWidthScaled = nCalloutWidth * scale;

        }else{
            textbh = (defaultFont.height  / 0.75);
            nCalloutWidthScaled = nCalloutWidth;
        }

        if(arrowpos){
            if (arrowpos == TextArrowPosLeft){
                y = y - (textbh * 0.5);
                //x = x;
            }else if (arrowpos == TextArrowPosRight){
                x = x - nCalloutWidthScaled;
                y = y - (textbh * 0.5);

            }else if(arrowpos == TextArrowPosTop){

                x = x - (nCalloutWidthScaled * 0.5);
                y = y - textbh;

            }else if(arrowpos == TextArrowPosBottom){
                x = x - (nCalloutWidthScaled * 0.5);
                //box.y = height;

            }
        }


        //var textrect = {x : x, y :  y, w : nCalloutWidth, h : textbh};
        return {x : x, y :  y, w : nCalloutWidthScaled, h : textbh};



    }


    function getCurrentPageOffset(){

        var offset = {x : 0, y : 0};

        var pixelRatio = getPixelRatio();

        if(docpagNotReady()){
            return offset;
        }


        if (DocObj.getCurrentpage().usevectorxml) {

            offset.x = DocObj.getCurrentpage().dxvector;
            offset.y = DocObj.getCurrentpage().dyvector;

        } else if (DocObj.getCurrentpage().usepdfjs) {

            offset.x = DocObj.getCurrentpage().dxpdf;
            offset.y = DocObj.getCurrentpage().dypdf;

            offset.x *= pixelRatio;
            offset.y *= pixelRatio;

        } else {

            offset.x = DocObj.getCurrentpage().dx;


            offset.y = DocObj.getCurrentpage().dy;
        }

        if(DocObj.getCurrentpage().usevector3Dxml){
            offset.x = canvasowidth * 0.5;
            offset.y = canvasoheight * 0.5;

        }


        return offset;

    }

