    function MousePosradiusdrwext(centre, mousepos) {

        var bIswithin = false;

        if(docpagNotReady()){
            return bIswithin;
        }


        var xdiff = Math.max(centre.x, mousepos.x) - Math.min(centre.x, mousepos.x);
        var ydiff = Math.max(centre.y, mousepos.y) - Math.min(centre.y, mousepos.y);

        var radius = getDiagonal(xdiff, ydiff);

        var radiusnegx = centre.x - radius;
        var radiusposx = centre.x + radius;
        var radiusnegy = centre.y - radius;
        var radiusposy = centre.y + radius;


        if(DocObj.getCurrentpage().getpageRotation() == 0){

            if (radiusnegx > DocObj.getCurrentpage().startx && radiusposx < DocObj.getCurrentpage().endx){
                if(radiusnegy > DocObj.getCurrentpage().starty && radiusposy < DocObj.getCurrentpage().endy){
                    bIswithin = true;
                }

            }
            if (bIswithin){
                if (mousepos.x > DocObj.getCurrentpage().startx && mousepos.x < DocObj.getCurrentpage().endx) {
                    if (mousepos.y > DocObj.getCurrentpage().starty && mousepos.y < DocObj.getCurrentpage().endy) {
                        bIswithin = true;
                    }
                }
            }

        }else{
            var rotrect = DocObj.getCurrentpage().rotatedRect();

            if (radiusnegx > rotrect.x && radiusposx < rotrect.w){
                if(radiusnegy > rotrect.y && radiusposy < rotrect.h){
                    bIswithin = true;
                }
            }
            if(bIswithin){
                if (mousepos.x > rotrect.x && mousepos.x < rotrect.w) {
                    if (mousepos.y > rotrect.y && mousepos.y < rotrect.h) {
                        bIswithin = true;
                    }
                }
            }
        }

        if (DocObj.getCurrentpage().usevector3Dxml) {

            bIswithin = true;
        }

        return bIswithin;
    }

