    function parseXML(text) {
        var doc = null;

        if(window.DOMParser){
            var parser = new DOMParser();
            doc = parser.parseFromString(text, "text/xml");
        }else if(window.ActiveXObject){
            doc = new ActiveXObject("Microsoft.XMLDOM");
            doc.async = "false";
            doc.loadXML(text);
        }else{
            throw new Error("Cannot parse XML");
        }
        return doc;
    }

