    function getHatch(ctx, type, color) {


        pattern = document.createElement('canvas');

        pattern.width = 16;
        pattern.height = 16;

        var pctx = pattern.getContext('2d');

        drawhatchtype(pctx, type, color);


        var HatchPtrn = ctx.createPattern(pattern, "repeat");
        return HatchPtrn;

    }




    function getURLFile(s){
        var path = "";
        var sp = s.split('/');
        for (var i = 0; i < sp.length - 1; i++) {
            path += sp[i] + "/";
        }
        //var file = sp[sp.length-1];
        //alert(file);
        return sp[sp.length-1];

    }

    function getURLPath(s) {
        var path = "";

        if(s){
            var sp = s.split('/');
            for (var i = 0; i < sp.length - 1; i++) {
                path += sp[i] + "/";
            }

            if (bUseID){
                path = xmlurlrel;
            }
        }
        //var file = sp[sp.length-1];
        //alert(file);
        return path;
    }

    function getPath(s) {
        var path = "";
        var sp = s.split('\\');
        for (var i = 0; i < sp.length - 1; i++) {
            path += sp[i] + "\\";
        }
        //var file = sp[sp.length-1];
        //alert(file);
        if(!path) {
            path = s;
        }

        return path;

    }

    function getFileName(s) {
     var path = "";
     var file = "";
      if(s){
        if(s.indexOf('https://') > -1){
            file = getURLFile(s);
         }else if (s.indexOf('http://') > -1){
            file = getURLFile(s);
         }else{
            var sp = s.split('\\');
            for (var i = 0; i < sp.length - 1; i++) {
                    path += sp[i] + "\\";
                }
            file = sp[sp.length - 1];
            //alert(file);
         }
      }
     return file;

    }

