    function getUnitArea(value) {


        //var Unitofmeasure = DocObj.getCurrentpage().Unitofmeasure;

        var Unitofmeasure = DocObj.getCurrentpage().scaleObject.Unitofmeasure;
        if(markupForScale) {
            Unitofmeasure = markupForScale.scaleObject.Unitofmeasure;
        }


        var dimValue = 0;
        var dpi = DocObj.getCurrentpage().DPI;
        var DPmm = dpi / 25.4;
        var DPInch = dpi;


        //var mscale = MeasureScale;
        var mscale = DocObj.getCurrentpage().scaleObject.getMeasureScale();

        if(markupForScale) {
            mscale = markupForScale.scaleObject.getMeasureScale();
        }



        if (mscale ==  undefined){
            mscale = MeasureScale;
        }

        //var unit = currentglobalunit;
        if (DocObj.getCurrentpage().usepdfjs) {
            dpi = 72;
            DPmm = dpi / 25.4;
            DPInch = dpi;
        }

        var Dpmmsquare = DPmm * DPmm;
        var DPInchSquare = DPInch * DPInch;
        var measureScaleSquared = mscale * mscale;
        if (DocObj.getCurrentpage().usevectorxml) {
            var mainimagesquare = DocObj.getCurrentpage().OriginalScale * DocObj.getCurrentpage().OriginalScale;
        } else if (DocObj.getCurrentpage().usepdfjs) {
            mainimagesquare = DocObj.getCurrentpage().OriginalScale * DocObj.getCurrentpage().OriginalScale;
        } else {
            mainimagesquare = DocObj.getCurrentpage().MainImageScaling * DocObj.getCurrentpage().MainImageScaling;
        }


        var dscalesquare = DocObj.getCurrentpage().dscale * DocObj.getCurrentpage().dscale;

        if (DocObj.getCurrentpage().usevectorxml) {
            dscalesquare = DocObj.getCurrentpage().dscalevector * DocObj.getCurrentpage().dscalevector;
        } else if (DocObj.getCurrentpage().usepdfjs) {
            dscalesquare = (DocObj.getCurrentpage().curpagescale * DocObj.getCurrentpage().dscalepdf) * (DocObj.getCurrentpage().curpagescale * DocObj.getCurrentpage().dscalepdf);
        }

        //var scalefactor = DocObj.getCurrentpage().dscale / this.scaling;
        //var scalefactorsquare = scalefactor * scalefactor;
        var orignalscalesquare = DocObj.getCurrentpage().OriginalScale * DocObj.getCurrentpage().OriginalScale;


        //dimValue = ((value  / mainimagesquare) / dscalesquare)*measureScaleSquared;//*scalefactorsquare;
        //change to make value independent of current zoom factor.
        dimValue = (value / mainimagesquare) * measureScaleSquared; //*scalefactorsquare;
        // dimValue = dimValue / (unitscale * unitscale);

        // dimValue = dimValue / (unitscale * unitscale);

        //var unitScaleValue = DocObj.getCurrentpage().getUnitScale();

        var unitScaleValue = DocObj.getCurrentpage().scaleObject.getUnitScale();

        if(markupForScale) {
            unitScaleValue = markupForScale.scaleObject.getUnitScale();
        }


        dimValue = dimValue / (unitScaleValue * unitScaleValue);





        if (dpi != 0) {
            switch (Unitofmeasure) {
                case 1:
                    dimValue = dimValue / Dpmmsquare;
                    break;
                case 2:
                    dimValue = dimValue / DPInchSquare;
                    break;
                case 3:
                    //dimValue = dimValue;
                    break;
            }


        } else {
            if (!DocObj.getCurrentpage().usevectorxml) {
                dimValue = dimValue / orignalscalesquare;
            }

        }
        return dimValue;
    }

    function getScreenDim(length, munit){

        var pixelwidth = 0;

        if(docpagNotReady()){
            return pixelwidth;
        }

        var dpi = DocObj.getCurrentpage().DPI;
        //var Unitofmeasure = DocObj.getCurrentpage().Unitofmeasure;
        var Unitofmeasure = DocObj.getCurrentpage().scaleObject.Unitofmeasure;
        var DPmm = dpi / 25.4;
        var DPInch = dpi;

        /*if(DocObj.getCurrentpage().usevectorxml){
            dpi = 0;
        }*/

        if (DocObj.getCurrentpage().usepdfjs) {
            dpi = 72;
            DPmm = dpi / 25.4;
            DPInch = dpi;
        }

        length = length * unitscale;
        //length *= DocObj.getCurrentpage().getdscale();

        //var mscale = MeasureScale;
        var mscale = DocObj.getCurrentpage().scaleObject.getMeasureScale();


        if(markupForScale) {
            mscale = markupForScale.scaleObject.getMeasureScale();
        }

        if (mscale == undefined){
            mscale = MeasureScale;
        }



        if (DocObj.getCurrentpage().usevectorxml || DocObj.getCurrentpage().usepdfjs || DocObj.getCurrentpage().usevector3Dxml) {
            //length = ((value / DocObj.getCurrentpage().OriginalScale)) * mscale;
            pixelwidth = (length / mscale) * DocObj.getCurrentpage().OriginalScale;
        } else {
            //length = ((value / DocObj.getCurrentpage().MainImageScaling)) * mscale;
            pixelwidth = (length / mscale) * DocObj.getCurrentpage().MainImageScaling;
        }



        //pixelwidth = pixelwidth * DPmm;

        if (dpi != 0) {
            switch (Unitofmeasure) {
                case 1:
                    //dimValue = dimValue / DPmm;
                    pixelwidth = pixelwidth * DPmm;
                    break;
                case 2:
                    //dimValue = dimValue / DPInch;
                    pixelwidth = pixelwidth * DPInch;
                    break;
                case 3:
                    //dimvalue= dimvalue;
                    break;
            }


        } else {
            /*if (!DocObj.getCurrentpage().usevectorxml) {
                pixelwidth = pixelwidth * DocObj.getCurrentpage().getdscale();

            }*/


        }

        return pixelwidth;

    }

    var gcd = function(a, b) {
        if (b < 0.0000001) return a;                // Since there is a limited precision we need to limit the value.

        return gcd(b, Math.floor(a % b));           // Discard any fractions due to limitations in precision.
    };

    function getUnitlengthRemainder(value){
        var dimValue = 0;
        var remainder = 0;
        var remainddec = 0;


        if(docpagNotReady()){
            return;
        }

        var dpi = DocObj.getCurrentpage().DPI;
        var DPmm = dpi / 25.4;
        var DPInch = dpi;

        var mscale = DocObj.getCurrentpage().scaleObject.getMeasureScale();
        if(markupForScale) {
            mscale = markupForScale.scaleObject.getMeasureScale();
        }


        if (mscale ==  undefined){
            mscale = MeasureScale;
        }

        if (DocObj.getCurrentpage().usepdfjs) {
            dpi = 72;
            DPmm = dpi / 25.4;
            DPInch = dpi;
        }

        if (DocObj.getCurrentpage().usevectorxml || DocObj.getCurrentpage().usepdfjs || DocObj.getCurrentpage().usevector3Dxml) {
            dimValue = ((value / DocObj.getCurrentpage().OriginalScale)) * mscale; // * scalefactor;
        } else {
            dimValue = ((value / DocObj.getCurrentpage().MainImageScaling)) * mscale; // * scalefactor;
        }


        //dimValue = dimValue / unitscale;

        var unitScaleValue = DocObj.getCurrentpage().scaleObject.getUnitScale();
        if(markupForScale) {
            unitScaleValue = markupForScale.scaleObject.getUnitScale();
        }


        dimValue = dimValue / unitScaleValue;

        if (dpi != 0) {

            dimValue = dimValue / DPInch;


        } else {
            if (!DocObj.getCurrentpage().usevectorxml) {
                dimValue = dimValue / DocObj.getCurrentpage().OriginalScale;
            }


        }

        var rnddimValue = Math.floor(dimValue / unitscale);
        remainder = dimValue % unitscale;
        var rndrem = Math.floor(remainder);
        var remainddec = remainder - rndrem;

        remainddec = Math.round(remainddec * nFractionRes) / nFractionRes;

        var fractionlimit = 1 / nFractionRes;

        if (remainddec > fractionlimit){
            var len = remainddec.toString().length - 2;

            var nDenominator = Math.pow(10, len);
            var nNumerator = remainddec * nDenominator;

            var divisor = gcd(nNumerator, nDenominator);    // Should be 5

            nNumerator /= divisor;                         // Should be 687
            nDenominator /= divisor;                       // Should be 2000
            var nretnumerator = Math.floor(nNumerator);
            var nretdenominator = Math.floor(nDenominator);

        }else{

            nretnumerator = 0;
            nretdenominator = 0;

        }


        return {quot : rnddimValue, rem : rndrem, remdec : remainddec, numerator : nretnumerator, denominator : nretdenominator};
    }

    function getUnitlength(value) {
        var dimValue = 0;

        if(docpagNotReady()){
            return dimValue;
        }

        //var Unitofmeasure = DocObj.getCurrentpage().Unitofmeasure;

        var Unitofmeasure = DocObj.getCurrentpage().scaleObject.Unitofmeasure;
        if(markupForScale) {
            Unitofmeasure = markupForScale.scaleObject.Unitofmeasure;
        }


        var remainder = 0;
        var dpi = DocObj.getCurrentpage().DPI;
        var DPmm = dpi / 25.4;
        var DPInch = dpi;

        //var mscale = MeasureScale;

        var mscale = DocObj.getCurrentpage().scaleObject.getMeasureScale();
        if(markupForScale) {
            mscale = markupForScale.scaleObject.getMeasureScale();
        }


        if (mscale ==  undefined){
            mscale = MeasureScale;
        }

        //var scalefactor = DocObj.getCurrentpage().dscale / this.scaling;

        //dimValue = ((value  / DocObj.getCurrentpage().MainImageScaling) / DocObj.getCurrentpage().dscale)*MeasureScale;// * scalefactor;
        //value without the scale factor to estblish value independent from zoom factor.
        if (DocObj.getCurrentpage().usepdfjs) {
            dpi = 72;
            DPmm = dpi / 25.4;
            DPInch = dpi;
        }

        if (DocObj.getCurrentpage().usevectorxml || DocObj.getCurrentpage().usepdfjs || DocObj.getCurrentpage().usevector3Dxml) {
            dimValue = ((value / DocObj.getCurrentpage().OriginalScale)) * mscale; // * scalefactor;
        } else {
            dimValue = ((value / DocObj.getCurrentpage().MainImageScaling)) * mscale; // * scalefactor;
        }

        //dimValue = dimValue / unitscale;
        //remainder = dimValue % unitscale;

        //var unitScaleValue = DocObj.getCurrentpage().getUnitScale();

        var unitScaleValue = DocObj.getCurrentpage().scaleObject.getUnitScale();
        if(markupForScale) {
            unitScaleValue = markupForScale.scaleObject.getUnitScale();
        }


        dimValue = dimValue / unitScaleValue;
        remainder = dimValue % unitScaleValue;


        if (dpi != 0) {
            switch (Unitofmeasure) {
                case 1:
                    dimValue = dimValue / DPmm;
                    break;
                case 2:
                    dimValue = dimValue / DPInch;
                    break;
                case 3:
                    //dimvalue= dimvalue;
                    break;
            }


        } else {
            if (!DocObj.getCurrentpage().usevectorxml) {
                dimValue = dimValue / DocObj.getCurrentpage().OriginalScale;
            }


        }
        return dimValue;
    }

