    function MarkupRedoSingle(localmarkup){

        var found = false;

        if(localmarkup){

            if(!localmarkup.bredoonly){
                DocObj.markupundolist.push(localmarkup);
            }else{
                DocObj.markupredolist.push(localmarkup);

                localmarkup = getFirstRedoOnly(DocObj.markupredolist);
            }

        }

        if (localmarkup != undefined) {
            var id = localmarkup.markupnumber;
            var curmarkup = 0;

            for (curmarkup = 0; curmarkup < DocObj.markuplist.length; curmarkup++) {
                if (DocObj.markuplist[curmarkup] != null) {
                    if (DocObj.markuplist[curmarkup].markupnumber == localmarkup.markupnumber) {

                        localmarkup.PerformUndo(DocObj.markuplist[curmarkup], DocObj);
                        //.PerformUndo(localmarkup);
                        found = true;
                    }
                }
            }
            if (!found) {

                localmarkup.PerformUndo(undefined,DocObj);


            }

        }


    }

    function MarkupRedo() {

        if(DocObj == null || DocObj == undefined){
            return;
        }


        var localmarkup = DocObj.markupredolist.pop();

        //console.log(DocObj.markupredolist.length);

        if(localmarkup){
            //localmarkup.bcurstate = true;
            while (localmarkup.bcurstate && DocObj.markupredolist.length > 0){
                DocObj.markupundolist.push(localmarkup);
                localmarkup = DocObj.markupredolist.pop();
            }

        }

        if(localmarkup){

            if(localmarkup.bMultiOp){


                MarkupRedoSingle(localmarkup);

                var tempredolist = [];
                var id = localmarkup.multiOpId;
                var ui = 0;

                for (ui=0; ui < DocObj.markupredolist.length; ui++){

                    if(DocObj.markupredolist[ui].bMultiOp && DocObj.markupredolist[ui].multiOpId == id){
                        MarkupRedoSingle(DocObj.markupredolist[ui]);
                    }else{
                        tempredolist.push(DocObj.markupredolist[ui]);
                    }
                }

                DocObj.markupredolist = tempredolist;


            }else{
                MarkupRedoSingle(localmarkup);
            }

        }


        if(DocObj.markupredolist.length == 0){
            if (RxCore_GUI_UndoRedoEmpty != undefined){

                RxCore_GUI_UndoRedoEmpty.listempty(false, true);

            }
        }



    }


