                this.PerformRedo = function(MarkupObj, DocRef){

                    if(undoscope.bcreate){
                        //undoscope.bdelete = true;
                        //undoscope.bcreate = false;
                    }

                    if(undoscope.bdelete){
                        undoscope.bdelete = false;
                        undoscope.bcreate = true;
                    }
                    undoscope.PerformUndo(MarkupObj, DocRef);

                };

                this.PerformUndo = function(MarkupObj, DocRef){

                    if(undoscope.type == 6 && undoscope.subtype == 6){
                        return;
                    }

                    if(undoscope.bcreate){
                        //delete created

                        if(undoscope.bhasArrow && undoscope.markupArrowConnected ){
                            undoremovemarkup(undoscope.markupArrowConnected.markupnumber);
                        }

                        if(MarkupObj){

                            if(MarkupObj.type == 11 || MarkupObj.type == 20){
                                if(MarkupObj.image){
                                    undoscope.image = MarkupObj.image;
                                }

                            }

                        }






                        undoremovemarkup(undoscope.markupnumber);
                        undoscope.bdelete = true;
                        undoscope.bcreate = false;



                        return;
                    }

                    if(undoscope.bdelete){
                        MarkupObj = undoscope.restoreDeleted();

                        if(undoscope.bhasArrow && undoscope.markupArrowConnected ){
                            MarkupObj.markupArrowConnected = undoscope.markupArrowConnected.restoreDeleted();
                            MarkupObj.bhasArrow = true;
                            MarkupObj.markupArrowConnected.textBoxConnected = MarkupObj;
                            MarkupObj.markupArrowConnected.bisTextArrow =  true;

                            undoscope.markupArrowConnected.savetolist = true;
                            //undoscope.markupArrowConnected.bdelete = false;
                            //undoscope.markupArrowConnected.bcreate = true;

                        }

                        if(MarkupObj.type == 8 && MarkupObj.subtype == 2){
                            undoscope.parent.holes.push(MarkupObj);
                        }

                        if(MarkupObj.type == 11 || MarkupObj.type == 20){

                            MarkupObj.image = undoscope.image;
                            MarkupObj.imageloaded = true;
                        }

                        undoscope.savetolist = true;
                        undoscope.bdelete = false;
                        undoscope.bcreate = true;

                        //MarkupObj.savemetolistLoad(DocObj);
                        MarkupObj.setfirstDraw();


                    }


                    if(!MarkupObj){
                        return;
                    }

                    var curpoint = 0;
                    var tempx = 0;
                    var tempy = 0;


                    undoscope.PerformUndoCommon(MarkupObj, DocRef);

                    if(undoscope.bhasArrow && undoscope.markupArrowConnected ){

                        if(MarkupObj.markupArrowConnected != null){
                            undoscope.markupArrowConnected.PerformUndoCommon(MarkupObj.markupArrowConnected, DocRef);
                        }

                    }

                    /*if (undoscope.bdelete) {
                        //delete created
                        undoremovemarkup(undoscope.markupnumber);
                        //UndoObj
                        //remove from docobj markuplist
                    }*/

                };
