                this.calculateDrawAngle = function (rect) {
                    var angleRadians = Math.atan2(rect.h - rect.y, rect.w - rect.x);
                    //normalize to remove negative values
                    if (angleRadians < 0)
                        angleRadians += 2 * Math.PI;
                    markupobject.orthoDrawAngle = angleRadians;
                    markupobject.orthoDrawAngledeg = markupobject.orthoDrawAngle * (180 / Math.PI);
                    //markupobject.orthoDrawAngle = angleRadians * (180 / Math.PI);
                    //calculateOrtho
                };
                this.calculateLength = function(points){

                    var xdiff = Math.max(points[0].x, points[1].x) - Math.min(points[0].x, points[1].x);
                    var ydiff = Math.max(points[0].y, points[1].y) - Math.min(points[0].y, points[1].y);


                    var radius = markupobject.getdiag(xdiff, ydiff);
                    return radius;


                };
                this.calculateOrthoPoints = function(points){

                    //points is an array of two points point is an object with x and y value.

                    var angleRadians = Math.atan2(-(points[1].y - points[0].y), points[1].x - points[0].x);
                    return angleRadians;


                };
                this.getClosestDegree = function(nOrthoDegree, degrees){

                    var resultangle = 0;

                    //var closeforward =  degrees + nOrthoDegree;
                    //var closebackward =  degrees - nOrthoDegree;

                    //var halfdeg = nOrthoDegree * 0.5;
                    //var sections = 360 / nOrthoDegree;

                    var bcontinue = true;
                    var startval = 0;
                    var endval = 360;
                    var curval = 0;
                    var diff = Math.abs(degrees - curval);
                    resultangle = curval;


                    while(bcontinue){
                        curval = curval + nOrthoDegree;
                        var curdiff = Math.abs(degrees - curval);

                        if (curdiff < diff){
                            diff = curdiff;
                            resultangle = curval;
                            if (curval == endval){
                                resultangle = startval;
                            }
                        }
                        if (curval == endval){
                            bcontinue = false;
                        }

                    }



                    return resultangle;


                };
                this.calculateOrthoDraw = function(startpoint, curpoint){
                    var pointLength = markupobject.calculateLength([{x:startpoint.x,y:startpoint.y},{x:curpoint.x,y:curpoint.y}]); //Math.atan2(this.h - this.y, this.w - this.x);
                    var angleRadians = markupobject.calculateOrthoPoints([{x:startpoint.x,y:startpoint.y},{x:curpoint.x,y:curpoint.y}]); //Math.atan2(this.h - this.y, this.w - this


                    if (angleRadians < 0)
                    angleRadians += 2 * Math.PI;
                    var degrees = angleRadians * (180 / Math.PI);

                    var anglesnap = markupobject.getClosestDegree(nOrthoDegree, degrees);

                    var point = markupobject.setAnglelengthUnscaled(startpoint, pointLength, anglesnap, undefined);

                    return point;

                };
                this.calculateOrtho = function (bscale, corner, point) {
                    //angle = atan2(vector2.y, vector2.x) - atan2(vector1.y, vector1.x);
                    //var angle = Math.atan2(this.h, this.w) - Math.atan2(this.y, this.x);
                    var pointLength = markupobject.calculateLength([{x:this.x,y:this.y},{x:point.x,y:point.y}]); //Math.atan2(this.h - this.y, this.w - this.x);
                    var angleRadians = markupobject.calculateOrthoPoints([{x:this.x,y:this.y},{x:this.w,y:this.h}]); //Math.atan2(this.h - this.y, this.w - this.x);
                    var pageangle = DocObj.getCurrentpage().getpageRotation() * (Math.PI / 180);
                    //angleRadians += pageangle;
                    /*if(bscale){
                        switch(corner){
                            case 1 :
                                angleRadians = Math.atan2(point.y - this.y, point.x- this.x);
                                break;
                            case 4 :
                                angleRadians = Math.atan2(this.h - point.y, this.w- point.x);
                                break;
                        }
                    }*/
                    if (angleRadians < 0)
                        angleRadians += 2 * Math.PI;
                    var degrees = angleRadians * (180 / Math.PI);

                    var anglesnap = markupobject.getClosestDegree(nOrthoDegree, degrees);

                    var point = markupobject.setAnglelengthUnscaled({x:this.x,y:this.y}, pointLength, anglesnap, undefined);


                    if (bscale && corner == 1) {
                        //this.y = this.h;
                        this.x = point.w;
                        this.y = point.h;
                    }
                    else {
                        //this.h = this.y;
                        this.w = point.w;
                        this.h = point.h;

                    }

                    //console.log(degrees);
                };
