                this.SetDim3D = function(scalefactor, rotation, pagedx, pagedy){

                    //pagedx = canvasowidth * 0.5;
                    //pagedy = canvasoheight * 0.5;

                    //scalefactor = canvasoheight / this.pageheight;

                    //dimensionmarkupobj.pageheight = canvasoheight;

                    var abswidthandheight = true;

                    this.xscaled = (this.x - this.xoffset) * scalefactor;
                    this.yscaled = (this.y - this.yoffset) * scalefactor;
                    this.wscaled = this.w * scalefactor;
                    this.hscaled = this.h * scalefactor;

                    //this.xscaled += pagedx;
                    //this.yscaled += pagedy;

                    switch (this.type) {
                        case 0: //pencil, marker, eraser

                            this.xscaled += pagedx;
                            this.yscaled += pagedy;
                            this.wscaled = (this.w - this.xoffset) * scalefactor;
                            this.hscaled = (this.h - this.yoffset) * scalefactor;

                            this.wscaled += pagedx;
                            this.hscaled += pagedy;
                            abswidthandheight = true;
                            break;
                        case 1: //polygon

                            this.xscaled += pagedx;
                            this.yscaled += pagedy;
                            this.wscaled = (this.w - this.xoffset) * scalefactor;
                            this.hscaled = (this.h - this.yoffset) * scalefactor;

                            this.wscaled += pagedx;
                            this.hscaled += pagedy;
                            abswidthandheight = true;
                            break;
                        case 2:

                            this.xscaled += pagedx;
                            this.yscaled += pagedy;
                            this.wscaled = (this.w - this.xoffset) * scalefactor;
                            this.hscaled = (this.h - this.yoffset) * scalefactor;

                            this.wscaled += pagedx;
                            this.hscaled += pagedy;
                            abswidthandheight = true;
                            break;
                        case 3: //rectangle
                            this.xscaled += pagedx;
                            this.yscaled += pagedy;

                            abswidthandheight = false;
                            break;
                        case 4: //oval
                            this.xscaled += pagedx;
                            this.yscaled += pagedy;
                            if (this.subtype == 1) {
                                this.wscaled = (this.w - this.xoffset) * scalefactor;
                                this.hscaled = (this.h - this.yoffset) * scalefactor;
                                this.wscaled += pagedx;
                                this.hscaled += pagedy;
                                abswidthandheight = true;
                            }
                            else {
                                abswidthandheight = false;
                            }

                            break;
                        case 5:
                            this.xscaled += pagedx;
                            this.yscaled += pagedy;

                            abswidthandheight = false;
                            break;
                        case 6: //line arrow
                            this.xscaled += pagedx;
                            this.yscaled += pagedy;
                            this.wscaled = (this.w - this.xoffset) * scalefactor;
                            this.hscaled = (this.h - this.yoffset) * scalefactor;
                            this.wscaled += pagedx;
                            this.hscaled += pagedy;

                            abswidthandheight = true;
                            break;
                        case 7: //dimension line
                            this.xscaled += pagedx;
                            this.yscaled += pagedy;
                            this.wscaled = (this.w - this.xoffset) * scalefactor;
                            this.hscaled = (this.h - this.yoffset) * scalefactor;
                            this.wscaled += pagedx;
                            this.hscaled += pagedy;

                            abswidthandheight = true;
                            break;
                        case 8:
                            this.xscaled += pagedx;
                            this.yscaled += pagedy;

                            this.wscaled = (this.w - this.xoffset) * scalefactor;
                            this.hscaled = (this.h - this.yoffset) * scalefactor;
                            this.wscaled += pagedx;
                            this.hscaled += pagedy;

                            abswidthandheight = true;
                            break;
                        case 9: //text
                            this.xscaled += pagedx;
                            this.yscaled += pagedy;

                            if (this.subtype == 1 || this.subtype == 2) {
                                abswidthandheight = false;
                            }
                            else {
                                this.wscaled = this.textwidth; // * scalefactor;
                                this.hscaled = this.textheight * scalefactor;
                            }
                            //width and height determined by text and font set in draw function
                            abswidthandheight = false;
                            break;
                        case 10:
                            this.xscaled += pagedx;
                            this.yscaled += pagedy;

                            if (bUseFixedScale) {
                                this.wscaled = this.w * markupobject.fixedscaleFactor;
                                this.hscaled = this.h * markupobject.fixedscaleFactor;
                            }
                            else {
                                this.wscaled = this.w * scalefactor;
                                this.hscaled = this.h * scalefactor;
                            }
                            abswidthandheight = false;
                            break;
                        //image
                        case 11:


                            if (this.subtype == 2){

                                this.wscaled = this.w;
                                this.hscaled = this.h;

                            }else{
                                this.wscaled = this.w * scalefactor;
                                this.hscaled = this.h * scalefactor;
                            }

                            this.xscaled += pagedx;
                            this.yscaled += pagedy;


                            abswidthandheight = false;
                            break;
                        case 12:
                            this.xscaled += pagedx;
                            this.yscaled += pagedy;

                            abswidthandheight = false;
                            break;

                        case 13:


                            this.xscaled += pagedx;
                            this.yscaled += pagedy;

                            if (bUseFixedScale) {
                                this.wscaled = this.w * markupobject.fixedscaleFactor;
                                this.hscaled = this.h * markupobject.fixedscaleFactor;
                            }

                            break;


                        case 20:


                            if (this.subtype == 2){

                                this.wscaled = this.w;
                                this.hscaled = this.h;

                            }else{
                                this.wscaled = this.w * scalefactor;
                                this.hscaled = this.h * scalefactor;
                            }

                            this.xscaled += pagedx;
                            this.yscaled += pagedy;


                            abswidthandheight = false;
                            break;


                    }

                    this.rotatedrect.x = this.xscaled;
                    this.rotatedrect.y = this.yscaled;
                    this.rotatedrect.w = this.wscaled;
                    this.rotatedrect.h = this.hscaled;


                };
                this.setFirstdrawDim = function(scalefactor, fixedscale, bRasterScale){


                    if(markupobject.pdfannot){
                        var pdfannot = DocObj.getFoxitAnnot(markupobject.pdfannotref);

                        if(pdfannot != undefined){


                          scalefactor = 1;



                          var bpoly = this.type == 1 || this.type == 2 || this.type == 8;


                          if (bpoly) {
                            markupobject.findrectangle();
                          }

                        }
                    }

                    if(scalefactor == 0){
                        scalefactor = 1;
                    }

                    if(fixedscale == 0){
                        fixedscale = 1;
                    }


                    if(isNaN(scalefactor)){
                        scalefactor = 1;
                    }

                    if(isNaN(fixedscale)){
                        fixedscale = 1;
                    }


                    //var mainimagescale = getImageMainscale(pageobject);


                    var mainimagescale = getCurrentPageMainimageScale();

                    var internalscale = scalefactor;


                    if(bNewestFileformat){
                        internalscale = internalscale * mainimagescale;
                    }





                    var fontheight = markupobject.font.height;

                    if(bUseMarkupScaling){
                        internalscale = markupobject.scaling;

                    }


                    if (markupobject.type != 12) {

                        if(bRasterScale){

                            if (bfixedScale && !bUseMarkupScaling){
                                fontheight = Math.round((fontheight * fixedscale) / markupobject.scaling);
                            }else{
                                fontheight = markupobject.font.height;
                            }

                        }else{

                            if (bfixedScale && bNewFileformat && !bUseMarkupScaling){
                                fontheight = Math.round(fontheight * fixedscale);
                            }else{
                                fontheight = Math.round(fontheight * internalscale);
                            }

                        }

                        if (isNaN(markupobject.font.height)) {
                            //markupobject.font.height = 11;
                            //markupobject.font.setHeight(11);
                            fontheight = 11;
                        }


                        markupobject.textheight = fontheight;
                        markupobject.font.setHeight(fontheight);

                    }


                    if (bNewFileformat){


                        if(!bRasterScale){
                            //markupobject.arrowlength = markupobject.arrowlength - markupobject.linewidth;

                            //this.arrowlength = parseInt(xmlDoc.getElementsByTagName('ArrowSize')[0].firstChild.nodeValue);
                            //this.linewidth = parseFloat(xmlDoc.getElementsByTagName('LineWidth')[0].firstChild.nodeValue);



                            if (bfixedScale && !bUseMarkupScaling) {
                                markupobject.linewidth *= fixedscale;
                                markupobject.linewidthSegment *= fixedscale;



                            }
                            else {
                                markupobject.linewidth *= internalscale;
                                markupobject.linewidthSegment *= internalscale;
                            }

                            markupobject.arrowlength = markupobject.arrowlength + markupobject.linewidth;

                        }else{
                            //markupobject.arrowlength = markupobject.arrowlength - markupobject.linewidth;

                            if (bfixedScale && !bUseMarkupScaling) {
                                markupobject.linewidth = (markupobject.linewidth * fixedscale) / internalscale;

                                markupobject.linewidthSegment = (markupobject.linewidthSegment * fixedscale) / internalscale;

                            }

                            markupobject.arrowlength = markupobject.arrowlength + markupobject.linewidth;

                        }

                        if (isNaN(markupobject.linewidth)) {
                            markupobject.linewidth = 1;
                            markupobject.linewidthSegment = linewidthvalueSegment;

                        }

                        if (isNaN(markupobject.arrowlength)) {
                            markupobject.arrowlength = nArrowSize + markupobject.linewidth;
                        }

                        //change to set when page is loaded not from page object.




                    }

                    if (bNewFileformat && !bRasterScale){
                        this.x = (this.x + this.xoffset) * internalscale;
                        this.y = (this.y + this.yoffset) * internalscale;

                        var bCircle = (this.type == 4 && this.subtype == 1 && bNewestFileformat);

                        if (this.type == 0 || this.type == 1 || this.type == 2 || this.type == 6 || this.type == 7 || this.type == 8 || bCircle) {
                            this.w = (this.w + this.xoffset) * internalscale;
                            this.h = (this.h + this.yoffset) * internalscale;
                        }
                        else {
                            if (this.type == 10 && bfixedScale) {
                                this.w *= fixedscale;
                                this.h *= fixedscale;
                            }
                            else {
                                this.w *= internalscale;
                                this.h *= internalscale;
                            }
                        }
                    }



                    if (this.type == 7) {

                        if (bNewFileformat && !bRasterScale){
                            markupobject.leaderoffset *= internalscale;
                        }

                    }
                    if (this.type == 8) {

                        if (bNewFileformat && !bRasterScale) {
                            markupobject.labeloffsetx *= internalscale;
                        }
                        if (bNewFileformat && !bRasterScale) {
                            markupobject.labeloffsety *= internalscale;
                        }
                    }

                    if (this.type == 13) {

                        if (bNewFileformat) {

                            if(!bRasterScale){
                                if (bfixedScale && !bUseMarkupScaling) {
                                    //this.linewidth *= fixedscale;

                                    this.innerRadius *= fixedscale;
                                    this.outerRadius *= fixedscale;

                                }
                                else {

                                    this.innerRadius *= internalscale;
                                    this.outerRadius *= internalscale;

                                    //this.linewidth *= internalscale;
                                }

                            }else{

                                //markupobject.linewidth = (markupobject.linewidth * fixedscale) / internalscale;

                                if (bfixedScale && !bUseMarkupScaling) {
                                    markupobject.innerRadius = (markupobject.innerRadius * fixedscale) / internalscale;
                                    markupobject.outerRadius = (markupobject.outerRadius * fixedscale) / internalscale;
                                }

                                //outerRadiusscale = ( localouterRadius / fixedscale) * imagescale;
                                //innerRadiusscale = ( localinnerRadius / fixedscale) * imagescale;

                            }

                        }



                        //markupobject.countshapes.push({x : mousepos.x, y : mousepos.y});

                        for (var ci = 0; ci < markupobject.countshapes.length; ci++) {

                            if (bNewFileformat && !bRasterScale) {

                                markupobject.countshapes[ci].x = (markupobject.countshapes[ci].x + this.xoffset) * internalscale;
                                markupobject.countshapes[ci].y = (markupobject.countshapes[ci].y + this.yoffset) * internalscale;

                            }


                        }
                        markupobject.findrectangle();



                    }

                    var bsegment = (this.type == 1 && this.subtype == 6);
                    var bpoly = (this.type == 1 || this.type == 2 || this.type == 8);

                    if (bpoly && !bsegment) {

                        for (var pi = 0; pi < markupobject.points.length; pi++) {

                            if (bNewFileformat && !bRasterScale) {

                                markupobject.points[pi].x = (markupobject.points[pi].x + this.xoffset) * internalscale;
                                markupobject.points[pi].y = (markupobject.points[pi].y + this.yoffset) * internalscale;

                            }


                        }
                        markupobject.findrectangle();

                        if(markupobject.holes.length > 0){

                            for(var h = 0; h < markupobject.holes.length; h++){

                                //markupobject.holes[h].parent = markupobject;

                                /*for (var pi = 0; pi < markupobject.holes[h].points.length; pi++) {

                                    if (bNewFileformat && !bRasterScale) {

                                        markupobject.holes[h].points[pi].x = (markupobject.holes[h].points[pi].x + markupobject.holes[h].xoffset) * internalscale;
                                        markupobject.holes[h].points[pi].y = (markupobject.holes[h].points[pi].y + markupobject.holes[h].yoffset) * internalscale;

                                    }


                                }*/


                            }

                        }

                    }



                    if (this.type == 0 || bsegment) {


                        for (var lcounter = 0; lcounter < this.pointlist.length; lcounter++) {
                            for (var counter = 0; counter < this.pointlist[lcounter].length; counter++) {


                                if (bNewFileformat && !bRasterScale) {

                                    this.pointlist[lcounter][counter].x = (this.pointlist[lcounter][counter].x + this.xoffset) * internalscale;
                                    this.pointlist[lcounter][counter].y = (this.pointlist[lcounter][counter].y + this.yoffset) * internalscale;

                                }


                            }
                        }
                        markupobject.findrectangle();


                    }


                    if (bNewFileformat && !bRasterScale) {
                        this.xoffset *= internalscale;
                        this.yoffset *= internalscale;

                        if (isNaN(this.docdx)) {
                            this.docdx = DocObj.getCurrentpage().getdx();
                        }

                        if (isNaN(this.docdy)) {
                            this.docdy = DocObj.getCurrentpage().getdy();
                        }

                        if (isNaN(this.docdscale)) {
                            this.docdscale = DocObj.getCurrentpage().getdscale();
                        }

                    }

                    if (this.type == 12) {

                        //ctx.font = "bold " + textstampscaled + "pt " + "Times New Roman";
                        this.stampsmalltheight = (this.w * 0.08) - 4;
                        var combinedtextheight = this.textheight + this.stampsmalltheight + ((this.h / 10) * 2);

                        if (combinedtextheight > this.h) {
                            this.textheight = (this.h / 2) - ((this.h / 10) * 2);
                            this.stampsmalltheight = (this.textheight / 2) - 4;
                        }
                    }

                    if (this.type == 12) {
                        markupobject.restorestampfontSize();
                    }

                    markupobject.scaling = scalefactor;

                };
