                    if(bisfoxitPDF){

                        var pixelRatio = getPixelRatio();

                        centercanvX *= pixelRatio;
                        centercanvY *= pixelRatio;

                    }



                    var counter = 0;
                    var lcounter = 0;
                    var transpoint = new point();
