                    this.dimtext = getUnitlength(dimdiag / this.scaling);
                    //this.dimtext = this.dimtext.toFixed(ndimprecision);
                    this.dimtext = this.dimtext.toFixed(dimPrecision);
                    this.dimtext = this.dimtext + " " + Unitlabel;

