                                        //yscalepoint = (this.points[counter].y - this.yoffset) * scalefactor;
                                        xscalepoint += pagedx;
                                        yscalepoint += pagedy;

                                        if (counter == 0) {
                                            ctx.moveTo(xscalepoint, yscalepoint);
                                        }
                                        else {
                                            ctx.lineTo(xscalepoint, yscalepoint);
                                        }
