    function deleteFromParentHoles(markupIndex) {
        let parentMarkupNo = DocObj.markuplist[markupIndex].parentmarkupnumber;

        if(parentMarkupNo) {
            let parentMarkup = DocObj.markuplist.find(obj => obj.markupnumber === parentMarkupNo);
            if(parentMarkup && parentMarkup.holes && parentMarkup.holes.length) {
                parentMarkup.holes = parentMarkup.holes.filter(item => item !== DocObj.markuplist[markupIndex].markupnumber);
            }
        }
    }

    function deleteAllHoles(holes) {
        for(let idx = 0; idx < holes.length; idx++) {
            RxCore_SelectMarkupbyIndex(holes[idx]);
            deletemarkup();
        }
    }

    function undoremoveholes(markup, id){

        var curhole = 0;
        var holecount = 0;
        var id = -1;
        var tempholelist = [];
        var bdeleted = true;


        for (curhole = 0; curhole < markup.holes.length; curhole++) {


            var bSekected = (markup.holes[curhole].id = id);

            if(bSekected){

                id = markup.markupnumber;
                //MarkupSaveState(id, undoModify);

                bdeleted = false;

                if (RxCore_GUI_Markup != undefined) {
                    RxCore_GUI_Markup.setMarkupSelected(markup.holes[curhole], {created : false, modified : false, deleted : true});
                }


            }else{
                tempholelist[holecount] = markup.holes[curhole];
                holecount++;

            }


        }

        markup.holes = tempholelist;

        return bdeleted;


    }


