    function drawpagerect(ctx, pagerect){

        var stroke = true;

        ctx.save(); // save the context so we don't mess up others
        ctx.strokeStyle = "black";
        //ctx.fillStyle = fillcolor;
        ctx.lineWidth = 4;
        /*if (markupobject.rotation != 0 && markupobject.type != 9) {
            var tx = x + (width / 2);
            var ty = y + (height / 2);
            ctx.translate(tx, ty);
            ctx.rotate(markupobject.rotation);
            ctx.translate(-tx, -ty);
        }*/
        ctx.beginPath();
        ctx.moveTo(pagerect.x, pagerect.y);
        ctx.lineTo(pagerect.w, pagerect.y);
        ctx.lineTo(pagerect.w, pagerect.h);
        ctx.lineTo(pagerect.x, pagerect.h);
        ctx.closePath();
        /*if (fill) {
            ctx.fill();
        }*/
        if (stroke) {
            ctx.stroke();
        }
        ctx.restore(); // restore context to what it was on entry


    }


