        function base64StringToByteArray(base64String) {

            base64String = base64String.split('base64,')[1];

            var byteCharacters = atob(base64String);
            var byteNumbers = new Array(byteCharacters.length);

            for (var i = 0; i < byteCharacters.length; i++) {
                byteNumbers[i] = byteCharacters.charCodeAt(i);
            }

            return new Uint8Array(byteNumbers);
        }




        function bytes2Int(bytes){
            var ret = 0;

            for (var idx = 0; idx<bytes.length; idx++) {
                ret += bytes[idx];
                if (idx < bytes.length - 1) {
                    ret = ret << 8;
                }
            }

            return ret;
        }
        function getChunk(pngData, chunkName){
            for (var idx = 0; idx<pngData.chunks.length; idx++) {
                if (pngData.chunks[idx].name = chunkName) {
                    return pngData.chunks[idx];
                }
            }
            return null;
        }

        function enrichParsedData(pngData){
            var idhrChunk = getChunk(pngData, 'IDHR');
            pngData.width = bytes2Int(idhrChunk.data.slice(0, 4));
            pngData.height = bytes2Int(idhrChunk.data.slice(4, 8));
            pngData.bitDepth = bytes2Int(idhrChunk.data.slice(8, 9));
            pngData.colorType = bytes2Int(idhrChunk.data.slice(9, 10));
            pngData.compressionMethod = bytes2Int(idhrChunk.data.slice(10, 11));
            pngData.filterMethod = bytes2Int(idhrChunk.data.slice(11, 12));
            pngData.interlaceMethod =bytes2Int(idhrChunk.data.slice(12, 13));

            pngData.isGreyScale = pngData.colorType == 0 || pngData.colorType == 4;
            pngData.isRgb = pngData.colorType == 2 || pngData.colorType == 6;
            pngData.hasAlpha = pngData.colorType == 4 || pngData.colorType == 6;
            pngData.hasPaletteMode = pngData.colorType == 3 && getChunk(pngData, 'PLTE') != null;

            return pngData;
        }

        function parseChunk(bytes, start){
            var chunkLength = bytes2Int(bytes.slice(start, start + 4));

            var chunkName = '';
            chunkName += String.fromCharCode(bytes[start + 4]);
            chunkName += String.fromCharCode(bytes[start + 5]);
            chunkName += String.fromCharCode(bytes[start + 6]);
            chunkName += String.fromCharCode(bytes[start + 7]);

            var chunkData = [];
            for (var idx = start + 8; idx<chunkLength + start + 8; idx++) {
                chunkData.push(bytes[idx]);
            }

            //TODO validate crc as required!

            return {
                start: start,
                end: Number(start) + Number(chunkLength) + 12, //12 = 4 (length) + 4 (name) + 4 (crc)
                length: chunkLength,
                name: chunkName,
                data: chunkData,
                crc: [
                    bytes[chunkLength + start + 8],
                    bytes[chunkLength + start + 9],
                    bytes[chunkLength + start + 10],
                    bytes[chunkLength + start + 11]
                ],
                crcChecked: false
            };
        }

        function parseBytes(bytes){
            var pngData = {};

            //verify file header
            pngData['headerIsValid'] = bytes[0] == 0x89
                        && bytes[1] == 0x50
                        && bytes[2] == 0x4E
                        && bytes[3] == 0x47
                        && bytes[4] == 0x0D
                        && bytes[5] == 0x0A
                        && bytes[6] == 0x1A
                        && bytes[7] == 0x0A

            if (!pngData.headerIsValid) {
                console.warn('Provided data does not belong to a png');
                return pngData;
            }
            var chunks = [];

            var chunk = parseChunk(bytes, 8);
            chunks.push(chunk);

            while (chunk.name !== 'IEND') {
                chunk = parseChunk(bytes, chunk.end);
                chunks.push(chunk);
            }

            pngData['chunks'] = chunks;
            return pngData;

        }

        function getPixelRatio() {
            var dpr = window.devicePixelRatio || 1;
            var bsr = 1;


            if(dpr != nstartuppixelratio){
                if(!brestartmessageshown){
                    brestartmessageshown = true;
                    alert("the browser window scaling has changed, restart the viewer");

                }

            }

            return dpr / bsr;
        }

        function setCtxTranslatehpx(ctx){
            var pixelRatio = getPixelRatio();
            glpixelRatio = pixelRatio;
            glpixellinewidthratio = 1 * pixelRatio;
            var halfx = pixelRatio/2;
            ctx.transform(1, 0, 0, 1, 0.5, 0.5);
            //ctx.translate(halfx, halfx);

        }

        function pxround(num){

            var rnum = (num + (num>0?0.5:-0.5)) << 0;

            return rnum;
        }

        class textObject {
            constructor(texobject, parent, fontobject, blockname, pathindx) {
                var scope = this;
                this.type = "text";
                this.textwidthset = false;
                this.textwidth = fontobject.height;
                this.parent = parent;
                this.blockname = blockname;
                this.index = pathindx;
                this.blockstate = 1;
                this.layerstate = 1;
                this.x1 = texobject.x1;
                this.y1 = texobject.y1;
                this.height = fontobject.height;
                this.fontname = fontobject.name;
                this.weight = fontobject.weight;
                this.rotation = -(fontobject.rotation * (Math.PI / 180));
                this.layer = texobject.layer;
                this.layerstate = texobject.layerstate;
                this.drawmode = texobject.drawmode;
                this.pen = texobject.pen;
                this.penarrindex = parent.pentable.getPenArrindex(this.pen);
                this.text = texobject.text;
                this.strokecolor = texobject.strokecolor;
                this.fillcolor = texobject.fillcolor;
                this.stroketempcolor = texobject.strokecolor;
                this.filltempcolor = texobject.fillcolor;
                this.selected = false;
                this.hasArea = false;
                this.entityType = texobject.entityType;
                this.role = texobject.role;
                this.mouseon = false;
                this.mouseover = false;

                var highlightdraw = false;

                this.insidePolygon = function (x, y, scalefactor, offsetx, offsety, mediax, mediay, mediah) {
                    return false;
                };
                this.toggleselect = function () {
                    var selectstate = !scope.selected;
                    scope.selected = selectstate;
                };

                this.iswithin = function (x, y, scalefactor, offsetx, offsety, mediax, mediay, mediah, hover) {

                    var within = false;

                    var rect = scope.getRectangle(scalefactor, offsetx, offsety, mediax, mediay, mediah);

                    if(x > rect.x && x < (rect.x + rect.w)){
                        if(y > rect.y && y < (rect.y + rect.h)){
                            within = true;
                        }
                    }



                    return within;


                };

                this.getArea = function(){


                    var minx = scope.x1;
                    var miny = scope.y1;

                    var maxy = miny + scope.height;
                    var maxx = minx + scope.textwidth;

                    //var maxx = scope.x2;
                    //var maxy = scope.y2;

                    if (minx > maxx) {
                        var tempx = minx;
                        minx = maxx;
                        maxx = tempx;
                    }
                    if (miny > maxy) {
                        var tempy = miny;
                        miny = maxy;
                        maxy = tempy;
                    }
                    /*return {
                        area: (maxx - minx) * (maxy - miny),
                        x: minx,
                        y: miny,
                        w: maxx - minx,
                        h: maxy - miny,
                        wp: (maxx - minx) / 10,
                        hp: (maxy - miny) / 10
                    };*/

                    return (maxx - minx) * (maxy - miny);

                };

                function getrotrect(rect, angle, rotpoint){
                    var origx = rect.x;
                    var origy = rect.y;

                    var origw = rect.w;
                    var origh = rect.h;

                    var CanvRotRad = angle;// * (Math.PI / 180);
                    var cosangle = Math.cos(CanvRotRad);
                    var sinangle = Math.sin(CanvRotRad);


                    var centercanvX = rotpoint.x;
                    var centercanvY = rotpoint.y;

                    var hw = origx - centercanvX;
                    var hh = origy - centercanvY;

                    var newx = (hw * cosangle) - (hh * sinangle);
                    var newy = (hw * sinangle) + (hh * cosangle);

                    newx = centercanvX + newx;
                    newy = centercanvY + newy;
                    hw = origw - centercanvX;
                    hh = origh - centercanvY;
                    var neww = (hw * cosangle) - (hh * sinangle);
                    var newh = (hw * sinangle) + (hh * cosangle);
                    neww = centercanvX + neww;
                    newh = centercanvY + newh;

                    return {
                        x: Math.min(newx, neww),
                        y: Math.min(newy, newh),
                        w: Math.max(neww, newx),
                        h: Math.max(newh, newy)
                    };


                }


                this.getRectangle = function (scalefactor, offsetx, offsety, mediax, mediay, mediah) {
                    var minx = (scope.x1 - mediax) * scalefactor;
                    var miny = (mediah - scope.y1) * scalefactor;
                    //var maxx = (scope.x2 - mediax) * scalefactor;
                    //var maxy = (mediah - scope.y2) * scalefactor;
                    var height = scope.height * scalefactor;
                    var width = scope.textwidth * scalefactor;



                    var maxy = miny + height;
                    //var maxx = minx + height;
                    var maxx = minx + width;
                    minx += offsetx;
                    maxx += offsetx;
                    miny += offsety;
                    maxy += offsety;
                    if (minx > maxx) {
                        var tempx = minx;
                        minx = maxx;
                        maxx = tempx;
                    }
                    if (miny > maxy) {
                        var tempy = miny;
                        miny = maxy;
                        maxy = tempy;
                    }

                    //ctx.translate(x1scaled, y1scaled - height);

                    var rotpoint = {x : minx, y : miny};

                    if (scope.rotation != 0) {
                       var rotrect = getrotrect({x : minx, y : miny, w : maxx, h : maxy},scope.rotation, rotpoint);
                       minx = rotrect.x;
                       miny = rotrect.y;
                       maxx = rotrect.w;
                       maxy = rotrect.h;
                    }

                    return {
                        found: true,
                        x: minx,
                        y: miny,
                        w: maxx - minx,
                        h: maxy - miny,
                        wp: (maxx - minx) / 10,
                        hp: (maxy - miny) / 10
                    };
                };
                this.findsnapPoint = function (x, y, scalefactor, offsetx, offsety, mediax, mediay, mediah) {
                    return {
                        found: false,
                        x: 0,
                        y: 0,
                        type: snapEndpoint
                    };
                };

                this.getdrawColors = function(drawprint){

                    var linecolor = scope.stroketempcolor;
                    var fillcolor = scope.filltempcolor;
                    var drawcolors = {linecolor : linecolor, fillcolor : fillcolor };


                    if(scope.parent.applypentable && scope.parent.pentable.changed){
                        if(scope.parent.pentable.getPendirect(scope.penarrindex) != undefined){
                            scope.stroketempcolor = scope.parent.pentable.getPendirect(scope.penarrindex).getcolor();
                            linecolor = scope.stroketempcolor;
                            fillcolor = linecolor;
                            scope.stroketempcolor = fillcolor;



                        }

                    }else{

                        scope.stroketempcolor = scope.strokecolor;
                        linecolor = scope.stroketempcolor;


                    }



                    if (!bKeepVectorColor) {
                        if (scope.stroketempcolor == DocObj.backgroundColor) {
                            if (DocObj.backgroundColor == "#FFFFFF") {
                                scope.stroketempcolor = "#000000";
                                linecolor = scope.stroketempcolor;
                            }
                            if (DocObj.backgroundColor == "#000000") {
                                scope.stroketempcolor = "#FFFFFF";
                                linecolor = scope.stroketempcolor;
                            }
                        }
                        if (this.filltempcolor == DocObj.backgroundColor) {
                            if (DocObj.backgroundColor == "#FFFFFF") {
                                scope.filltempcolor = "#000000";
                                fillcolor = scope.filltempcolor;
                            }
                            if (DocObj.backgroundColor == "#000000") {
                                scope.filltempcolor = "#FFFFFF";
                                fillcolor = scope.filltempcolor;
                            }
                        }
                    }
                    else {
                        scope.stroketempcolor = scope.strokecolor;
                        linecolor = scope.stroketempcolor;
                        scope.filltempcolor = scope.fillcolor;
                        fillcolor = scope.filltempcolor;
                    }
                    if (drawprint && scope.strokecolor == "#FFFFFF") {
                        scope.stroketempcolor = "#000000";
                        linecolor = scope.stroketempcolor;
                    }
                    if (drawprint && scope.fillcolor == "#FFFFFF") {
                        scope.filltempcolor = "#000000";
                        fillcolor = scope.filltempcolor;
                    }

                    if (scope.drawcompare) {
                        //ctx.strokeStyle = scope.comparecolor;

                        linecolor = scope.comparecolor;

                    }
                    else if (scope.parent.viewmode == 1) {

                        if (DocObj.backgroundColor == "#FFFFFF") {
                            //pathHandle.filltempcolor = "#000000";

                            linecolor = "#000000";
                            fillcolor = "#000000";

                            //ctx.strokeStyle = "#000000";
                            //ctx.fillStyle = "#000000";
                        }
                        if (DocObj.backgroundColor == "#000000" || DocObj.backgroundColor == "#A0A0A0") {
                        //if (DocObj.backgroundColor == "#000000") {
                            //pathHandle.filltempcolor = "#FFFFFF";
                            //ctx.strokeStyle = "#FFFFFF";
                            //ctx.fillStyle = "#FFFFFF";

                            linecolor = "#FFFFFF";
                            fillcolor = "#FFFFFF";

                        }

                        //ctx.fillStyle = "black";
                    }
                    else {
                        //ctx.strokeStyle = scope.stroketempcolor;
                        linecolor = scope.stroketempcolor;
                    }

                    if( scope.parent.comparemode == 0 ){
                        if(scope.role == 1){

                            //ctx.fillStyle = scope.parent.backgroundColor;
                            //ctx.strokeStyle = scope.parent.backgroundColor;

                            linecolor = scope.parent.backgroundColor;
                            fillcolor = scope.parent.backgroundColor;


                        }else if (scope.role == 2){
                            //ctx.fillStyle = scope.parent.overlayColor;
                            //ctx.strokeStyle = scope.parent.overlayColor;

                            linecolor = scope.parent.overlayColor;
                            fillcolor = scope.parent.overlayColor;


                        }

                    }

                    if(highlightdraw){

                        fillcolor = szmarkVectorColor;
                        linecolor = szmarkVectorColor;

                    }



                    return drawcolors = {linecolor : linecolor, fillcolor : fillcolor };
                };

                function getTextWidth(ctx, text, font) {
                    // re-use canvas object for better performance
                    //const canvas = getTextWidth.canvas || (getTextWidth.canvas = document.createElement("canvas"));
                    //const context = canvas.getContext("2d");
                    ctx.save();
                    ctx.font = font;
                    const metrics = ctx.measureText(text);
                    ctx.restore();


                    return metrics.width;
                }


                this.setTextWidth = function(ctx){
                    if(scope.textwidthset){
                        return;
                    }

                    var fontvalue = "normal " + scope.height + "px " + scope.fontname + ", Helvetica";

                    scope.textwidth = getTextWidth(ctx, scope.text, fontvalue);

                    scope.textwidthset = true;


                }

                this.highlight = function(ctx, scalefactor, offsetx, offsety, mediax, mediay, mediah){

                    highlightdraw = true;
                    scope.drawme(ctx, scalefactor, offsetx, offsety, mediax, mediay, mediah, 1, 1, false, false);
                    highlightdraw = false;

                };


                this.drawme = function (ctx, scalefactor, offsetx, offsety, mediax, mediay, mediah, ls, bs, drawprint, magnify) {
                    var x1scaled = (scope.x1 - mediax) * scalefactor;
                    var y1scaled = (mediah - scope.y1) * scalefactor;
                    var height = scope.height * scalefactor;
                    y1scaled += height;
                    //var x2scaled = (this.x2-mediax) * scalefactor;
                    //var y2scaled = (mediah - this.y2) * scalefactor;
                    if (ls == 0 || bs == 0) {
                        return;
                    }

                    if(!DocObj){
                        return;
                    }


                    //return drawcolors = {linecolor : linecolor, fillcolor : fillcolor };

                    var drawcolors = scope.getdrawColors(drawprint);

                    ctx.fillStyle = drawcolors.fillcolor;
                    ctx.strokeStyle = drawcolors.linecolor;

                    if (height < 5) {
                        //var fontvalue = "800 " + height + "px " + scope.fontname + ", Helvetica";
                        var fontvalue = "normal " + height + "px " + scope.fontname + ", Helvetica";
                        //console.log(height);
                    }
                    else {
                        fontvalue = "normal " + height + "px " + scope.fontname + ", Helvetica";
                    }

                    if (highlightdraw){
                        fontvalue = "normal " + height + 1 + "px " + scope.fontname + ", Helvetica";
                    }
                    //ctx.font = this.weight + " " + height + "pt " +  this.fontname;
                    ctx.font = fontvalue;


                    x1scaled += offsetx;
                    y1scaled += offsety;

                    x1scaled = pxround(x1scaled);
                    y1scaled = pxround(y1scaled);


                    ctx.save();
                    if (scope.rotation != 0) {
                        ctx.translate(x1scaled, y1scaled - height);
                        ctx.rotate(scope.rotation);
                        ctx.translate(-x1scaled, -(y1scaled - height));
                    }
                    ctx.fillText(scope.text, x1scaled, y1scaled);
                    ctx.restore();

                    scope.setTextWidth(ctx);

                    scope.drawcompare = false;
                };
                this.Close = function () {
                };
            }
        }

