                function transparent (data) {
                    for (var i = 0; i < data.length; i += 4) {
                        if (data[i] == 255 && data[i + 1] == 255 && data[i + 2] == 255) {
                            data[i + 3] = 100; // - data[i + 2]; // transparent
                            //do nothting with white
                        }
                    }
                };


                function setinvert(data) {

                    for (var i = 0; i < data.length; i += 4) {
                        data[i] = 255 - data[i]; // red
                        data[i + 1] = 255 - data[i + 1]; // green
                        data[i + 2] = 255 - data[i + 2]; // blue
                    }

                }

                function setcolor(data, color) {
                    //var c = color; // 16712640
                    /*var components = {
                        r: (color & 0xff0000) >> 16,
                        g: (color & 0x00ff00) >> 8,
                        b: (color & 0x0000ff)
                    };*/
                    var components = convertHexrgb(color);
                    for (var i = 0; i < data.length; i += 4) {
                        if (data[i] == 255 && data[i + 1] == 255 && data[i + 2] == 255) {
                            data[i + 3] = 100; // - data[i + 2]; // transparent
                            //do nothting with white
                        }else if(data[i] == 254 && data[i + 1] == 254 && data[i + 2] == 254){
                            data[i + 3] = 100; // - data[i + 2]; // transparent
                        }
                        else {
                            //console.log(data[i], data[i + 1], data[i + 2]);
                            data[i] = components.r; //255 - data[i];     // red
                            data[i + 1] = components.g; //255 - data[i + 1]; // green
                            data[i + 2] = components.b; // - data[i + 2]; // blue
                            //this.overlayColor = '#ff8000';
                        }
                    }
                }


                function countColors(data){
                    var count = 1;
                    var color = {r : data[0], g : data[1], b : data[2]};
                    var newcolor = {r : data[0], g : data[1], b : data[2]};

                    for (var i = 0; i < data.length; i += 4) {
                        /*data[i] = 255 - data[i]; // red
                        data[i + 1] = 255 - data[i + 1]; // green
                        data[i + 2] = 255 - data[i + 2]; // blue*/


                        newcolor = {r : data[i], g : data[i + 1], b : data[i + 2]};
                        if(newcolor.r == color.r && newcolor.g == color.g && newcolor.b == color.b){

                        }else{
                            count ++;
                            color.r = newcolor.r;
                            color.g = newcolor.g;
                            color.b = newcolor.b;

                        }

                    }

                    return count;
                }

