            ctx.strokeStyle = lineobj.getlineColor(drawprint);

            ctx.lineWidth = lineobj.getlinewidth(scalefactor, drawprint);
            //ctx.lineWidth = this.linewidth * scalefactor;

            x1scaled = pxround(x1scaled);
            y1scaled = pxround(y1scaled);

            x2scaled = pxround(x2scaled);
            y2scaled = pxround(y2scaled);

            ctx.beginPath();
            ctx.moveTo(x1scaled, y1scaled);
