        class HyperLinkObject {
            constructor(hyperlinkobj) {

                this.x1 = parseFloat(hyperlinkobj.x1);
                this.x2 = parseFloat(hyperlinkobj.x2);
                this.y1 = parseFloat(hyperlinkobj.y1);
                this.y2 = parseFloat(hyperlinkobj.y2);
                this.page = hyperlinkobj.page;
                this.dx1 = parseFloat(hyperlinkobj.dx1);
                this.dx2 = parseFloat(hyperlinkobj.dx2);
                this.dy1 = parseFloat(hyperlinkobj.dy1);
                this.dy2 = parseFloat(hyperlinkobj.dy2);
                this.mouseover = false;
                this.currentpage = 0;


            }

            onhyperlinkClick(x,y){

            }

            Getwithin (x, y, x1, x2, y1, y2) {
                var within = false;



                if (x > x1 && x < x2) {
                    if (y > y1 && y < y2) {
                        within = true;
                    }
                }
                return within;
            }

            drawhyperlink (ctx, scalefactor, offsetx, offsety, mediax, mediay, mediah){

                var minx = (this.x1 - mediax) * scalefactor;
                var miny = (mediah - this.y1) * scalefactor;
                var maxx = (this.x2 - mediax) * scalefactor;
                var maxy = (mediah - this.y2) * scalefactor;
                minx += offsetx;
                maxx += offsetx;
                miny += offsety;
                maxy += offsety;
                if (minx > maxx) {
                    var tempx = minx;
                    minx = maxx;
                    maxx = tempx;
                }
                if (miny > maxy) {
                    var tempy = miny;
                    miny = maxy;
                    maxy = tempy;
                }

                ctx.strokeStyle = "blue";
                ctx.lineWidth = 2;
                ctx.strokeRect(minx, miny, maxx - minx, maxy - miny);

            }

            insideHyperlink (x, y, scalefactor, offsetx, offsety, mediax, mediay, mediah, currentpage, hover) {

                var mp = {
                    x: x,
                    y: y
                };

                this.currentpage = currentpage;

                var minx = (this.x1 - mediax) * scalefactor;
                var miny = (mediah - this.y1) * scalefactor;
                var maxx = (this.x2 - mediax) * scalefactor;
                var maxy = (mediah - this.y2) * scalefactor;
                minx += offsetx;
                maxx += offsetx;
                miny += offsety;
                maxy += offsety;
                if (minx > maxx) {
                    var tempx = minx;
                    minx = maxx;
                    maxx = tempx;
                }
                if (miny > maxy) {
                    var tempy = miny;
                    miny = maxy;
                    maxy = tempy;
                }
                //cntximg.strokeStyle = "yellow";
                //cntximg.lineWidth = 2;
                //cntximg.strokeRect(minx, miny, maxx - minx, maxy - miny);
                if ((mp.x < minx || mp.x > maxx) || (mp.y < miny || mp.y > maxy)) {
                    return false;
                }


                var within = this.Getwithin(mp.x,mp.y, minx, maxx ,miny, maxy);


                if (within) {
                    //pathHandle.toggleselect();
                    this.mouseon();

                    if(hover){
                        if(RxCore_GUI_HyperlinkHover != undefined){
                            RxCore_GUI_HyperlinkHover.setMarkupHover(this, mp.x, mp.y);
                        }


                    }else{

                        if(RxCore_GUI_Hyperlink != undefined){
                            RxCore_GUI_Hyperlink.markupLink(this);
                        }

                        if(bautohyperlink){
                            var pageindex = parseInt(this.page) - 1;

                            if(pageindex != this.currentpage){

                                RxCore.gotoPage(pageindex);

                                //console.log(hyperlink.page);
                            }

                        }

                    }

                    return true;

                    //console.log(pathHandle.blockname);
                }
                else {

                    this.mouseoff();
                    return false;
                }

            }

            mouseon (){
                this.mouseover = true;
            }

            mouseoff(){
                this.mouseover = false;
            }



        }

        class LayerObject {
            constructor(layerxmldata, binary) {
                if(binary){
                    this.index = parseInt(layerxmldata.getInt32(0, true));
                    var ncolor = parseInt(layerxmldata.getInt32(4, true));
                    this.color = decimalToHex(ncolor);
                    var statevar = parseInt(layerxmldata.getInt32(8, true));
                    this.state = statevar;
                    this.isplottable = parseInt(layerxmldata.getInt32(12, true));
                    this.defaultstate = statevar;
                    var nname = layerxmldata.getUint16(16, true);
                    var lname = (nname == 0) ? " " : String.fromCharCode(nname);
                    var i = 18;
                    while (i <= 128) {
                        nname = layerxmldata.getUint16(i, true);
                        lname += (nname == 0) ? " " : String.fromCharCode(nname);
                        i += 2;
                    }
                    this.name = lname;
                }else{
                    this.index = layerxmldata.index;
                    this.color = layerxmldata.color;
                    this.state = layerxmldata.state;
                    this.isplottable = true;
                    this.defaultstate = layerxmldata.state;
                    this.name = layerxmldata.name;
                }

                this.turnLayerOnOff = function (index) {
                };
            }
        }

