                this.nudgeRotate = function (clockwise) {
                    //0.01745329252
                    if (clockwise) {
                        scope.fgdrawangle -= 0.001;
                        //scope.overlayrotation -= 0.001;
                    }
                    else {
                        scope.fgdrawangle += 0.001;
                        //scope.overlayrotation += 0.001;
                    }
                    scope.bnudgeangleused = true;

                    scope.refreshdraw();
                };
                this.nudgeScale = function (updown) {
                    var onepermillescale = scope.overlayscale / 5000;
                    /*0 - up
                    1 - down
                    2 - reset*/
                    switch (updown) {
                        case 0:
                            scope.nudgeScalefactor += onepermillescale;
                            break;
                        case 1:
                            scope.nudgeScalefactor -= onepermillescale;
                            break;
                        case 2:
                            scope.nudgeScalefactor = 0;
                    }

                    scope.refreshdraw();
                };
                this.offsetdirect = function (x, y) {

                    scope.nOffsetX = x;
                    scope.nOffsetY = y;
                    scope.refreshdraw();


                };
                this.nudgeoffset = function (direction) {
                    /*0 - left
                    1 - right
                    2 - up
                    3 - down*/


                    //scope.overlayoffsetx = offsetx;
                    //scope.overlayoffsety = offsety;

                    if(scope.parent.fixedScale != undefined){
                        var scaledIncrement = 0.1 * scope.parent.fixedScale;
                    }else{
                        scaledIncrement = 0.1
                    }


                    switch (direction) {
                        case 0:
                            scope.nOffsetX += scaledIncrement;
                            break;
                        case 1:
                            scope.nOffsetX -= scaledIncrement;
                            break;
                        case 2:
                            scope.nOffsetY -= scaledIncrement;
                            break;
                        case 3:
                            scope.nOffsetY += scaledIncrement;
                            break;
                    }



                    scope.refreshdraw();

                };
