                    var blockindex = getBlockIndex(blockid);

                    for (var attrc = 0; attrc < scope.attributes.length; attrc++) {
                        if (scope.attributes[attrc].name.toUpperCase() == name.toUpperCase() && scope.attributes[attrc].blockref == blockindex) {
                            scope.attributes[attrc].value = value;
                            break;
                        }

                    }

