                this.getinsidePolygon = function (x, y, scalefactor, offsetx, offsety, multi, hover) {
                    scope.multiselect = multi;
                    var within = false;
                    var screenmouse  = { x: x, y: y };
                    var rotatedpoint = { x: x, y: y };
                    var partlist = [];
                    var partlistAll = [];
                    var selected = [];
                    var foundblocks = [];
                    var pathindex = {index : null};
                    var foundblock = undefined;

                    var foundArea = 0;
                    var curfoundArea = 0;

                    var partindex = undefined;

                    if (scope.parent.DocRef.pages[scope.parent.DocRef.currentpage].getpageRotation() != 0) {
                        rotatedpoint = mouse_rotated(x, y);
                    }
                    x = rotatedpoint.x;
                    y = rotatedpoint.y;
                    for (var i = 0; i < scope.pathlist.length; i++) {
                        var blayeron = layeron(i);
                        var bblcckon = blockon(i);
                        if (blayeron && bblcckon) {
                            within = scope.pathlist[i].insidePolygon(x, y, scalefactor, offsetx, offsety, scope.x, scope.y, scope.h, hover);
                            if (within) {


                                foundArea = curfoundArea;
                                curfoundArea = scope.pathlist[i].getArea();

                                if(foundblock){

                                    if(curfoundArea < foundArea){
                                        foundblock = scope.pathlist[i].blockname;
                                        partindex = i;

                                        foundblocks.unshift({foundblock : foundblock, partindex : partindex, area : curfoundArea});
                                    }else{
                                        foundblock = scope.pathlist[i].blockname;
                                        partindex = i;

                                        foundblocks.push({foundblock : foundblock, partindex : partindex, area : curfoundArea});
                                    }


                                }else{
                                    foundblock = scope.pathlist[i].blockname;
                                    partindex = i;

                                    foundblocks.push({foundblock : foundblock, partindex : partindex, area : curfoundArea});
                                }

                                //scope.pathlist[i].toggleselect();
                                //foundblock = scope.pathlist[i].blockname;
                                //partindex = i;
                            }
                            else {
                                //foundblock = undefined;

                                if (multi) {
                                    if (scope.pathlist[i].selected) {
                                        var blockindex = scope.pathlist[i].blockname;
                                        selected.push(scope.blocklist[blockindex].index);
                                    }
                                }
                            }
                        }
                    }
                    if (foundblock) {

                        if(!hover){
                            if (!scope.pathlist[partindex].selected) {
                                scope.selectBlockPath(true, scope.pathlist[partindex].blockname);


                            }
                            else {
                                scope.selectBlockPath(false, scope.pathlist[partindex].blockname);

                            }

                            if (scope.pathlist[partindex].selected) {
                                selected.push(scope.blocklist[foundblock].index);
                                if (!multi) {
                                    partlist = getAttributes(foundblock);
                                    pathindex.index = partindex;
                                    partlist.push(pathindex);

                                }
                            }
                            else {
                                if (!multi) {
                                    partlist = [];
                                }
                            }

                        }else{

                            if (!scope.pathlist[partindex].selected) {

                                if (foundblocks.length > 1){

                                    pathindex.index = foundblocks[0].partindex;

                                    for (var fbi = 0; fbi < foundblocks.length; fbi ++){

                                        var attributes = getAttributes(foundblocks[fbi].foundblock);
                                        attributes.push({index : foundblocks[fbi].partindex});

                                        partlistAll.push(attributes);

                                    }

                                }else{
                                    partlistAll = getAttributes(foundblock);
                                    //pathindex = {pathindex : partindex};
                                    pathindex.index = partindex;
                                    partlistAll.push(pathindex);

                                }

                                //partlist = getAttributes(foundblock);
                                //pathindex = {pathindex : partindex};
                                //pathindex.index = partindex;
                                //partlist.push(pathindex);


                            }
                        }
                    }

                    if(!hover){
                        if (RxCore_GUI_2DBlockID != undefined) {
                            RxCore_GUI_2DBlockID.set2DBlockID(selected);
                        }
                    }
                    if (!multi) {

                        if(!hover){
                            if (RxCore_GUI_2DBlockInfo != undefined) {
                                RxCore_GUI_2DBlockInfo.set2DBlockInfo(partlist);
                            }
                        }

                        if (hover){
                            if (RxCore_GUI_2DBlockInfoScreen != undefined) {
                                //RxCore_GUI_2DBlockInfoScreen.set2DBlockInfo(partlist, screenmouse, pathindex);
                                RxCore_GUI_2DBlockInfoScreen.set2DBlockInfo(partlistAll, screenmouse, pathindex);
                            }

                        }

                    }
                    return within;
                };

