                function getTextWidth(ctx, text, font) {
                    // re-use canvas object for better performance
                    //const canvas = getTextWidth.canvas || (getTextWidth.canvas = document.createElement("canvas"));
                    //const context = canvas.getContext("2d");
                    ctx.save();
                    ctx.font = font;
                    const metrics = ctx.measureText(text);
                    ctx.restore();


                    return metrics.width;
                }

                function getTexareadim(x,y,w,h){

                    const scale = getPixelRatio();

                    var textleft = (x / scale);
                    var texttop = (y / scale);

                    var textwidth = (w / scale);
                    var textheight = (h / scale);

                    return {x:textleft, y:texttop, w:textwidth, h:textheight};


                }


