        class markupLoader {
            constructor(URL, parent) {
                var markupref = this;
                this.parent = parent;
                this.scene = null;
                var loader = new THREE.ObjectLoader();
                this.markuploaded = function (markup) {
                    markupref.parent.setMarkupScene(markup);
                };
                this.markupProgress = function (xhr) {
                    /*if (RxCore_GUI_Upload != undefined) {
                        RxCore_GUI_Upload.setUpload(Math.round(xhr.loaded / xhr.total * 100));
                    }*/
                    console.log((xhr.loaded / xhr.total * 100) + '% loaded');
                };
                this.markupError = function (error) {
                    console.log('An error happened ', error);
                };
                loader.load(URL, markupref.markuploaded, markupref.markupProgress, markupref.markupError);
            }
        }

        class glTFLoader {
            constructor(URL, parent, addscene) {
                //import { GLTFLoader } from 'three/GLTFLoader.js';
                var gltfref = this;
                this.parent = parent;
                this.scene = null;
                var baddscene = addscene;
                var loader = new THREE.GLTFLoader();
                var buseoptimizer = false;

                if (buseoptimizer){
                    loader.setMeshoptDecoder( MeshoptDecoder );
                }


                this.addScene = function(URL, addscene){
                    baddscene = addscene;
                    suspendrender = true;
                    loader.load(URL, gltfref.gltfloaded, gltfref.gltfprogress, gltfref.gltferror);
                };

                this.gltfloaded = function (gltf) {
                    //gltfref.scene = gltf.scene;
                    renderer.domElement.style.visibility = 'visible';

                    suspendrender = false;

                    if(baddscene){
                        gltfref.parent.setAddtoScene(gltf.scene);
                    }else{
                        gltfref.parent.setScene(gltf.scene);
                    }

                    if (RxCore_GUI_Upload != undefined) {
                        RxCore_GUI_Upload.setUpload("hide");
                    }
                    //gltfref.parent.blockreadComplete();
                };
                this.gltfprogress = function (xhr) {
                    if (RxCore_GUI_Upload != undefined) {
                        RxCore_GUI_Upload.setUpload(Math.round(xhr.loaded / xhr.total * 100));
                    }
                    //console.log( ( xhr.loaded / xhr.total * 100 ) + '% loaded' );
                };
                this.gltferror = function (error) {
                    //console.log('An error happened');
                    console.log('An error happened', error);
                };

                if(buseAuth){

                    var auth = getAuth();

                    if (auth.authset){
                        //xhr.setRequestHeader('Authorization', auth.authString + auth.baseuserstring);
                        var requestHeader = { Authorization: auth.authString + auth.baseuserstring };
                        //

                    }

                }else{
                    requestHeader = undefined;
                }

                loader.load(URL, gltfref.gltfloaded, gltfref.gltfprogress, gltfref.gltferror, requestHeader);

                //loader.load(URL, gltfref.gltfloaded, gltfref.gltfprogress, gltfref.gltferror);
            }
        }

