                this.setCADmaterial = function(busevmerge){

                    var mesharr = vector3Dref.getMeshChildren();
                    //for var

                    var creaseAngle = 35 / (180 / Math.PI);

                    //.mergeVertices ( geometry : BufferGeometry, tolerance : Number ) : BufferGeometry

                    for (var i = 0; i < mesharr.length; i++) {
                        if (mesharr[i].type == "Group") {
                            for (var j = 0; j < mesharr[i].children.length; j++) {
                                if (mesharr[i].children[j].type == "Mesh") {
                                    if(mesharr[i].children[j].material.type == "MeshStandardMaterial"){

                                        if(busevmerge){
                                            if(vector3Dref.geometryutil != undefined){
                                                //mesharr[i].children[j].geometry = vector3Dref.geometryutil.mergeVertices(mesharr[i].children[j].geometry);


                                                mesharr[i].children[j].geometry = vector3Dref.geometryutil.toCreasedNormals(mesharr[i].children[j].geometry, creaseAngle);


                                                //mesharr[i].children[j].geometry = vector3Dref.geometryutil.mergeVertices(mesharr[i].children[j].geometry, 0.0000001);
                                            }

                                        }

                                        //mesharr[i].children[j].geometry.computeFaceNormals();
                                        //mesharr[i].children[j].geometry.computeVertexNormals();

                                        mesharr[i].children[j].material.flatShading = false;

                                        if(!vector3Dref.isbim){
                                            mesharr[i].children[j].material.metalness = 0.1;
                                            mesharr[i].children[j].material.roughness = 0.5;
                                        }
                                        mesharr[i].children[j].material.needsUpdate = true;


                                        mesharr[i].children[j].updateMatrixWorld();
                                    }
                                    //mesharr[i].children[j].geometry.mergeVertices();
                                }
                            }
                        }
                        if (mesharr[i].type == "Mesh") {



                            if(mesharr[i].material.type == "MeshStandardMaterial"){


                                if(busevmerge){

                                    if(vector3Dref.geometryutil != undefined){
                                        //mesharr[i].geometry = vector3Dref.geometryutil.mergeVertices(mesharr[i].children[j].geometry);

                                        mesharr[i].geometry = vector3Dref.geometryutil.toCreasedNormals(mesharr[i].geometry, creaseAngle);

                                        //.toCreasedNormals ( geometry : BufferGeometry, creaseAngle : Number ) :
                                        //mesharr[i].geometry = vector3Dref.geometryutil.mergeVertices(mesharr[i].geometry);
                                    }






                                }




                                //mesharr[i].geometry.computeFaceNormals();
                                //mesharr[i].geometry.computeVertexNormals();


                                mesharr[i].material.flatShading = false;

                                if(!vector3Dref.isbim){
                                    mesharr[i].material.metalness = 0.1;
                                    mesharr[i].material.roughness = 0.5;
                                }

                                mesharr[i].material.needsUpdate = true;

                                mesharr[i].updateMatrixWorld();
                            }

                            //mesharr[i].geometry.mergeVertices();
                        }
                    }


                };




