                    parent.navcamera.position.set(vector3Dref.navbox.max.x, vector3Dref.navbox.min.y, vector3Dref.navbox.max.z);
                    parent.navcamera.translateY(-distance);
                    parent.navcamera.lookAt(vector3Dref.navboxCenter.x, vector3Dref.navboxCenter.y, vector3Dref.navboxCenter.z);

