                this.frameArea = function () {
                    if (vector3Dref.boxSize == null || vector3Dref.boxCenter == null) {
                        return;
                    }

                    // pick some near and far values for the frustum that
                    // will contain the box.
                    parent.camera.near = vector3Dref.boxSize / 1000;
                    parent.camera.far = vector3Dref.boxSize * 300;

                    //directionalLight_1.shadow.camera.near = vector3Dref.boxSize / 300;
                    //directionalLight_1.shadow.camera.far = vector3Dref.boxSize * 300;

                    //directionalLight_1.shadow.camera.updateProjectionMatrix();
                    //thispage.walkthroughcontrol.movementSpeed = 10;
                    //thispage.walkthroughcontrol.lookSpeed = 0.125;
                    //thispage.walkthroughcontrol.lookVertical = true;
                    parent.camera.updateProjectionMatrix();
                    // point the camera to look at the center of the box

                    vector3Dref.setCamera();


                    var width = vector3Dref.box.max.x - vector3Dref.box.min.x;
                    var depth = vector3Dref.box.max.y - vector3Dref.box.min.y;
                    var height = vector3Dref.box.max.z - vector3Dref.box.min.z;
                    var minx = vector3Dref.box.min.x;
                    var maxx = vector3Dref.box.max.x
                    var miny = vector3Dref.box.min.y;
                    var maxy = vector3Dref.box.max.y;
                    var minz = vector3Dref.box.min.z;
                    var maxz = vector3Dref.box.max.z;

                    vector3Dref.curwidth = width;
                    vector3Dref.curdepth = depth;
                    vector3Dref.curheight = height;
                    vector3Dref.curminx = minx;
                    vector3Dref.curmaxx = maxx;
                    vector3Dref.curminy = miny;
                    vector3Dref.curmaxy = maxy;
                    vector3Dref.curminz = minz;
                    vector3Dref.curmaxz = maxz;


                    vector3Dref.setClippingPlanes(width, depth, height, minx, maxx, miny, maxy, minz, maxz);

                    //vector3Dref.helperplaneX.updateMatrixWorld(true);
                    //vector3Dref.helperplaneY.updateMatrixWorld(true);
                    //vector3Dref.helperplaneZ.updateMatrixWorld(true);

                    //vector3Dref.scene.add( vector3Dref.helperplaneX );
                    //vector3Dref.scene.add( vector3Dref.helperplaneY );
                    //vector3Dref.scene.add( vector3Dref.helperplaneZ );




                };

                this.setClippingPlanes = function(width, depth, height, minx, maxx, miny, maxy, minz, maxz){
                    //var width = vector3Dref.box.max.x - vector3Dref.box.min.x;
                    //var depth = vector3Dref.box.max.y - vector3Dref.box.min.y;
                    //var height = vector3Dref.box.max.z - vector3Dref.box.min.z;
                    var wscale = renderer.domElement.width / width;
                    var hscale = renderer.domElement.height / height;
                    this.scale = Math.min(wscale, hscale);

                    vector3Dref.xPlaneconst = width;
                    var safeadjust = vector3Dref.xPlaneconst / 20; //10 percent additional space for clipping
                    vector3Dref.xPlaneconst += safeadjust;
                    //vector3Dref.xPlaneEnd = vector3Dref.box.max.x;

                    //vector3Dref.xPlaneStart = vector3Dref.box.min.x;

                    //non inverted
                    //vector3Dref.xPlaneEnd = vector3Dref.box.min.x;
                    //inverted
                    vector3Dref.xPlaneEnd = -(minx) - width;
                    vector3Dref.xPlaneStart = maxx;
                    vector3Dref.xPlaneEnd -= safeadjust / 2;
                    //vector3Dref.yPlaneconst = height;

                    vector3Dref.yPlaneconst = depth;


                    safeadjust = vector3Dref.yPlaneconst / 20; //10 percent additional space for clipping
                    vector3Dref.yPlaneconst += safeadjust;
                    //vector3Dref.yPlaneEnd = vector3Dref.box.max.y;
                    //vector3Dref.yPlaneStart = vector3Dref.box.min.y;

                    //non inverted
                    //vector3Dref.yPlaneEnd = vector3Dref.box.min.y;
                    //inverted
                    vector3Dref.yPlaneEnd = -(miny) - depth;
                    vector3Dref.yPlaneStart = maxy;
                    //console.log(vector3Dref.yPlaneEnd, "plane end y");
                    //console.log(vector3Dref.yPlaneEnd + depth, "plane end y + depth");
                    //console.log(vector3Dref.yPlaneStart, "plane start y");
                    vector3Dref.yPlaneEnd -= safeadjust / 2;
                    //vector3Dref.zPlaneconst = depth;

                    vector3Dref.zPlaneconst = height;

                    safeadjust = vector3Dref.zPlaneconst / 20; //10 percent additional space for clipping
                    vector3Dref.zPlaneconst += safeadjust;
                    //vector3Dref.zPlaneEnd = vector3Dref.box.max.z;
                    //vector3Dref.zPlaneStart = vector3Dref.box.min.z;
                    vector3Dref.zPlaneEnd = minz;
                    vector3Dref.zPlaneStart = maxz;
                    vector3Dref.zPlaneEnd -= safeadjust / 2;

                    //vector3Dref.globalPlaneX.constant = vector3Dref.xPlaneStart;
                    //vector3Dref.globalPlaneY.constant = vector3Dref.yPlaneStart;
                    //vector3Dref.globalPlaneZ.constant = vector3Dref.zPlaneStart;

                    vector3Dref.globalPlaneX.constant = vector3Dref.xPlaneEnd + vector3Dref.xPlaneconst;
                    vector3Dref.globalPlaneY.constant = vector3Dref.yPlaneEnd + vector3Dref.yPlaneconst;
                    vector3Dref.globalPlaneZ.constant = vector3Dref.zPlaneEnd + vector3Dref.zPlaneconst;
                };

