                this.closestVertex = function(intersection,triangle){


                    var _faceVertices = triangle.geometry.getAttribute('position');
                    if (_faceVertices.count < 4){
                        return;
                    }

                    var _interPoint = intersection.point;

                    var apoint = new THREE.Vector3(_faceVertices.array[0],_faceVertices.array[1],_faceVertices.array[2]);
                    var bpoint = new THREE.Vector3(_faceVertices.array[3],_faceVertices.array[4],_faceVertices.array[5]);
                    var cpoint = new THREE.Vector3(_faceVertices.array[6],_faceVertices.array[7],_faceVertices.array[8]);

                    //var curx = vector3Dref.boxCenter.x;
                    //var cury = vector3Dref.boxCenter.y;
                    //var curz = vector3Dref.boxCenter.z;

                    //var sceneoffset = new THREE.Vector3(curx,cury,curz);
                    apoint.sub(vector3Dref.boxCenter);
                    bpoint.sub(vector3Dref.boxCenter);
                    cpoint.sub(vector3Dref.boxCenter);



                    //-(vector3Dref.w / 2) * vector3Dref.scale;


                    //apoint.set(_faceVertices[0],_faceVertices[1],_faceVertices[2]);
                    //bpoint.set(_faceVertices[3],_faceVertices[4],_faceVertices[5]);
                    //cpoint.set(_faceVertices[6],_faceVertices[7],_faceVertices[8]);

                    //var curpoint = new THREE.Vector3();
                    //var closestpoint = new THREE.Vector3();
                    //var distancetopoint = 0;
                    //var prevdist = null;
                    //var _closestVertex;

                    //_interPoint.normalize();

                    /*for(var i=0;i<_faceVertices.count;i+=3){
                        if (i>0){
                            prevdist = distancetopoint;
                        }
                        curpoint.set(i,i+1,i+2);
                        distancetopoint = _interPoint.distanceTo(curpoint);

                        if(prevdist != null && distancetopoint > prevdist){
                            distancetopoint = prevdist;

                        }else{
                            closestpoint.copy(curpoint);
                        }

                    }*/

                    var _distToA = _interPoint.distanceTo(apoint);
                    var _distToB = _interPoint.distanceTo(bpoint);
                    var _distToC = _interPoint.distanceTo(cpoint);

                    var _closestVertex;

                    var _closest = Math.min(_distToA,_distToB);
                    _closest = Math.min(_distToC,_closest);
                    switch(_closest){
                        case _distToA:
                            _closestVertex = apoint;
                            apoint.add(vector3Dref.boxCenter);
                            break;
                        case _distToB:
                            _closestVertex = bpoint;
                            bpoint.add(vector3Dref.boxCenter);
                            break;
                        case _distToC:
                            _closestVertex = cpoint;
                            cpoint.add(vector3Dref.boxCenter);
                            break;

                    }


                    //var _closest = _distToA < _distToB ? (_closestVertex = apoint, _distToA) : (_closestVertex = bpoint, _distToB);
                    //_closest > _distToC && (_closest = _distToC, _closestVertex = cpoint);

                    _faceVertices = apoint = bpoint = cpoint = _interPoint = null;

                    return {
                        vertex: _closestVertex,
                        distance: _closest
                    }

                };

