                this.dimvaluedraw = function (midpoint, ctx, strokecolor, dimtext, bcreate) {
                    ctx.save();

                    var scalefactor = 1;

                    var labelsize = { w: 0, h: 0 };

                    //x, y, width, height
                    //, scalefactor, brotate
                    //var dimwidth = width - x;


                    //var dimheight = height - y;
                    //var dimdiag = markupobject.getdiag(dimwidth, dimheight);
                    //var dimanglerad = Math.atan2(dimheight, dimwidth);
                    ctx.textAlign = "start";

                    //need to duplicatge font object
                    //markupobject.font.setScale(scalefactor);


                    var scaletextheight = vector3Dref.font.height * scalefactor;
                    this.textheight = vector3Dref.font.height;
                    var labelsizefactor = vector3Dref.font.height / 12;
                    var labelstartoffsetx = 10 * labelsizefactor;
                    var labelstartoffsety = 5 * labelsizefactor;
                    var labelwidthtoffset = 20 * labelsizefactor;
                    var labelheightoffset = 10 * labelsizefactor;
                    ctx.font = vector3Dref.font.fontstringScaled;
                    var dimt = ctx.measureText(dimtext);


                   var dimtextwidth = dimt.width;

                   if(bcreate){
                        var dimtextx = midpoint.x + 15;
                        var dimtexty = midpoint.y;

                   } else{
                        dimtextx = midpoint.x - (dimtextwidth / 2);
                        dimtexty = midpoint.y + (scaletextheight / 2);
                    }

                    /*if (markupobject.saved) {
                        var dimtextx = x + (dimwidth / 2) - (dimtextwidth / 2);
                        var dimtexty = y + (dimheight / 2) + (scaletextheight / 2);
                    }
                    else {
                        //var dimtextx = x + (dimwidth / 2) - (dimtextwidth / 2);
                        dimtextx = width + (15 * scalefactor);
                        dimtexty = height;
                        //var dimtexty = y + (dimheight / 2) + (scaletextheight / 2);
                    }*/
                    /*if (dimanglerad > (Math.PI * 0.5) || dimanglerad < -(Math.PI * 0.5)) {
                        if (markupobject.pagerotation == 0) {
                            dimanglerad += Math.PI;
                        }
                    }*/
                    //console.log(dimanglerad);
                    /*if (brotate && markupobject.saved) {
                        var tx = x + (dimwidth / 2);
                        var ty = y + (dimheight / 2);
                        ctx.translate(tx, ty);
                        ctx.rotate(dimanglerad);
                        ctx.translate(-tx, -ty);
                    }*/
                    /*if(rotation !=0){
                     }*/

                    ctx.lineWidth = 1;
                    var yrect = dimtexty - scaletextheight;

                    ctx.fillStyle = "white";
                    ctx.strokeStyle = strokecolor;

                    ctx.fillRect(dimtextx - (labelstartoffsetx * scalefactor), yrect - (labelstartoffsety * scalefactor), dimtextwidth + (labelwidthtoffset * scalefactor), scaletextheight + (labelheightoffset * scalefactor));
                    ctx.strokeRect(dimtextx - (labelstartoffsetx * scalefactor), yrect - (labelstartoffsety * scalefactor), dimtextwidth + (labelwidthtoffset * scalefactor), scaletextheight + (labelheightoffset * scalefactor));

                    labelsize.w = dimtextwidth + (labelwidthtoffset * scalefactor);
                    labelsize.h = scaletextheight + (labelheightoffset * scalefactor);

                    ctx.fillStyle = "black";
                    ctx.fillText(dimtext, dimtextx, dimtexty);
                    ctx.restore();
                };

                this.draw2DPoints = function(points){

                    cntximg.save(); // save the context so we don't mess up others
                    cntximg.strokeStyle = 'black';
                    cntximg.fillStyle = "rgba(0, 0, 255, 0.5)";


                    cntximg.beginPath();

                    cntximg.arc(points[0].x, points[0].y, 32 * 0.25, 0, Math.PI * 2); //full circle
                    //ctx.arc(100, 75, 50, 0, 2 * Math.PI);
                    cntximg.closePath();
                    //ctx.beginPath();
                    //ctx.arc(100, 75, 25, 0, 2 * Math.PI, true);
                    cntximg.arc(points[0].x, points[0].y, 32 * 0.125, 0, Math.PI * 2, true); //full circle
                    cntximg.closePath();


                    cntximg.arc(points[1].x, points[1].y, 32 * 0.25, 0, Math.PI * 2); //full circle
                    //ctx.arc(100, 75, 50, 0, 2 * Math.PI);
                    cntximg.closePath();
                    //ctx.beginPath();
                    //ctx.arc(100, 75, 25, 0, 2 * Math.PI, true);
                    cntximg.arc(points[1].x, points[1].y, 32 * 0.125, 0, Math.PI * 2, true); //full circle
                    cntximg.closePath();

                    if(points.length > 1){

                        cntximg.moveTo(points[0].x, points[0].y);
                        cntximg.lineTo(points[1].x, points[1].y);
                        cntximg.closePath();
                        var bdostroke = true;
                    }


                    if(bdostroke){
                        cntximg.stroke();
                    }

                    //ctx.stroke();
                    cntximg.fill();
                    cntximg.restore(); // restore context to what it was on entry

                };

                this.inViewCheck = function(vector){

                    //var inview = false;

                    //THREE.Matrix4: .getInverse() has been removed. Use matrixInv.copy( matrix ).invert(); instead.

                    parent.camera.updateMatrix(); // make sure camera's local matrix is updated
                    parent.camera.updateMatrixWorld(); // make sure camera's world matrix is updated

                    var threerev = parseInt(THREE.REVISION);


                    if (threerev <= 127){
                        //var quatInverse = quat.clone().inverse();
                        parent.camera.matrixWorldInverse.getInverse( parent.camera.matrixWorld );
                    }else{
                        ///var matrix4 =
                        //parent.camera.matrixWorldInverse.invert(parent.camera.matrixWorld);
                        parent.camera.matrixWorldInverse.copy( parent.camera.matrixWorld ).invert();
                        //matrixInv
                    }



                    var frustum = new THREE.Frustum();

                    //setFromProjectionMatrix(
                    frustum.setFromProjectionMatrix( new THREE.Matrix4().multiplyMatrices( parent.camera.projectionMatrix, parent.camera.matrixWorldInverse ) );

                    if(frustum.containsPoint(vector.pos)) {
                        return true;
                        //console.log('within camera view');
                      } else {
                        return false;
                        //console.log('outside camera view');
                      }

                };

                this.addDimLine = function(p1, p2, parentuuid){


                    var linepos = new Float32Array([p1.x,p1.y,p1.z,p2.x,p2.y,p2.z]);

                    var geometry3 = new THREE.BufferGeometry();
                    geometry3.setAttribute('position', new THREE.BufferAttribute(linepos, 3));

                    geometry3.setIndex(new THREE.BufferAttribute(new Uint16Array([0,1]), 1));

                    var material = new THREE.LineBasicMaterial( { color: 0x0000ff,linewidth:2.0 } );
                    var dimension = new THREE.LineSegments(geometry3, material);

                    dimension.userData.type = "dimension";
                    dimension.userData.parentref = parentuuid;


                    vector3Dref.markupscene.add(dimension);


                };
                this.draw2DLine = function(points){
                    cntximg.save(); // save the context so we don't mess up others
                    cntximg.strokeStyle = 'black';

                    cntximg.beginPath();
                    cntximg.moveTo(points[0].x, points[0].y);
                    cntximg.lineTo(points[1].x, points[1].y);
                    cntximg.closePath();
                    cntximg.stroke();

                };



                this.draw2DPoint = function(point, ctx){

                    ctx.save(); // save the context so we don't mess up others
                    ctx.strokeStyle = 'black';

                    if(point.selected){
                        ctx.fillStyle = "rgba(255, 0, 0, 0.5)";
                    }else{
                        ctx.fillStyle = "rgba(0, 0, 255, 0.5)";
                    }




                    ctx.beginPath();
                    ctx.arc(point.pos.x, point.pos.y, 32 * 0.25, 0, Math.PI * 2); //full circle
                    //ctx.arc(100, 75, 50, 0, 2 * Math.PI);

                    ctx.closePath();
                    //ctx.beginPath();
                    //ctx.arc(100, 75, 25, 0, 2 * Math.PI, true);
                    ctx.arc(point.pos.x, point.pos.y, 32 * 0.125, 0, Math.PI * 2, true); //full circle
                    ctx.closePath();
                    //ctx.stroke();
                    ctx.fill();
                    ctx.restore(); // restore context to what it was on entry

                };


                this.setdimvalue = function (distance) {

                    var dimdiag = distance;

                    var blocalusefraction = false;



                    if (pageobject.Unitofmeasure == 2) {

                        if (bUseFraction) {
                            blocalusefraction = true;
                        }
                        var fractionval = getUnitlengthRemainder(dimdiag);


                        var dimtextfrac = fractionval.quot;
                        var dimtextrem = fractionval.rem;

                        if (pageobject.SubmeasureUnit == 1) {
                            var szdimtext = dimtextfrac + "\"";
                            if (fractionval.numerator != 0 && fractionval.denominator != 0) {
                                if (fractionval.numerator == fractionval.denominator) {
                                    dimtextfrac + 1;
                                    var szdimtext = dimtextfrac + "\"";
                                }
                                else {
                                    var szfraction = fractionval.numerator + "/" + fractionval.denominator;
                                    var szdimtext = dimtextfrac + " " + szfraction + "\"";
                                }
                            }
                        }
                        if (pageobject.SubmeasureUnit == 2) {
                            if (dimtextrem != 0) {
                                var szdimtext = dimtextfrac + "\' - " + dimtextrem + "\"";
                            }
                            else {
                                szdimtext = dimtextfrac + "\'";
                            }
                            if (fractionval.numerator != 0 && fractionval.denominator != 0) {
                                if (fractionval.numerator == fractionval.denominator) {
                                    dimtextrem + 1;
                                    var szdimtext = dimtextfrac + "\' - " + dimtextrem + "\"";
                                }
                                else {
                                    if (dimtextrem != 0) {
                                        var szfraction = fractionval.numerator + "/" + fractionval.denominator;
                                        var szdimtext = dimtextfrac + "\' - " + dimtextrem + " " + szfraction + "\"";
                                    }
                                    else {
                                        var szfraction = fractionval.numerator + "/" + fractionval.denominator;
                                        var szdimtext = dimtextfrac + "\' - " + szfraction + "\"";
                                    }
                                }
                            }
                        }
                    }
                    var dimtext = getUnitlength(dimdiag);

                    dimtext = getUnitlength(dimdiag);
                    dimtext = dimtext.toFixed(ndimprecision);

                    dimtext = dimtext + " " + pageobject.Unitlabel;

                    if (blocalusefraction) {
                        dimtext = szdimtext;
                    }

                    return dimtext;

                };

