                this.posToScreen = function(pos){
                    var p = pos.clone();

                    var vector = p.project(pageobject.camera);

                    //vector.x = (vector.x + 1) / 2 * window.innerWidth;
                    //vector.y = -(vector.y - 1) / 2 * window.innerHeight;
                    vector.x = (vector.x + 1) / 2 * canvas.width;
                    vector.y = -(vector.y - 1) / 2 * canvas.height;


                    return vector;

                };
                this.pointToScreen = function(intersection){
                    var p = intersection.point.clone();


                    var vector = p.project(pageobject.camera);

                    //vector.x = (vector.x + 1) / 2 * window.innerWidth;
                    //vector.y = -(vector.y - 1) / 2 * window.innerHeight;
                    vector.x = (vector.x + 1) / 2 * canvas.width;
                    vector.y = -(vector.y - 1) / 2 * canvas.height;


                    return vector;

                };
