                this.checkcurfloor = function(){


                    if(!vector3Dref.isbim){
                        return 0;
                    }

                    var curfloor = 0;
                    var curfloorindex = 0;


                    vector3Dref.floorelevation.max = null;
                    vector3Dref.floorelevation.min = null;
                    var floorindexmin = null;
                    var floorindexmax = null;


                    for (var fpi = 0;fpi< parent.floorplans.length;fpi++){


                        if(parent.camera.position.z > parent.floorplans[fpi].Elevation){
                            vector3Dref.floorelevation.min = fpi;
                            floorindexmin = parent.floorplans[fpi].index;
                        }

                        if(parent.camera.position.z < parent.floorplans[fpi].Elevation){
                            vector3Dref.floorelevation.max = fpi;
                            floorindexmax = parent.floorplans[fpi].index;
                        }


                    }

                    if (vector3Dref.floorelevation.max == null && vector3Dref.floorelevation.min != null){
                        vector3Dref.floorelevation.max = vector3Dref.floorelevation.min;
                    }

                    if(vector3Dref.floorelevation.max == null || vector3Dref.floorelevation.min == null){
                        //below or above builiding.
                        curfloor = 0;
                        curfloorindex = parent.floorplans[0].index;
                        //thisthumb.floorelevation.index = 0;

                    }else{
                        curfloor = vector3Dref.floorelevation.min;
                        curfloorindex = floorindexmin;

                        //thisthumb.floorelevation.index = thisthumb.floorelevation.min;
                    }

                    if(vector3Dref.curfloor != curfloor){
                        if (RxCore_GUI_floorlevel != undefined) {
                            RxCore_GUI_floorlevel.setFloorLevel({floorindex : curfloor, storeyindex : curfloorindex});
                        }
                    }

                    vector3Dref.curfloor = curfloor;

                    return vector3Dref.curfloor;


                };

