                this.restoreClipping = function(clippvalues){

                    if(clippvalues == undefined){

                        vector3Dref.clipping(-1, 0, false);
                        return;

                    }

                    var cliponx = ((clippvalues.x > 0) && (clippvalues.x < 100));
                    var clipony = ((clippvalues.y > 0) && (clippvalues.y < 100));
                    var cliponz = ((clippvalues.z > 0) && (clippvalues.z < 100));

                    var clippingon = (cliponx || clipony || cliponz);

                    if(clippingon){
                        vector3Dref.clipping(0, clippvalues.x, true);
                        vector3Dref.clipping(1, clippvalues.y, true);
                        vector3Dref.clipping(2, clippvalues.z, true);
                    }else{
                        vector3Dref.clipping(-1, 0, false);
                    }

                    /*if((clipping.x > 0) && (clipping.x < 100)){
                        vector3Dref.clipping(0, clipping.x, true);
                    }else{
                        //vector3Dref.clipping(0, clipping.x, false);
                    }
                    if((clipping.y > 0) && (clipping.y < 100)){
                        vector3Dref.clipping(1, clipping.y, true);
                    }else{
                        //vector3Dref.clipping(1, clipping.y, false);
                    }
                    if((clipping.z > 0) && (clipping.z < 100)){
                        vector3Dref.clipping(2, clipping.z, true);
                    }else{
                        //vector3Dref.clipping(2, clipping.z, false);
                    }*/

                };

                this.getClipfactor = function(){

                    var percentX = (vector3Dref.globalPlaneX.constant - vector3Dref.xPlaneEnd) / vector3Dref.xPlaneconst;
                    var percentY = (vector3Dref.globalPlaneY.constant - vector3Dref.yPlaneEnd) / vector3Dref.yPlaneconst;
                    var percentZ = (vector3Dref.globalPlaneZ.constant - vector3Dref.zPlaneEnd) / vector3Dref.zPlaneconst;

                    return {
                        xplane : percentX,
                        yplane : percentY,
                        zplane : percentZ,
                        xplaneconst : percentX * 100,
                        yplaneconst : percentY * 100,
                        zplaneconst : percentZ * 100
                    };

                };

                this.clipping = function (plane, constant, onoff) {

                    if(vector3Dref.active3DView){
                        return;
                    }

                    vector3Dref.clippingOn = onoff;
                    if (onoff) {
                        renderer.clippingPlanes = vector3Dref.globalPlanes;
                    }
                    else {
                        renderer.clippingPlanes = Empty;
                        return;
                    }
                    var percent = constant / 100;


                    switch (plane) {
                        case 0: //x plane
                            var newval = vector3Dref.xPlaneEnd + (vector3Dref.xPlaneconst * percent);
                            vector3Dref.globalPlaneX.constant = newval;

                            break;
                        case 1: //y plane

                            newval = vector3Dref.yPlaneEnd + (vector3Dref.yPlaneconst * percent);
                            vector3Dref.globalPlaneY.constant = newval;

                            break;
                        case 2: //z plane
                            newval = vector3Dref.zPlaneEnd + (vector3Dref.zPlaneconst * percent);
                            vector3Dref.globalPlaneZ.constant = newval;
                            break;
                    }






                };
