                this.addCameraViews = function(cameraArr){

                    for(var i = 0; i < cameraArr.length; i++){

                        //var camobj = cameraArr[i];

                        if(cameraArr[i].explodefactor == undefined){
                            var explfctr = 0;
                        }else{
                            explfctr = cameraArr[i].explodefactor;
                        }

                        if(cameraArr[i].clipping == undefined){

                            var clippingplanes = {
                                x : 0,
                                y : 0,
                                z : 0
                            };


                        }else{
                            var clippingplanes = {
                                x : cameraArr[i].clipping.x,
                                y : cameraArr[i].clipping.y,
                                z : cameraArr[i].clipping.z
                            };

                        }

                        if(cameraArr[i].attributes == undefined){
                            var attribs = [];
                        }else{
                            attribs = cameraArr[i].attributes;
                        }

                        var camobj = {
                            position: cameraArr[i].position,
                            name: cameraArr[i].name,
                            tool: cameraArr[i].tool,
                            explodefactor : explfctr,
                            clipping : clippingplanes,
                            thumbnail: null,
                            width: 0,
                            height: 0,
                            image: document.createElement('img'),
                            selectedmesharray : cameraArr[i].selectedmesharray,
                            attributes : attribs
                        };

                        camobj.image.src = cameraArr[i].image;


                        getThumbcanvas(camobj, nCamerathumbwidth).then(function(cameraobj){
                            vector3Dref.cameraSaves.push(cameraobj);
                        });

                        //vector3Dref.cameraSaves.push(cameraArr[i]);
                    }


                };

