                this.saveResetCam = function(){


                    //get3DResetViewName

                    if(vector3Dref.topView != null){
                        //there can be only one.
                        return;
                    }


                    var radius = vector3Dref.getmminUnit(200); //1 mm
                    //console.log(pageobject.DocRef.curcontrol3D);

                    var geometry = new THREE.SphereBufferGeometry(radius, 32, 32);
                    var material = new THREE.MeshBasicMaterial({ color: 0xffff00 });
                    var sphere = new THREE.Mesh(geometry, material);

                    sphere.name = "resetView";

                    var base64String = renderer.domElement.toDataURL();

                    //this.curcontrol3D = 'orbitControl';

                    vector3Dref.topView = {
                        position: pageobject.camera.matrix.toArray(),
                        name: 'resetView',
                        tool: 'orbitControl',
                        explodefactor : 0,
                        thumbnail: null,
                        width: 0,
                        height: 0,
                        image: document.createElement('img'),
                        selectedmesharray : [],
                        attributes : []
                    };

                    vector3Dref.topView.image.src = base64String;

                    getThumbcanvas(vector3Dref.topView, nCamerathumbwidth).then(function(cameraobj){

                        vector3Dref.cameraSaves.unshift(cameraobj);

                        //RxCore_SaveTop3DCamera

                       /*if (Rxcore_GUI_3DCameraSave != undefined) {

                            Rxcore_GUI_3DCameraSave.setCameraSave(cameraobj, DocObj.bActive);

                       }*/


                    });


                    var cposvector = new THREE.Vector3();
                    cposvector.copy(pageobject.camera.position);
                    cposvector.sub(vector3Dref.scene.position);

                    sphere.position.copy(cposvector);
                    sphere.userData.type = "camera";
                    sphere.userData.name = sphere.name;
                    sphere.userData.signature = signature;

                    sphere.visible = false;

                    vector3Dref.markupscene.add(sphere);

                    if (RxCore_GUI_3DMarkupList != undefined) {
                        RxCore_GUI_3DMarkupList.setMarkupList(vector3Dref.markupscene.children, DocObj.bActive);
                    }


                };

