                this.getBelowIntersections = function(origin, walkheight){

                    //var raycaster = new THREE.raycaster();
                    //raycaster.ray.origin.copy( scope.camera.position );
                    //raycaster.ray.origin.y -= scope.walkheight;

                    var intersectFaceObjects = [];
                    var intersectObjects = [];

                    var zoffset = vector3Dref.getfloorheight();


                    var basefloor = walkheight - zoffset;

                    var distbase = origin.z - basefloor;
                    //console.log(distbase);

                    if (distbase > zoffset){
                        var addval = distbase * 0.1;
                        zoffset = distbase + addval;

                    }

                    //raycaster = new THREE.Raycaster( new THREE.Vector3(), new THREE.Vector3( 0, - 1, 0 ), 0, 10 );



                            /*Raycaster( origin : Vector3, direction : Vector3, near : Float, far : Float ) {
                            origin — The origin vector where the ray casts from.
                            direction — The direction vector that gives direction to the ray. Should be normalized.
                            near — All results returned are further away than near. Near can't be negative. Default value is 0.
                            far — All results returned are closer than far. Far can't be lower than near. Default value is Infinity.*/


                    var directionZN = new THREE.Vector3(0, 0, -1).normalize();
                    var directionZP = new THREE.Vector3(0, 0, 1).normalize();

                    var mesharray = vector3Dref.getMeshChildren();

                    var addedmesharray = vector3Dref.getAddedMeshChildren();

                    //raycaster = new THREE.Raycaster( new THREE.Vector3(), new THREE.Vector3( 0, - 1, 0 ), 0, 10 );
                    //raycaster.ray.origin.copy( controls.getObject().position );
                    //raycaster.ray.origin.y -= 10;
                    //origin.z -= zoffset;



                    var raycaster = new THREE.Raycaster( origin, directionZN, 0, zoffset);


                    intersectObjects = raycaster.intersectObjects(mesharray, true);

                    for (var i = 0; i < intersectObjects.length; i++) {

                        if (intersectObjects[i].object.visible && intersectObjects[i].face != null) {

                            if(intersectObjects[i].distance < zoffset){
                                intersectFaceObjects.push(intersectObjects[i]);
                            }

                        }

                    }


                    for (var ami = 0; ami < addedmesharray.length; ami++){

                        intersectObjects = raycaster.intersectObjects(addedmesharray[ami], true);

                        for (var i = 0; i < intersectObjects.length; i++) {

                            if (intersectObjects[i].object.visible && intersectObjects[i].face != null) {

                                if(intersectObjects[i].distance < zoffset){
                                    intersectFaceObjects.push(intersectObjects[i]);
                                }

                            }

                        }

                    }



                    return intersectFaceObjects;


                };

                this.getmeterunit = function(){

                    if(vector3Dref.unit == 1){
                        //var zoffset = (1.8 - zdiff) * modelscale;
                        return 1;

                    }else if (vector3Dref.unit == 0){
                        //zoffset = (1800 - zdiff) * modelscale;
                        return 1000;

                    }else if(vector3Dref.unit == 2){
                        return 3.3;
                    }else if(vector3Dref.unit == 3){
                        return 39.37;
                    }else if (vector3Dref.unit == 4){
                        return 100;
                    }

                    /*if(unit == 1){
                        thispage.walkthroughcontrol.setwalkUnit(1);
                    }else if(unit == 0){
                        thispage.walkthroughcontrol.setwalkUnit(1000);
                    }else if(unit == 2){
                        thispage.walkthroughcontrol.setwalkUnit(3.3);
                    }*/


                };
                this.getmminUnit = function(value){

                    if(vector3Dref.unit == 1){
                        //var zoffset = (1.8 - zdiff) * modelscale;
                        return value / 1000;

                    }else if (vector3Dref.unit == 0){
                        //zoffset = (1800 - zdiff) * modelscale;
                        return value;

                    }else if(vector3Dref.unit == 2){
                        return (value / 25.4) / 12;

                    }else if(vector3Dref.unit == 3){
                        return (value / 25.4);
                    }else if(vector3Dref.unit == 4){
                        return (value / 10);
                    }

                };
                this.getfloorheight = function(){


                    if(vector3Dref.unit == 1){
                        //var zoffset = (1.8 - zdiff) * modelscale;
                        return 1.8;

                    }else if (vector3Dref.unit == 0){
                        //zoffset = (1800 - zdiff) * modelscale;
                        return 1800;

                    }else if(vector3Dref.unit == 2){
                        return 5.9;
                    }else if(vector3Dref.unit == 3){
                        return 69;
                    }else if (vector3Dref.unit == 4){
                        return 180;
                    }

                };

                function getmeshName(name, type){

                    var retname = name;

                    var threerev = parseInt(THREE.REVISION);


                    if (threerev <= 127){

                        retname = name.substring(0, name.length - 2);

                    }else{

                        if(type == "LineSegments"){
                            retname = name.substring(0, name.length - 2);

                        }else{
                            retname = name;
                        }

                    }


                    return retname;


                }


                this.setBlockRef = function(Meshobject){
                    if(Meshobject.name.length == MESHNameGroup){
                        //var meshname = Meshobject.name.substring(0, Meshobject.name.length - 2);

                        var meshname = getmeshName(Meshobject.name, Meshobject.type);


                        var mindex = vector3Dref.blocklistquick.indexOf(meshname);
                        if(mindex != -1){
                            Meshobject.userData.blockRef = mindex;
                        }

                    }else if(Meshobject.name.length == MESHName){
                        var mindex = vector3Dref.blocklistquick.indexOf(Meshobject.name);
                        if(mindex != -1){
                            Meshobject.userData.blockRef = mindex;
                        }

                    }else if(Meshobject.name.length == RVTMESHName){
                        var mindex = vector3Dref.blocklistquick.indexOf(Meshobject.name);
                        if(mindex != -1){
                            Meshobject.userData.blockRef = mindex;
                        }
                    }


                };

                this.checkNewHeight = function(intersects){
                    var returnVector = null;

                    var zoffset = vector3Dref.getfloorheight();

                    //var origin = parent.camera.position.clone();
                    //var directionZN = new THREE.Vector3(0, 0, -1).normalize();
                    //var directionZP = new THREE.Vector3(0, 0, 1).normalize();

                    var distance = 0;
                    var distdiff = 0;
                    var ipoint = null;
                    var rxbimtype = null;

                    if (intersects.length > 0) {
                        for (var i = 0; i < intersects.length; i++) {

                            if (intersects[i].object.visible && intersects[i].face != null ) {

                                //const MESHNameGroup = 24;
                                //const MESHName = 22;

                                if(intersects[i].object.userData.blockRef == undefined){

                                    vector3Dref.setBlockRef(intersects[i].object);

                                }

                                if(intersects[i].object.userData.blockRef){
                                    var rxBimtype = Number(vector3Dref.blocklist[intersects[i].object.userData.blockRef].RxBimType);
                                    //console.log( ' checkNewHeight RxBimType: ', rxBimtype );

                                    if(rxBimtype >= 31 && rxBimtype <= 36 || rxBimtype == 23 || rxBimtype == 3){

                                        distance = intersects[i].distance;
                                        ipoint = intersects[i].point.clone();
                                        break;

                                    }

                                }else{
                                    distance = intersects[i].distance;
                                    ipoint = intersects[i].point.clone();
                                    break;

                                }



                            }
                        }


                        //distdiff = Math.abs(zoffset - distance);


                        if(ipoint != null){
                            returnVector = ipoint;
                        }


                    }
                    return {vec : returnVector, dist : distance};


                };

                this.checkfloorheightAll = function(intersects, zoffset, origin, directionZP, returnVector){
                    var distance = 0;
                    var distdiff = 0;
                    var ipoint = null;
                    var rxbimtype = null;

                    if (intersects.length > 0) {
                        for (var i = 0; i < intersects.length; i++) {

                            if (intersects[i].object.visible && intersects[i].face != null ) {

                                if(intersects[i].object.userData.blockRef == undefined){

                                    vector3Dref.setBlockRef(intersects[i].object);

                                }


                                if(intersects[i].object.userData.blockRef){

                                    var rxBimtype = Number(vector3Dref.blocklist[intersects[i].object.userData.blockRef].RxBimType);
                                    //console.log( 'checkfloorheight RxBimType:', rxBimtype );

                                    if(rxBimtype >= 31 && rxBimtype <= 36 || rxBimtype == 23 || rxBimtype == 3){

                                        distance = intersects[i].distance;
                                        ipoint = intersects[i].point.clone();
                                        break;

                                    }


                                }



                            }
                        }


                        distdiff = Math.abs(zoffset - distance);


                        if(ipoint != null){
                            /*const direction3 = (new THREE.Vector3())
                            .subVectors(DocObj.getCurrentpage().camera.position, ipoint)
                            .normalize();*/
                            returnVector = new THREE.Vector3().copy(directionZP.multiplyScalar(distdiff).add(origin));
                            //DocObj.getCurrentpage().camera.position.copy(direction2.multiplyScalar(distdiff).add(ipoint));
                            //parent.camera.position.copy();
                            //console.log(parent.camera.position);
                            //parent.camera.lookAt(partcenter);

                        }


                    }
                    return returnVector;
                };

                this.checkfloorheight = function(){

                    var returnVector = null;

                    //var zdiff = 0;
                    //var modelscale = vector3Dref.scale;

                    var zoffset = vector3Dref.getfloorheight();

                    var mesharray = vector3Dref.getMeshChildren();
                    var addedmesharray = vector3Dref.getAddedMeshChildren();

                    var raycaster = new THREE.Raycaster();

                    var origin = parent.camera.position.clone();

                    var directionZN = new THREE.Vector3(0, 0, -1).normalize();
                    var directionZP = new THREE.Vector3(0, 0, 1).normalize();

                    raycaster.set ( origin, directionZN);

                    var intersects = raycaster.intersectObjects(mesharray, true);


                    returnVector = vector3Dref.checkfloorheightAll(intersects, zoffset, origin, directionZP,  returnVector);

                    for (var ami = 0; ami < addedmesharray.length; ami++){

                        intersects = raycaster.intersectObjects(addedmesharray[ami], true);

                        returnVector = vector3Dref.checkfloorheightAll(intersects, zoffset, origin, directionZP,  returnVector);
                        //vector3Dref.getarrayMeshIDs(addedmesharray[ami], meshids, meshuserData);

                    }


                    //this.checkfloorheightAll = function(intersects, zoffset, origin,  returnVector){


                    return returnVector;

                };

                function resetmarkupmesh(markupmesh){

                    if (markupmesh.type == "Mesh") {
                        markupmesh.position.x = markupmesh.userData.originalpositionX;
                        markupmesh.position.y = markupmesh.userData.originalpositionY;
                        markupmesh.position.z = markupmesh.userData.originalpositionZ;
                    }

                }

                function resetmesh(mesh){

                    //for (var partix = 0; partix < mesharray.length; partix++) {

                        if(mesh.type == "Group"){
                            for (var gpartix = 0; gpartix < mesh.children.length; gpartix++) {
                                if (mesh.children[gpartix].type == "Mesh" || mesh.children[gpartix].type == "LineSegments") {
                                    mesh.children[gpartix].position.x = 0;
                                    mesh.children[gpartix].position.y = 0;
                                    mesh.children[gpartix].position.z = 0;
                                }
                            }

                        }else{

                            if (mesh.type == "Mesh") {
                                mesh.position.x = 0;
                                mesh.position.y = 0;
                                mesh.position.z = 0;
                            }


                        }

                    //}


                }




                function expandmesh(mesh, distance, pxplodefactor){

                    var bcontinue = false;

                    var meshmarkups = [];


                    if(mesh.type == "Group"){
                        for (var gpartix = 0; gpartix < mesh.children.length; gpartix++) {
                            if (mesh.children[gpartix].type == "Mesh" || mesh.children[gpartix].type == "LineSegments") {

                                if (mesh.children[gpartix].geometry.boundingSphere.center != undefined) {
                                    var partcenter = mesh.children[gpartix].geometry.boundingSphere.center.clone();

                                    meshmarkups = vector3Dref.getAttachedMarkups(mesh.children[gpartix].uuid);

                                    if (pxplodefactor != 0) {
                                        var ppartcenter = partcenter.clone();
                                        var ppartoffset = ppartcenter.multiplyScalar(pxplodefactor);

                                        ppartcenter.multiplyScalar(vector3Dref.scale);

                                        mesh.children[gpartix].position.sub(ppartoffset);

                                        if(meshmarkups.length > 0){
                                            for (var mmix = 0; mmix < meshmarkups.length ; mmix++){
                                                meshmarkups[mmix].position.sub(ppartoffset);
                                            }

                                        }

                                    }
                                    var partoffset = partcenter.multiplyScalar(distance);
                                    partoffset.multiplyScalar(vector3Dref.scale);
                                    mesh.children[gpartix].position.add(partoffset);

                                    if(meshmarkups.length > 0){
                                        for (mmix = 0; mmix < meshmarkups.length ; mmix++){
                                            meshmarkups[mmix].position.add(partoffset);
                                        }

                                    }
                                }

                            }

                        }
                    }else{
                        if (mesh.type == "Mesh") {

                            if (mesh.name === "") {
                                return bcontinue;
                            }

                            if (mesh.geometry.boundingSphere.center != undefined) {
                                var partcenter = mesh.geometry.boundingSphere.center.clone();
                                //console.log(partcenter);

                                meshmarkups = vector3Dref.getAttachedMarkups(mesh.uuid);

                                if (pxplodefactor != 0) {
                                    var ppartcenter = partcenter.clone();
                                    var ppartoffset = ppartcenter.multiplyScalar(pxplodefactor);
                                    ppartcenter.multiplyScalar(vector3Dref.scale);
                                    mesh.position.sub(ppartoffset);

                                    if(meshmarkups.length > 0){
                                        for (mmix = 0; mmix < meshmarkups.length ; mmix++){
                                            meshmarkups[mmix].position.sub(ppartoffset);
                                        }

                                    }

                                }
                                var partoffset = partcenter.multiplyScalar(distance);
                                partoffset.multiplyScalar(vector3Dref.scale);
                                mesh.position.add(partoffset);

                                if(meshmarkups.length > 0){
                                    for (mmix = 0; mmix < meshmarkups.length ; mmix++){
                                        meshmarkups[mmix].position.add(partoffset);
                                    }

                                }



                            }

                        }

                    }

                    return bcontinue;

                }

                this.explode = function (distance) {

                    if (!vector3Dref.doexplode) {
                        return;
                    }
                    var mesharray = vector3Dref.getMeshChildren();

                    if (mesharray.length == 0) {
                        return;
                    }

                    var markuparray = vector3Dref.getMarkupChildren();

                    var meshaddedarray = vector3Dref.getAddedMeshChildren();


                    var scenepos = vector3Dref.originalpos.clone();
                    //var scenepos = vector3Dref.boxCenter.clone();

                    if (distance == 0) {
                        if (mesharray.length > 0) {

                            for (var partix = 0; partix < mesharray.length; partix++) {

                                resetmesh(mesharray[partix]);

                                /*if(mesharray[partix].type == "Group"){
                                    for (var gpartix = 0; gpartix < mesharray[partix].children.length; gpartix++) {
                                        if (mesharray[partix].children[gpartix].type == "Mesh" || mesharray[partix].children[gpartix].type == "LineSegments") {
                                            mesharray[partix].children[gpartix].position.x = 0;
                                            mesharray[partix].children[gpartix].position.y = 0;
                                            mesharray[partix].children[gpartix].position.z = 0;
                                        }
                                    }
                                }*/

                                /*if (mesharray[partix].type == "Mesh") {
                                    mesharray[partix].position.x = 0;
                                    mesharray[partix].position.y = 0;
                                    mesharray[partix].position.z = 0;
                                }*/

                            }
                        }
                        if(markuparray.length > 0){
                            for (var mix = 0; mix < markuparray.length; mix++) {

                                resetmarkupmesh(markuparray[mix]);
                                /*if (markuparray[mix].type == "Mesh") {
                                    markuparray[mix].position.x = markuparray[mix].userData.originalpositionX;
                                    markuparray[mix].position.y = markuparray[mix].userData.originalpositionY;
                                    markuparray[mix].position.z = markuparray[mix].userData.originalpositionZ;
                                }*/
                            }
                        }

                        if(meshaddedarray.length > 0){

                            for (var adix = 0; adix < meshaddedarray.length; adix++) {
                                for (var maix = 0; maix < meshaddedarray[adix].length; maix++) {

                                    resetmesh(meshaddedarray[adix][maix]);

                                }


                            }
                        }

                        if (this.pxplodefactor != 0) {
                            var pscenepos = vector3Dref.originalpos.clone();
                            //var pscenepos = vector3Dref.boxCenter.clone();
                            var psceneoffset = pscenepos.multiplyScalar(this.pxplodefactor);
                            vector3Dref.scene.position.sub(psceneoffset);
                        }
                        this.pxplodefactor = 0;
                        return;
                    }
                    //var size = vector3Dref.boxSize;
                    var sizefactor = Math.round(vector3Dref.boxSize);
                    sizefactor *= 0.00015;
                    distance *= sizefactor;
                    //var meshmarkups = [];

                    //- vector3Dref.pxplodefactor;
                    for (partix = 0; partix < mesharray.length; partix++) {
                        //var partcenter = this.partlist[partix].center;

                        //distance, pxplodefactor
                        if (expandmesh(mesharray[partix], distance, this.pxplodefactor)){
                            continue;
                        }


                    }


                    if(meshaddedarray.length > 0){

                        for (var adix = 0; adix < meshaddedarray.length; adix++) {
                            for (var maix = 0; maix < meshaddedarray[adix].length; maix++) {

                                if (expandmesh(meshaddedarray[adix][maix], distance, this.pxplodefactor)){
                                    continue;
                                }

                            }

                        }
                    }



                    vector3Dref.explodebox = new THREE.Box3().setFromObject(vector3Dref.scene);
                    vector3Dref.explodeboxSize = vector3Dref.explodebox.getSize(new THREE.Vector3()).length();
                    vector3Dref.explodeboxCenter = vector3Dref.explodebox.getCenter(new THREE.Vector3());
                    //parent.camera.lookAt(vector3Dref.explodeboxCenter.x, vector3Dref.explodeboxCenter.y, vector3Dref.boxCenter.z);
                    if (this.pxplodefactor != 0) {
                        pscenepos = vector3Dref.originalpos.clone();
                        //pscenepos = vector3Dref.boxCenter.clone();
                        psceneoffset = pscenepos.multiplyScalar(this.pxplodefactor);
                        vector3Dref.scene.position.sub(psceneoffset);
                    }
                    /*if (this.pxplodefactor != 0) {
                        //var pscenepos = vector3Dref.originalpos.clone();
                        var pscenepos = vector3Dref.boxCenter.clone();
                        var psceneoffset = pscenepos.multiplyScalar(this.pxplodefactor);
                        vector3Dref.scene.position.sub(psceneoffset);

                    }*/
                    var sceneoffset = scenepos.multiplyScalar(distance);
                    //sceneoffset.x /= vector3Dref.scale;
                    //sceneoffset.y /= vector3Dref.scale;
                    //sceneoffset.z /= vector3Dref.scale;
                    //vector3Dref.scene.position.add(sceneoffset);
                    vector3Dref.scene.updateMatrix();
                    vector3Dref.pxplodefactor = distance;
                };

                function getMeshMarkuporigcenter(mesh, center){
                    var positionvector = center.clone();

                    //markuparray[mix].position.x = markuparray[mix].userData.originalpositionX;
                    //markuparray[mix].position.y = markuparray[mix].userData.originalpositionY;
                    //markuparray[mix].position.z = markuparray[mix].userData.originalpositionZ;

                    if(mesh.userData.originalpositionX == undefined){
                        mesh.userData.originalpositionX = center.x;
                    }
                    if(mesh.userData.originalpositionY == undefined){
                        mesh.userData.originalpositionY = center.y;
                    }
                    if(mesh.userData.originalpositionZ == undefined){
                        mesh.userData.originalpositionZ = center.z;
                    }

                    positionvector.set(mesh.userData.originalpositionX,mesh.userData.originalpositionY,mesh.userData.originalpositionZ);

                    return positionvector;

                }
                function getMeshorigcenter(mesh, center){

                    var positionvector = center.clone();

                    if(mesh.userData.centerPosX == undefined){
                        mesh.userData.centerPosX = center.x;
                    }
                    if(mesh.userData.centerPosY == undefined){
                        mesh.userData.centerPosY = center.y;
                    }
                    if(mesh.userData.centerPosZ == undefined){
                        mesh.userData.centerPosZ = center.z;
                    }

                    positionvector.set(mesh.userData.centerPosX,mesh.userData.centerPosY,mesh.userData.centerPosZ);

                    return positionvector;

                }


