                this.setmeshTranspEx = function (mesh, value, reset, bUseParent) {

                    if(reset){

                        if (bUseParent){
                            if(mesh.type == "LineSegments"){
                                mesh.visible = true;
                            }

                            mesh.material.transparent = (mesh.parent.userData.transparent == 1);
                            //mesh.userData.temptransparent = false;
                            mesh.material.opacity = mesh.parent.userData.opacity;

                        }else{
                            if(mesh.type == "LineSegments"){
                                mesh.visible = true;
                            }

                            mesh.material.transparent = (mesh.userData.transparent == 1);
                            mesh.material.opacity = mesh.userData.opacity;
                            //mesh.userData.temptransparent = false;

                        }

                    }else{

                        if(mesh.type == "LineSegments" && value < 1){
                            mesh.visible = false;
                        }else{

                            /*if(mesh.parent.userData.transparent == 1){

                            }*/


                            if(mesh.userData.transparent != 1 && value < 1){
                                //console.log(mesh.parent.userData.transparent);
                                //mesh.userData.temptransparent = true;
                            }else{
                                //mesh.userData.temptransparent = false;
                            }



                             //== 1
                            //mesh.material.transparent = (mesh.parent.userData.transparent == 1);
                            //mesh.material.opacity = mesh.parent.userData.opacity;


                            mesh.material.transparent = true;
                            //vector3Dref.scene.children[i].material.depthWrite = false;
                            mesh.material.opacity = value;

                        }


                    }


                };

                this.setintialTransp = function(parentmesh, childmesh){
                    if (parentmesh.userData.transparent == undefined) {
                        parentmesh.userData.transparent = childmesh.material.transparent ? 1 : 0;
                        //parentmesh.userData.temptransparent = false;
                    }
                    if(parentmesh.userData.opacity == undefined){
                        parentmesh.userData.opacity = childmesh.material.opacity;
                    }

                };

