                this.setBlockTransparencyOld = function(blockid, value, override){
                    var mesharray = vector3Dref.getMeshChildren();
                    if (mesharray.length == 0) {
                        return;
                    }
                    for (var i = 0; i < mesharray.length; i++) {
                        if (mesharray[i].type == "Group") {
                            for (var j = 0; j < mesharray[i].children.length; j++) {
                                if (mesharray[i].children[j].type == "Mesh" || mesharray[i].children[j].type == "LineSegments") {
                                    if(mesharray[i].children[j].name == blockid){
                                        vector3Dref.setintialTransp(mesharray[i], mesharray[i].children[j]);
                                        if(override){
                                            vector3Dref.setmeshTranspEx(mesharray[i].children[j], value, false, true);
                                        }else{
                                            vector3Dref.setmeshTranspEx(mesharray[i].children[j], null, true, true);
                                        }

                                    }

                                }
                            }
                        }
                        if (mesharray[i].type == "Mesh" || mesharray[i].type == "LineSegments") {
                            if(mesharray[i].name == blockid){
                                vector3Dref.setintialTransp(mesharray[i],mesharray[i]);
                                if(override){
                                    vector3Dref.setmeshTranspEx(mesharray[i], value, false, false);
                                }else{
                                    vector3Dref.setmeshTranspEx(mesharray[i], null, true, false);
                                }

                            }


                        }
                    }
                    vector3Dref.doexplode = true;
                    if (value == 0) {
                        vector3Dref.explode(0);
                    }
                    else {
                        vector3Dref.explode(0.001);
                    }
                    vector3Dref.doexplode = false;

                    vector3Dref.scene.updateMatrix();

                };

