                this.setTransparency = function (value, override) {


                    if(value == 1){
                        vector3Dref.resetTransparency();
                        return;
                    }


                    var mesharray = vector3Dref.getMeshChildren();

                    if (mesharray.length == 0) {
                        return;
                    }

                    vector3Dref.setTransparencyArray(mesharray, value, override);

                    var addedmesharray = vector3Dref.getAddedMeshChildren();

                    for (var ami = 0; ami < addedmesharray.length; ami++){

                        vector3Dref.setTransparencyArray(addedmesharray[ami], value, override);
                    }

                    // a small explode used to force correct transparency
                    //workaround for now until a better solution present itself

                    //vector3Dref.setExplodeTransparency(true);

                    vector3Dref.scene.updateMatrix();
                };

                this.resetTransparencyArr = function(mesharray){

                    for (var i = 0; i < mesharray.length; i++) {
                        if (mesharray[i].type == "Group") {


                            for (var j = 0; j < mesharray[i].children.length; j++) {
                                if (mesharray[i].children[j].type == "Mesh" || mesharray[i].children[j].type == "LineSegments") {
                                    vector3Dref.setintialTransp(mesharray[i], mesharray[i].children[j]);

                                    vector3Dref.setmeshTransp(mesharray[i].children[j], null, true, true);

                                }
                            }
                        }
                        if (mesharray[i].type == "Mesh" || mesharray[i].type == "LineSegments") {
                            vector3Dref.setintialTransp(mesharray[i],mesharray[i]);
                            vector3Dref.setmeshTransp(mesharray[i], null, true, false);
                        }
                    }

                };
