                    vector3Dref.setClippingPlanes(vector3Dref.curwidth, vector3Dref.curdepth, vector3Dref.curheight, vector3Dref.curminx, vector3Dref.curmaxx, vector3Dref.curminy, vector3Dref.curmaxy, vector3Dref.curminz, vector3Dref.curmaxz);








