                        //thisthumb.birdseyeobj.ctx
                        thisthumb.floorplanobj.ctx.drawImage(thisthumb.DocRef.pages[thisthumb.pagenumber].smallimagecnv, 0, 0, thisthumb.floorplanobj.floorplan.width, thisthumb.floorplanobj.floorplan.height);
                        thisthumb.floorplandrawn = true;
