                            //thisthumb.birdseyeobj.ctx
                            thisthumb.birdseyeobj.ctx.drawImage(thisthumb.DocRef.pages[thisthumb.pagenumber].smallimagecnv, 0, 0, thisthumb.birdseyeobj.birdseye.width, thisthumb.birdseyeobj.birdseye.height);
                            thisthumb.birdseyedrawn = true;
