                        //thisthumb.birdseyeobj.ctx.fillStyle = "rgb(255,255,255)";
                        //thisthumb.birdseyeobj.ctx.fillRect(0, 0, thisthumb.birdseyeobj.birdseye.width, thisthumb.birdseyeobj.birdseye.height);
                        thisthumb.birdseyeobj.ctx.putImageData(thisthumb.birdseyeobj.imageData, 0, 0, 0, 0, thisthumb.birdseyeobj.birdseye.width, thisthumb.birdseyeobj.birdseye.height);
                        thisthumb.birdseyedrawn = true;
