        function setCanvasTiles(callback, tileArray,foxitpage, visibletiles){


            if(visibletiles){
                if (visibletiles.length > 0){


                    return;
                }

            }
            setTimeout(function() {

                //thispage.visibleTiles

                var rows = foxitpage.rows;
                var columns = foxitpage.columns;

                for (var rc = 0;rc < rows; rc++){

                    tileArray.push([]);

                    for (var cc = 0;cc < columns; cc++){

                        tileArray[rc].push({
                            cnv : document.createElement('canvas'),
                            ctx : null,
                            tilenumber : 0,
                            visible : false,
                            xoffset : 0,
                            yoffset : 0,
                            sharpend : false
                        });

                        tileArray[rc][cc].ctx = tileArray[rc][cc].cnv.getContext('2d');

                    }

                }

                callback(tileArray, foxitpage);

            }, 10);

        }

        function drawTiles(callback, drawntiles, foxitpage, page){

            function drawtilesother(readstate){

                if(!readstate.bcanvasvalid ||  !readstate.bmulticanvas){
                    return readstate;
                }

                for(var cdt = 0; cdt < drawntiles.length; cdt++){
                    if(readstate.tilerow == drawntiles[cdt].r && readstate.tilecolumn == drawntiles[cdt].c){
                        bdraw = false;
                    }
                }

                if (readstate.bdraw){
                    if (foxitpage.transScale == 1){
                        readstate.canvtileArray[readstate.tilerow][readstate.tilecolumn].ctx.drawImage(foxitpage.canvases[readstate.canvtileArray[readstate.tilerow][readstate.tilecolumn].tilenumber], 0,0);

                    }else{
                        var scaledcnv = downScaleCanvas(foxitpage.canvases[readstate.canvtileArray[readstate.tilerow][readstate.tilecolumn].tilenumber], readstate.transScale);
                        readstate.canvtileArray[readstate.tilerow][readstate.tilecolumn].ctx.drawImage(scaledcnv,0,0);
                        scaledcnv = null;

                    }

                }

                return readstate;

        }

            function drawTiles(){

                var bcanvasvalid = false;
                var bmulticanvas = false;

                if (foxitpage.canvases){
                    bcanvasvalid = true;
                    if (foxitpage.canvases.length > 0){
                        bmulticanvas = true;
                    }
                }

                var readstate = {
                    tilerow : 0,
                    tilecolumn : 0,
                    bcanvasvalid : bcanvasvalid,
                    bmulticanvas : bmulticanvas,
                    bdraw : true,
                    scaleupdate : foxitpage.scaleupdate,
                    page : page,
                    drawntiles : drawntiles,
                    nondrawtilecount : 0,
                    transScale  : foxitpage.transScale,
                    canvtileArray : page.canvtileArray
                };

                if (foxitpage.scrollupdate){
                    readstate.canvtileArray = page.bgCanvtileArray;
                }

                if (foxitpage.scaleupdate){
                    readstate.canvtileArray = page.canvtileArray;
                }


                yieldingLoop(readstate, 1, function() {

                    readstate = drawtilesother(readstate);
                    readstate.bdraw = true;

                    if(readstate.tilerow < readstate.canvtileArray.length){
                        if(readstate.tilecolumn < readstate.canvtileArray[readstate.tilerow].length){
                            readstate.tilecolumn ++;

                        }else{
                            readstate.tilecolumn = 0;
                            readstate.tilerow ++;
                        }
                    }



                }, function() {
                    callback(foxitpage);
                });

                (function timer() {


                    setTimeout(timer, 10);


                })();


            }

            drawTiles();

            function yieldingLoop(state,chunksize, ycallback, finished) {
                var i = 0;
                (function chunk() {
                    //var end = Math.min(i + chunksize, count);
                    //var end = (i < chunksize );

                    /*while((state.tilerow < state.canvtileArray.length && state.tilecolumn < state.canvtileArray[state.tilerow].length)) {

                    }*/
                    for (var i = 0; i < chunksize; ++i) {
                        ycallback.call(null, state);
                    }

                    if (state.tilerow < state.canvtileArray.length && state.tilecolumn < state.canvtileArray[state.tilerow].length && state.bcanvasvalid && state.bmulticanvas) {
                        setTimeout(chunk, 0);
                    } else {
                        finished.call(null);
                    }
                })();
            }

        }

        function drawpriorityTiles(callback, foxitpage, page, imagedim) {

            function drawtiles(readstate){

                    if(!readstate.bcanvasvalid ||  !readstate.bmulticanvas){
                        return readstate;
                    }

                    var offscreenwidth = readstate.canvtileArray[readstate.tilerow][readstate.tilecolumn].cnv.width;
                    var offscreenheight = readstate.canvtileArray[readstate.tilerow][readstate.tilecolumn].cnv.height;

                    if((readstate.ulx < canvasowidth && readstate.uly < canvasoheight) && ((readstate.ulx + (offscreenwidth * page.dscalepdf)) > 0 && (readstate.uly + (offscreenheight * page.dscalepdf)) > 0)){

                        if (readstate.transScale == 1){

                            readstate.canvtileArray[i][j].ctx.drawImage(foxitpage.canvases[readstate.canvtileArray[readstate.tilerow][readstate.tilecolumn].tilenumber], 0,0);

                        }else{

                            var scaledcnv = downScaleCanvas(foxitpage.canvases[readstate.canvtileArray[readstate.tilerow][readstate.tilecolumn].tilenumber], readstate.transScale);

                            readstate.canvtileArray[readstate.tilerow][readstate.tilecolumn].ctx.drawImage(scaledcnv,0,0);
                            scaledcnv = null;

                        }
                        readstate.drawntiles.push({r : readstate.tilerow, c : readstate.tilecolumn});

                    }else{
                        readstate.nondrawtilecount ++;
                    }
                    readstate.ulx += (offscreenwidth * page.dscalepdf) - 1;

                    return readstate;

            }


            function drawpTiles(){

                var bcanvasvalid = false;
                var bmulticanvas = false;

                if (foxitpage.canvases){
                    bcanvasvalid = true;
                    if (foxitpage.canvases.length > 0){
                        bmulticanvas = true;
                    }
                }

                var readstate = {
                    tilerow : 0,
                    tilecolumn : 0,
                    ulx : page.dxpdf,
                    uly : page.dypdf,
                    bcanvasvalid : bcanvasvalid,
                    bmulticanvas : bmulticanvas,
                    scaleupdate : foxitpage.scaleupdate,
                    page : page,
                    drawntiles : [],
                    nondrawtilecount : 0,
                    transScale  : foxitpage.transScale,
                    canvtileArray : page.canvtileArray
                };

                if (foxitpage.scrollupdate){
                    readstate.canvtileArray = page.bgCanvtileArray;
                }

                if (foxitpage.scaleupdate){
                    readstate.canvtileArray = page.canvtileArray;
                }



                yieldingLoop(readstate, 1, function() {

                    readstate = drawtiles(readstate);

                    if(readstate.tilerow < readstate.canvtileArray.length){
                        if(readstate.tilecolumn < readstate.canvtileArray[readstate.tilerow].length){
                            readstate.tilecolumn ++;

                        }else{
                            readstate.tilecolumn = 0;
                            readstate.tilerow ++;
                        }
                    }

                }, function() {
                    callback({dtiles : readstate.drawntiles, ndtilesnum : readstate.nondrawtilecount}, foxitpage, imagedim);
                });

                (function timer() {


                    setTimeout(timer, 10);


                })();


            }

            drawpTiles();

            function yieldingLoop(state,chunksize, ycallback, finished) {
                var i = 0;
                (function chunk() {
                    //var end = Math.min(i + chunksize, count);
                    //var end = (i < chunksize );

                    /*while((state.tilerow < state.canvtileArray.length && state.tilecolumn < state.canvtileArray[state.tilerow].length)) {

                    }*/
                    for (var i = 0; i < chunksize; ++i) {
                        ycallback.call(null, state);
                    }

                    if (state.tilerow < state.canvtileArray.length && state.tilecolumn < state.canvtileArray[state.tilerow].length && state.bcanvasvalid && state.bmulticanvas) {
                        setTimeout(chunk, 0);
                    } else {
                        finished.call(null);
                    }
                })();
            }


        }

