                this.updatedimline = function(object, p1, p2){
                    var markuparray = thispage.Vector3DPageObj.getMarkupChildren();

                    if (markuparray.length == 0) {
                        return;
                    }

                    for (var i = 0; i < markuparray.length; i++) {
                        if(markuparray[i].userData.type == "dimension"){
                            if(markuparray[i].userData.parentref == object && markuparray[i].type == "LineSegments"){

                                var linepos = new Float32Array([p1.x, p1.y, p1.z, p2.x, p2.y, p2.z]);
                                markuparray[i].geometry.setAttribute('position', new THREE.BufferAttribute(linepos, 3));
                                markuparray[i].geometry.attributes.position.needsUpdate = true;

                            }
                        }

                    }

                };

                this.move3DMarkupdimPoint = function(object, position, pointindex){
                    var markuparray = thispage.Vector3DPageObj.getMarkupChildren();
                    if (markuparray.length == 0) {
                        return;
                    }
                    if (pointindex == null){
                        return;
                    }

                    var bmoved = false;

                    for (var i = 0; i < markuparray.length; i++) {
                        if (markuparray[i].userData.selected) {
                            if(markuparray[i].userData.type == "dimension"){

                                var points = [];

                                if(markuparray[i].uuid == object && markuparray[i].type == "Points" ){

                                    markuparray[i].updateMatrixWorld();

                                    var positions = markuparray[i].geometry.getAttribute('position');


                                    var p1 = position.clone();

                                    for (var c=0; c < positions.count - 1; c++){

                                        var vstart = c * positions.itemSize;

                                        var x = positions.array[vstart];
                                        var y = positions.array[vstart + 1];
                                        var z = positions.array[vstart + 2];


                                        var pos = new THREE.Vector3(x, y, z);

                                        markuparray[i].localToWorld(pos);

                                        if(pointindex == c){
                                            points.push(p1);

                                        }else{
                                            points.push(pos);
                                        }


                                    }

                                    var dist = points[0].distanceTo ( points[1] );
                                    var midpoint = new THREE.Vector3();
                                    midpoint.subVectors( points[0], points[1] ).setLength( dist *  0.5).add( points[1] );
                                    points.push(midpoint);

                                    var pointspos = new Float32Array([points[0].x, points[0].y, points[0].z, points[1].x, points[1].y, points[1].z,points[2].x, points[2].y, points[2].z]);
                                    markuparray[i].geometry.setAttribute( 'position', new THREE.Float32BufferAttribute( pointspos, 3 ) );

                                    markuparray[i].userData.dimtext = thispage.Vector3DPageObj.setdimvalue(dist);

                                    markuparray[i].userData.distance = dist;

                                    thispage.updatedimline(object, points[0], points[1]);

                                    markuparray[i].geometry.attributes.position.needsUpdate = true;

                                    markuparray[i].updateMatrixWorld();

                                    //markuparray[i].userData.Unit = Unitofmeasure;
                                    //markuparray[i].userData.SubUnit = SubmeasureUnit;

                                    bmoved = true;

                                }

                            }
                            //check if object is the same

                            //remove mesh from markup scene
                            //markuparray[i].position.set(position);
                            //thispage.Vector3DPageObj
                        }
                        //thispage.Vector3DPageObj.scene.updateMatrix();
                        //Viewer3D.update();
                    }
                    if(bmoved){
                        if (RxCore_GUI_3DMarkupList != undefined) {
                            RxCore_GUI_3DMarkupList.setMarkupList(markuparray, DocObj.bActive);
                        }
                        this.Vector3DPageObj.updateblocklist();
                    }

                };

