                this.resetMesh = function (mesh) {
                    var meshindex = 0;
                    if (mesh.userData.visible == undefined) {
                        (mesh.visible) ? 1 : 0;
                    }
                    if (mesh.userData.tempvisible == undefined) {
                        mesh.userData.tempvisible = mesh.visible;
                    }
                    if (!mesh.userData.isSpace) {
                        //this.Vector3DPageObj.partlist[thispage.Vector3DPageObj.scene.children[modelidx].children[i].name].resetvisible();
                        if (mesh.userData.visible) {
                            mesh.userData.tempvisible = (mesh.userData.visible == 1);
                        }
                        else {
                            //mesharray[i].userData.tempvisible = (mesharray[i].userData.visible == 1);
                            mesh.userData.visible = (mesh.visible) ? 1 : 0;
                        }
                        //scope.tempvisible = (scope.visible == 1);
                        if (mesh.userData.tempvisible) {
                            mesh.visible = mesh.userData.tempvisible;
                        }
                        else {
                            mesh.userData.tempvisible = mesh.visible;
                        }
                        mesh.userData.selected = false;
                        mesh.userData.usetempfacecolor = false;
                        if (mesh.userData.facecolor != undefined) {
                            if (mesh.type == "LineSegments") {
                                //console.log(mesh.userData.facecolor);
                            }
                            mesh.material.color.setHex(mesh.userData.facecolor);
                        }
                        if (mesh.userData.meshcolors) {
                            if (mesh.userData.meshcolors.length > 1) {
                                mesh.material.color = new THREE.Color(mesh.userData.meshcolors[meshindex]);
                                if (meshindex < mesh.userData.meshcolors.length) {
                                    meshindex++;
                                }
                            }
                            else if (mesh.userData.facecolor) {
                                mesh.material.color = setHex(mesh.userData.facecolor);
                            }
                        }
                    }
                };

