                this.reset3DBlockColorsAll = function(mesharray){

                    for (var i = 0; i < mesharray.length; i++) {

                        if (mesharray[i].type == "Group") {
                            for (var j = 0; j < mesharray[i].children.length; j++) {
                                if ( mesharray[i].children[j].type == "Mesh") {

                                    if(mesharray[i].children[j].userData.facecolor == undefined){


                                        mesharray[i].children[j].userData.facecolor = mesharray[i].children[j].material.color.getHex();
                                    }else{

                                        mesharray[i].children[j].material.color.setHex(mesharray[i].children[j].userData.facecolor);
                                    }

                                }
                            }
                        }else  if ( mesharray[i].type == "Mesh") {
                            if (mesharray[i].name === "") {
                                continue;
                            }

                            if(mesharray[i].userData.facecolor == undefined){

                                mesharray[i].userData.facecolor = mesharray[i].material.color.getHex();

                            }else{
                                mesharray[i].material.color.setHex(mesharray[i].userData.facecolor);
                            }

                        }

                    }

                };
                this.reset3DBlockColors = function(){
                    var mesharray = thispage.Vector3DPageObj.getMeshChildren();
                    if (mesharray.length == 0) {
                        return;
                    }
                    thispage.reset3DBlockColorsAll(mesharray);

                    var addedmesharray = DocObj.getCurrentpage().Vector3DPageObj.getAddedMeshChildren();

                    if (addedmesharray.length == 0) {
                        return;
                    }

                    for (var i = 0; i < addedmesharray.length; i++) {
                        thispage.reset3DBlockColorsAll(addedmesharray[i]);
                    }
                };

                this.set3DBlockColorOld = function (name, color, override) {
                    var mesharray = thispage.Vector3DPageObj.getMeshChildren();
                    if (mesharray.length == 0) {
                        return;
                    }
                    for (var i = 0; i < mesharray.length; i++) {
                        if (mesharray[i].type == "Group") {
                            for (var j = 0; j < mesharray[i].children.length; j++) {
                                if (mesharray[i].children[j].type == "Mesh") {
                                    if (mesharray[i].children[j].userData.facecolor == undefined) {
                                        mesharray[i].children[j].userData.facecolor = mesharray[i].children[j].material.color.getHex();
                                    }
                                    if (mesharray[i].children[j].name == name && mesharray[i].children[j].visible) {
                                        if (override) {
                                            mesharray[i].children[j].material.color = new THREE.Color(color);
                                        }
                                        else {
                                            mesharray[i].children[j].material.color.setHex(mesharray[i].children[j].userData.facecolor);
                                        }
                                    }
                                }
                            }
                        }
                        else if (mesharray[i].type == "Mesh") {
                            if (mesharray[i].name === "") {
                                continue;
                            }
                            if (mesharray[i].userData.facecolor == undefined) {
                                mesharray[i].userData.facecolor = mesharray[i].material.color.getHex();
                            }
                            if (mesharray[i].name == name && mesharray[i].visible) {
                                if (override) {
                                    mesharray[i].material.color = new THREE.Color(color);
                                }
                                else {
                                    mesharray[i].material.color.setHex(mesharray[i].userData.facecolor);
                                }
                            }
                        }
                    }
                };
                this.set3DBlockDistance = function(name, distance, direction, override){
                    var meshobject = thispage.Vector3DPageObj.getMeshByName(name);

                    var directionvector = new THREE.Vector3(direction.x, direction.y, direction.z).normalize();
                    directionvector.multiplyScalar ( distance );

                    var positionvector = new THREE.Vector3();


                    if(meshobject == null){
                        return;
                    }else{
                        if(meshobject.userData.posX == undefined){
                            meshobject.userData.posX = meshobject.position.x;
                        }
                        if(meshobject.userData.posY == undefined){
                            meshobject.userData.posY = meshobject.position.y;
                        }
                        if(meshobject.userData.posZ == undefined){
                            meshobject.userData.posZ = meshobject.position.z;
                        }



                        if (meshobject.visible) {
                            if (override) {

                                //positionvector.set(position.x, position.y, position.z);
                                meshobject.position.add(directionvector);

                            }
                            else {
                                positionvector.set(meshobject.userData.posX,meshobject.userData.posY,meshobject.userData.posZ);
                                meshobject.position.copy(positionvector);

                            }
                        }

                    }

                };
                this.set3DBlockPosition = function(name, position, override){
                    var meshobject = thispage.Vector3DPageObj.getMeshByName(name);
                    var positionvector = new THREE.Vector3();

                    if(meshobject == null){
                        return;
                    }else{
                        if(meshobject.userData.posX == undefined){
                            meshobject.userData.posX = meshobject.position.x;
                        }
                        if(meshobject.userData.posY == undefined){
                            meshobject.userData.posY = meshobject.position.y;
                        }
                        if(meshobject.userData.posZ == undefined){
                            meshobject.userData.posZ = meshobject.position.z;
                        }

                        if (meshobject.visible) {
                            if (override) {

                                positionvector.set(position.x, position.y, position.z);
                                meshobject.position = positionvector.clone();

                            }
                            else {
                                positionvector.set(meshobject.userData.posX,meshobject.userData.posY,meshobject.userData.posZ);
                                meshobject.position = positionvector.clone();

                            }
                        }

                    }

                };
                this.set3DBlockColor = function (name, color, override) {
                    var meshobject = thispage.Vector3DPageObj.getMeshByName(name);
                    if (meshobject == null) {
                        return;
                    }
                    else {
                        if (meshobject.userData.facecolor == undefined) {
                            meshobject.userData.facecolor = meshobject.material.color.getHex();
                        }
                        if (meshobject.visible) {
                            if (override) {
                                meshobject.material.color = new THREE.Color(color);
                                meshobject.userData.tempfacecolor = meshobject.material.color.getHex();
                                meshobject.userData.usetempfacecolor = true;

                            }
                            else {
                                if (meshobject.userData.facecolor != undefined) {
                                    meshobject.material.color.setHex(meshobject.userData.facecolor);
                                    meshobject.userData.usetempfacecolor = false;
                                }
                            }
                        }
                    }
                };
