                this.vectorbinprogress = function (ev) {
                    if (ev.lengthComputable) {
                        //showDownloadDialog();
                        var percentComplete = Math.round(ev.loaded * 100 / ev.total);
                        if (percentComplete == 100) {
                            //hideDownloadDialog();
                            if (RxCore_GUI_Download != undefined) {
                                RxCore_GUI_Download.setDownload("hide");
                            }
                        }
                    }
                };
