                this.createEmptyVectorpage = function(){

                    var yscale = 0.0;
                    var xscale = 0.0;
                    var dxlocal = 0.0;
                    var dylocal = 0.0;
                    var dscalelocal = 0.0;
                    var dscalelocalOne = 0.0;
                    var imagewidth = 0;
                    var imageheight = 0;

                    var compareobject = {role : 1, bgColor : overlayBGColor, fgColor : overlayFGColor};

                    var vectorpageobj = {
                        x : 0,
                        y : 0,
                        w : 0,
                        h : 0,
                        scale : 1,
                        offsetx : 0,
                        offsety : 0,
                        iscompare : true,
                        bgcolor : overlayBGColor,
                        fgcolor : overlayFGColor
                    };


                    /*if (pagexmldata.iscompare){
                        createempty(pagexmldata);
                    }*/


                    if(thispage.loadbackgroundimage){

                        if (thispage.MainImageWidthBckGrnd != undefined ) {
                            vectorpageobj.w = parseInt(thispage.MainImageWidthBckGrnd);
                            vectorpageobj.h = parseInt(thispage.MainImageHeightBckGrnd);
                            vectorpageobj.scaling = parseFloat(thispage.MainImageScalingBckGrnd);

                        }

                    }else if (thispage.loadoverlayimage){

                            if(thispage.MainImageWidthFrGrnd != undefined){
                                vectorpageobj.w = parseInt(thispage.MainImageWidthFrGrnd);
                                vectorpageobj.h = parseInt(thispage.MainImageHeightFrGrnd);
                                vectorpageobj.scaling = parseFloat(thispage.MainImageScalingFrGrnd);

                            }

                    }else if(thispage.loadbackgroundpdf){

                        if(thispage.PDFWidthBckGrnd != undefined){
                            vectorpageobj.w = thispage.PDFWidthBckGrnd;
                            vectorpageobj.h = thispage.PDFHeightBckGrnd;
                            vectorpageobj.scaling = 1;

                        }


                    }else if(thispage.loadoverlaypdf){

                        if(thispage.PDFWidthFrGrnd != undefined){
                            vectorpageobj.w = thispage.PDFWidthFrGrnd;
                            vectorpageobj.h = thispage.PDFHeightFrGrnd;
                            vectorpageobj.scaling = 1;

                        }


                            //get pdf info to set vectorpage object width and heigh
                    }else{

                        return;

                    }





                    /*var backroundlayer = {
                        index : 0,
                        color : pageobject.bgcolor,
                        state : 1,
                        name : "backgroundlayer"
                    };

                    var overlaylayer = {
                        index : 1,
                        color : pageobject.fgcolor,
                        state : 1,
                        name : "overlaylayer"
                    };*/

                    //scope.flag = 1;

                    /*scope.x = pageobject.x;
                    scope.y = pageobject.y;
                    scope.w = pageobject.w;
                    scope.h = pageobject.h;

                    scope.scale = pageobject.scale;
                    scope.offsetx = pageobject.offsetx;
                    scope.offsety = pageobject.offsety;

                    scope.width = vectorobj.w - vectorobj.x;
                    scope.height = vectorobj.h - vectorobj.y;*/


                    thispage.VectorPageObj = new VectorPageObject(thispage, vectorpageobj, false, compareobject);


                    if(thispage.VectorPageObj == undefined){
                        return;
                    }

                    if (thispage.VectorPageObj.height == 0 || thispage.VectorPageObj.width == 0) {
                        return;
                    }

                    thispage.originalwidth = thispage.VectorPageObj.width;
                    thispage.originalheight = thispage.VectorPageObj.height;
                    yscale = fixedScaleSize.height / thispage.VectorPageObj.height; //thispage.MainImageHeight;
                    xscale = fixedScaleSize.width / thispage.VectorPageObj.width; // thispage.MainImageWidth;
                    dscalelocalOne = Math.min(xscale, yscale);
                    thispage.fixedScale = dscalelocalOne;
                    yscale = canvasoheight / thispage.VectorPageObj.height; //thispage.MainImageHeight;
                    xscale = canvasowidth / thispage.VectorPageObj.width; // thispage.MainImageWidth;
                    dscalelocal = Math.min(xscale, yscale);
                    dxlocal = (canvasowidth - (thispage.VectorPageObj.width * dscalelocal)) / 2;
                    dylocal = (canvasoheight - (thispage.VectorPageObj.height * dscalelocal)) / 2;

                    thispage.width = thispage.VectorPageObj.width;
                    thispage.height = thispage.VectorPageObj.height;

                    thispage.setvectordim(dxlocal, dylocal, dscalelocal);
                    thispage.printobj.setDocSize(thispage.VectorPageObj.width, thispage.VectorPageObj.height);


                    //addimages for background and overlay

                    //var compareobject = {role : 1, bgColor : overlayBGColor, fgColor : overlayFGColor};
                    if(thispage.loadbackgroundimage){


                        var imagebgobject = {
                            dlayer : 0,
                            drawmode : 13,
                            lstate : 1,
                            x1 : 0,
                            y1 : 0,
                            x2 : thispage.MainImageWidthBckGrnd,
                            y2 : thispage.MainImageHeightBckGrnd,
                            imagestr : thispage.Vector2DImageSRCBckGrnd
                        };

                        thispage.VectorPageObj.addimage(imagebgobject, true, compareobject);



                    }
                    if (thispage.loadoverlayimage){

                        var imagebgobject = {
                            dlayer : 1,
                            drawmode : 13,
                            lstate : 1,
                            x1 : 0,
                            y1 : 0,
                            x2 : thispage.MainImageWidthFrGrnd,
                            y2 : thispage.MainImageHeightFrGrnd,
                            imagestr : thispage.Vector2DImageSRCFrGrnd
                        };

                        thispage.VectorPageObj.addimage(imagebgobject, false, compareobject);

                    }


                    if(thispage.loadbackgroundpdf){

                        var imagebgobject = {
                            dlayer : 0,
                            drawmode : 13,
                            lstate : 1,
                            x1 : 0,
                            y1 : 0,
                            x2 : thispage.PDFWidthBckGrnd,
                            y2 : thispage.PDFHeightBckGrnd
                            //imagestr : thispage.Vector2DImageSRCBckGrnd
                        };

                        thispage.VectorPageObj.addpdfimage(imagebgobject, true, compareobject);

                    }

                    if(thispage.loadoverlaypdf){

                        var imagebgobject = {
                            dlayer : 1,
                            drawmode : 13,
                            lstate : 1,
                            x1 : 0,
                            y1 : 0,
                            x2 : thispage.PDFWidthFrGrnd,
                            y2 : thispage.PDFHeightFrGrnd
                            //imagestr : thispage.Vector2DImageSRCFrGrnd
                        };

                        thispage.VectorPageObj.addpdfimage(imagebgobject, false, compareobject);


                    }


                    /*if(thispage.loadoverlayvectors){
                        thispage.loadfgvectors();
                    }*/


                };

