                this.getVectorSearchListSearch = function(searchobj){

                    var searcharray = thispage.indexdivTexts();
                    var casesense = searchobj.casesens;
                    var str = searchobj.expr;

                    for (var txtcnt = 0; txtcnt < searcharray.length; txtcnt++) {
                        if (!casesense) {
                            var searchexpr = str.toLowerCase();
                            var searchstr = searcharray[txtcnt].toLowerCase();
                        }
                        else {
                            searchexpr = str;
                            searchstr = searcharray[txtcnt];
                        }
                        var found = false;
                        var pos = searchstr.search(searchexpr);
                        if (pos == -1) {
                            found = false;
                        }
                        else if (pos >= 0) {
                            found = true;
                        }
                        if (found) {
                            var resultobj = {
                                page: thispage.pagenumber,
                                indx: txtcnt,
                                searchtext: searcharray[txtcnt],
                                pos: pos,
                                length: str.length,
                                rect : {}
                            };
                            searchobj.matcharray.push(resultobj);
                        }
                    }

                };

