                this.getsearchpanupdate = function (x, y) {
                    //var centery = canvasoheight / 2;
                    //var centerx = canvasowidth / 2;


                    var centery = canvasoheightsize / 2;
                    var centerx = canvasowidthsize / 2;
                    var canvasowidth = canvasowidthsize;
                    var canvasoheight = canvasoheightsize;


                    var panx = 0;
                    var pany = 0;
                    if (thispage.getpageRotation() != 0) {
                        var rotpos = thispage.getrotcoords(centerx, centery, x, y, -thispage.getpageRotation());
                        distancexright = Math.max(rotpos.x, canvasowidth) - Math.min(rotpos.x, canvasowidth);
                        if (Math.max(rotpos.x, canvasowidth) == rotpos.x) {
                            move = 1;
                            //panx =  distancexright + 300;
                            panx = rotpos.x - centerx;
                        }
                        else if (distancexright < 300) {
                            move = 1;
                            panx = rotpos.x - centerx;
                        }
                        distanceybottom = Math.max(rotpos.y, canvasoheight) - Math.min(rotpos.y, canvasoheight);
                        if (Math.max(rotpos.y, canvasoheight) == rotpos.y) {
                            move = 2;
                            pany = rotpos.y - centery;
                        }
                        else if (distanceybottom < 100) {
                            move = 2;
                            pany = rotpos.y - centery;
                        }
                        distancexleft = Math.max(rotpos.x, 0) - Math.min(rotpos.x, 0);
                        if (Math.min(rotpos.x, 0) == rotpos.x) {
                            move = 0;
                            panx = -(centerx - rotpos.x);
                        }
                        else if (distancexleft < 100) {
                            move = 0;
                            panx = -(centerx - rotpos.x);
                        }
                        distanceytop = Math.max(rotpos.y, 0) - Math.min(rotpos.y, 0);
                        if (Math.min(rotpos.y, 0) == rotpos.y) {
                            move = 3;
                            pany = -(centery - rotpos.y);
                        }
                        else if (distanceytop < 100) {
                            move = 3;
                            pany = -(centery - rotpos.y);
                        }
                        /*switch (thispage.getpageRotation()) {
                            case 90:
                                //this.dxvector -= sy;
                                //this.dyvector += sx;
                                thispage.pan_update(pany,-panx);

                                break;
                            case 180:
                                //this.dxvector += sx;
                                //this.dyvector += sy;
                                thispage.pan_update(-panx,-pany);
                                break;
                            case 270:
                                //this.dxvector += sy;
                                //this.dyvector -= sx;
                                thispage.pan_update(-pany,panx);
                                break;
                        }*/
                        //thispage.pan_update(panx,pany);
                    }
                    else {
                        var distancexright = Math.max(x, canvasowidth) - Math.min(x, canvasowidth);
                        if (Math.max(x, canvasowidth) == x) {
                            move = 1;
                            //panx =  distancexright + 300;
                            panx = x - centerx;
                        }
                        else if (distancexright < 300) {
                            move = 1;
                            panx = x - centerx;
                        }
                        var distanceybottom = Math.max(y, canvasoheight) - Math.min(y, canvasoheight);
                        if (Math.max(y, canvasoheight) == y) {
                            move = 2;
                            pany = y - centery;
                        }
                        else if (distanceybottom < 100) {
                            move = 2;
                            pany = y - centery;
                        }
                        var distancexleft = Math.max(x, 0) - Math.min(x, 0);
                        if (Math.min(x, 0) == x) {
                            var move = 0;
                            panx = -(centerx - x);
                            //var panx = distancexleft - 200;
                        }
                        else if (distancexleft < 100) {
                            move = 0;
                            panx = -(centerx - x);
                        }
                        var distanceytop = Math.max(y, 0) - Math.min(y, 0);
                        if (Math.min(y, 0) == y) {
                            move = 3;
                            pany = -(centery - y);
                        }
                        else if (distanceytop < 100) {
                            move = 3;
                            pany = -(centery - y);
                        }
                        //console.log('panupdate show search');
                        //thispage.pan_update(panx,pany);
                    }


                    return { x: panx, y: pany };
                };
