                function getPagestats() {
                    if (thispage.usevectorxml) {

                        if(thispage.VectorPageObj == undefined){
                            return;
                        }

                        var stats = {
                            dscale: thispage.dscalevector,
                            dx: thispage.dxvector,
                            dy: thispage.dyvector,
                            width: thispage.VectorPageObj.width,
                            height: thispage.VectorPageObj.height
                        };
                    }
                    else if (thispage.usepdfjs) {
                        stats = {
                            dscale: thispage.dscalepdf,
                            dx: thispage.dxpdf,
                            dy: thispage.dypdf,
                            width: thispage.pdfpagewidth,
                            height: thispage.pdfpageheight,
                            mousepoint : {x: 0, y: 0},
                            offsetpoint : {x: 0, y: 0},
                            offsetcenter : {x: 0, y: 0},
                            bIn : false,
                            dfactor : 1
                        };
                    }
                    else {
                        stats = {
                            dscale: thispage.dscale,
                            dx: thispage.dx,
                            dy: thispage.dy,
                            width: thispage.MainImageWidth,
                            height: thispage.MainImageHeight
                        };
                    }
                    return stats;
                }
                function ScaleZoomInPDF(center, factor, stats, bIn) {

                    var pcanvheight = thispage.offscreenheight;
                    var pcanvwidth = thispage.offscreenwidth;

                    /*if (thispage.usedincomposite && thispage.compositereference != undefined) {
                        //var pcanvheight = thispage.compositereference.ovpagecanvas.height;
                        //var pcanvwidth = thispage.compositereference.ovpagecanvas.width;
                        var pcanvheight = thispage.compositereference.overlaypage.getheight();
                        var pcanvwidth = thispage.compositereference.overlaypage.getwidth();
                    }
                    else {

                        if(thispage.getpageRotation() != 0){

                            pcanvwidth = thispage.originalPDFwidth;
                            pcanvheight = thispage.originalPDFheight;


                        }

                    }*/
                    var bScaleChanged = false;
                    thispage.bMinzoom = false;
                    var bWidthlocked = false;
                    var prevcenterxpdf = (canvasowidth - (pcanvwidth * stats.dscale)) / 2;
                    var prevcenterypdf = (canvasoheight - (pcanvheight * stats.dscale)) / 2;

                    prevcenterxpdf = (canvasowidthsize - (pcanvwidth * stats.dscale)) / 2;
                    prevcenterypdf = (canvasoheightsize - (pcanvheight * stats.dscale)) / 2;


                    var diffxpdf = prevcenterxpdf - stats.dx;
                    var diffypdf = prevcenterypdf - stats.dy;

                    var wscale = ((pcanvwidth * stats.dscale) / thispage.pdfpagewidth) * factor;
                    var hscale = ((pcanvheight * stats.dscale) / thispage.pdfpageheight) * factor;


                    if(thispage.getpageRotation() != 0){

                        if(thispage.getpageRotation() == 90 || thispage.getpageRotation() == 270){

                            if(thispage.bpagesizeupdated){
                                wscale = ((pcanvwidth * stats.dscale) / thispage.pdfpagewidth) * factor;
                                hscale = ((pcanvheight * stats.dscale) / thispage.pdfpageheight) * factor;

                            }else{
                                wscale = ((pcanvwidth * stats.dscale) / thispage.pdfpageheight) * factor;
                                hscale = ((pcanvheight * stats.dscale) / thispage.pdfpagewidth) * factor;

                            }


                        }



                    }
                    var temppdfscale = Math.min(wscale, hscale);
                    temppdfscale *= factor;
                    stats.dscale = stats.dscale * factor;
                    bScaleChanged = true;

                    var centerxpdf = ((canvasowidth - (pcanvwidth * stats.dscale)) / 2);
                    var centerypdf = ((canvasoheight - (pcanvheight * stats.dscale)) / 2);

                    centerxpdf = ((canvasowidthsize - (pcanvwidth * stats.dscale)) / 2);
                    centerypdf = ((canvasoheightsize - (pcanvheight * stats.dscale)) / 2);


                    if(thispage.getpageRotation() != 0){

                        if(thispage.bpagesizeupdated){
                            if(thispage.getpageRotation() == 90 || thispage.getpageRotation() == 270){
                                centerxpdf = ((canvasoheight - (pcanvwidth * stats.dscale)) / 2);
                                centerypdf = ((canvasowidth - (pcanvheight * stats.dscale)) / 2);

                                centerxpdf = ((canvasoheightsize - (pcanvwidth * stats.dscale)) / 2);
                                centerypdf = ((canvasowidthsize - (pcanvheight * stats.dscale)) / 2);

                            }
                        }

                    }



                    if (center) {
                        stats.dx = centerxpdf;
                        stats.dy = centerypdf;
                    }
                    else {
                        if (bScaleChanged) {
                            stats.dx = centerxpdf - (diffxpdf * factor);
                            stats.dy = centerypdf - (diffypdf * factor);
                        }
                        else {
                            stats.dx = centerxpdf - diffxpdf;
                            stats.dy = centerypdf - diffypdf;
                        }
                    }
                    /*if (pcanvwidth <= canvasowidth) {
                        if (!thispage.DocRef.pagelocked) {
                            stats.dx = centerxpdf;
                        }
                        bWidthlocked = true;
                    }*/

                    if (pcanvwidth <= canvasowidthsize) {
                        if (!thispage.DocRef.pagelocked) {
                            stats.dx = centerxpdf;
                        }
                        bWidthlocked = true;

                    }

                    /*if (pcanvwidth * stats.dscale <= canvasowidth) {
                        if (!thispage.DocRef.pagelocked) {
                            stats.dx = (canvasowidth - (pcanvwidth * stats.dscale)) / 2;
                        }
                        bWidthlocked = true;
                    }*/

                    if (pcanvwidth * stats.dscale <= canvasowidthsize) {
                        if (!thispage.DocRef.pagelocked) {
                            stats.dx = (canvasowidthsize - (pcanvwidth * stats.dscale)) / 2;
                        }
                        bWidthlocked = true;
                    }


                    thispage.setpagedimsize(stats.dx, stats.dy, (pcanvwidth * stats.dscale), (pcanvheight * stats.dscale), false);

                    //DocObj.draw_mpagepdf();
                    //thispage.renderPDFpagescale();
                    var startx = stats.dx;
                    var starty = stats.dy;
                    var endx = (stats.width * stats.dscale) + startx;
                    var endy = (stats.height * stats.dscale) + starty;
                    return {
                        dscale: stats.dscale,
                        dx: stats.dx,
                        dy: stats.dy,
                        startx: startx,
                        starty: starty,
                        endx: endx,
                        endy: endy,
                        bWidthlocked: bWidthlocked,
                        mousepoint : stats.mousepoint,
                        offsetpoint : stats.offsetpoint,
                        offsetcenter : stats.offsetcenter,
                        bIn : bIn,
                        dfactor : factor
                    };
                }
                function ScaleZoomUpdate(stats, sx, sy, sWide, sHi) {
                    var newscale = 1.0;
                    var factor = 0.0;
                    var pointXtoCenter = 0;
                    var pointYtoCenter = 0;
                    var canvdiv2H = canvasoheight / 2;
                    var canvdiv2W = canvasowidth / 2;
                    var CanvRotRad = thispage.getpageRotation() * (Math.PI / 180);
                    //point to align to centre in display coordinates.
                    var rectCenterX = sx + (sWide / 2);
                    var rectCenterY = sy + (sHi / 2);
                    var ox1 = sx / stats.dscale;
                    var oy1 = sy / stats.dscale;
                    var ox2 = (sx + sWide) / stats.dscale;
                    var oy2 = (sy + sHi) / stats.dscale;
                    var hscale = sHi / stats.dscale;
                    var wscale = sWide / stats.dscale;
                    var yscale = canvasoheight / stats.height;
                    var xscale = canvasowidth / stats.width;
                    var imagescaleheight = stats.height * stats.dscale;
                    switch (thispage.getpageRotation()) {
                        case 90:
                            pointXtoCenter = rectCenterX - canvdiv2W;
                            pointYtoCenter = rectCenterY - canvdiv2H;
                            oy1 = (stats.dy + pointXtoCenter);
                            ox1 = (stats.dx - pointYtoCenter);
                            stats.dx = ox1;
                            stats.dy = oy1;
                            if (hscale > 0 && wscale > 0) {
                                yscale = stats.dscale * canvasoheight / sHi;
                                xscale = stats.dscale * canvasowidth / sWide;
                            }
                            newscale = Math.min(yscale, xscale);
                            factor = newscale / stats.dscale;
                            var tempstats = {
                                dscale: stats.dscale,
                                dx: stats.dx,
                                dy: stats.dy,
                                startx: stats.dx,
                                starty: stats.dy,
                                endx: (stats.width * stats.dscale) + stats.dx,
                                endy: (stats.height * stats.dscale) + stats.dy
                            };
                            setPagestats(tempstats, false);
                            thispage.ZoomIn(factor, false, false);
                            break;
                        case 270:
                            pointXtoCenter = rectCenterX - canvdiv2W;
                            pointYtoCenter = rectCenterY - canvdiv2H;
                            oy1 = (stats.dy - pointXtoCenter);
                            ox1 = (stats.dx + pointYtoCenter);
                            stats.dx = ox1;
                            stats.dy = oy1;
                            if (hscale > 0 && wscale > 0) {
                                yscale = stats.dscale * canvasoheight / sHi;
                                xscale = stats.dscale * canvasowidth / sWide;
                            }
                            newscale = Math.min(yscale, xscale);
                            factor = newscale / stats.dscale;
                            tempstats = {
                                dscale: stats.dscale,
                                dx: stats.dx,
                                dy: stats.dy,
                                startx: stats.dx,
                                starty: stats.dy,
                                endx: (stats.width * stats.dscale) + stats.dx,
                                endy: (stats.height * stats.dscale) + stats.dy
                            };
                            setPagestats(tempstats, false);
                            thispage.ZoomIn(factor, false, false);
                            break;
                        case 180:
                            //move point to center
                            pointXtoCenter = rectCenterX - canvdiv2W;
                            pointYtoCenter = rectCenterY - canvdiv2H;
                            oy1 = (stats.dy + pointYtoCenter);
                            ox1 = (stats.dx + pointXtoCenter);
                            stats.dx = ox1;
                            stats.dy = oy1;
                            if (hscale > 0 && wscale > 0) {
                                yscale = stats.dscale * canvasoheight / sHi;
                                xscale = stats.dscale * canvasowidth / sWide;
                            }
                            newscale = Math.min(yscale, xscale);
                            factor = newscale / stats.dscale;
                            tempstats = {
                                dscale: stats.dscale,
                                dx: stats.dx,
                                dy: stats.dy,
                                startx: stats.dx,
                                starty: stats.dy,
                                endx: (stats.width * stats.dscale) + stats.dx,
                                endy: (stats.height * stats.dscale) + stats.dy
                            };
                            setPagestats(tempstats, false);
                            thispage.ZoomIn(factor, false, false);
                            break;
                        case 0:
                            //offset in current scale
                            ox1 = -((rectCenterX - stats.dx) / stats.dscale);
                            oy1 = -((rectCenterY - stats.dy) / stats.dscale);
                            if (hscale > 0 && wscale > 0) {
                                yscale = stats.dscale * canvasoheight / sHi;
                                xscale = stats.dscale * canvasowidth / sWide;
                            }
                            stats.dscale = Math.min(yscale, xscale);
                            stats.dx = (ox1 * stats.dscale) + (canvasowidth / 2);
                            stats.dy = (oy1 * stats.dscale) + (canvasoheight / 2);
                            break;
                    }
                    var startx = stats.dx;
                    var starty = stats.dy;
                    var endx = (stats.width * stats.dscale) + startx;
                    var endy = (stats.height * stats.dscale) + starty;
                    return {
                        dscale: stats.dscale,
                        dx: stats.dx,
                        dy: stats.dy,
                        startx: startx,
                        starty: starty,
                        endx: endx,
                        endy: endy
                    };
                }
                function ScaleZoomHeight(stats) {
                    var yscale = 0.0;
                    switch (thispage.getpageRotation()) {
                        case 0:
                            yscale = canvasoheight / stats.height;
                            stats.dscale = yscale;
                            //xscale = canvasowidth / stats.width;
                            stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                            stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                            break;
                        case 90:
                            yscale = canvasoheight / stats.width;
                            stats.dscale = yscale;
                            stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                            stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                            break;
                        case 180:
                            yscale = canvasoheight / stats.height;
                            stats.dscale = yscale;
                            stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                            stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                            break;
                        case 270:
                            yscale = canvasoheight / stats.width;
                            stats.dscale = yscale;
                            stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                            stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                            break;
                    }
                    var startx = stats.dx;
                    var starty = stats.dy;
                    var endx = (stats.width * stats.dscale) + startx;
                    var endy = (stats.height * stats.dscale) + starty;
                    return {
                        dscale: stats.dscale,
                        dx: stats.dx,
                        dy: stats.dy,
                        startx: startx,
                        starty: starty,
                        endx: endx,
                        endy: endy
                    };
                }
                function ScaleZoomAll(stats) {
                    var yscale = stats.dscale;
                    var xscale = stats.dscale;
                    switch (thispage.getpageRotation()) {
                        case 0:
                            yscale = canvasoheight / stats.height;
                            xscale = canvasowidth / stats.width;
                            break;
                        case 90:
                            yscale = canvasoheight / stats.width;
                            xscale = canvasowidth / stats.height;
                            break;
                        case 180:
                            yscale = canvasoheight / stats.height;
                            xscale = canvasowidth / stats.width;
                            break;
                        case 270:
                            yscale = canvasoheight / stats.width;
                            xscale = canvasowidth / stats.height;
                            break;
                    }
                    stats.dscale = Math.min(xscale, yscale);
                    stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                    stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                    var startx = stats.dx;
                    var starty = stats.dy;
                    var endx = (stats.width * stats.dscale) + startx;
                    var endy = (stats.height * stats.dscale) + starty;
                    return {
                        dscale: stats.dscale,
                        dx: stats.dx,
                        dy: stats.dy,
                        startx: startx,
                        starty: starty,
                        endx: endx,
                        endy: endy
                    };
                }
                function ScaleZoomWidth(stats) {
                    var xscale = 0.0;
                    switch (thispage.getpageRotation()) {
                        case 0:
                            //xscale = canvasowidth / this.MainImageWidth;
                            xscale = canvasowidth / stats.width;
                            stats.dscale = xscale;
                            stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                            stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                            break;
                        case 90:
                            xscale = canvasowidth / stats.height;
                            stats.dscale = xscale;
                            stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                            stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                            break;
                        case 180:
                            xscale = canvasowidth / stats.width;
                            stats.dscale = xscale;
                            stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                            stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                            break;
                        case 270:
                            xscale = canvasowidth / stats.height;
                            stats.dscale = xscale;
                            stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                            stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                            break;
                        default:
                            xscale = canvasowidth / stats.width;
                            stats.dscale = xscale;
                            stats.dx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                            stats.dy = (canvasoheight - (stats.height * stats.dscale)) / 2;
                            break;
                    }
                    var startx = stats.dx;
                    var starty = stats.dy;
                    var endx = (stats.width * stats.dscale) + startx;
                    var endy = (stats.height * stats.dscale) + starty;
                    return {
                        dscale: stats.dscale,
                        dx: stats.dx,
                        dy: stats.dy,
                        startx: startx,
                        starty: starty,
                        endx: endx,
                        endy: endy
                    };
                }
                function ScaleZoom(center, factor, stats, bIn) {
                    //var dscale = stats.dscale;
                    //var dx = stats.dx;
                    //var dy = stats.dy;
                    /*var imagestats = {
                        dscale : this.dscale,
                        dx : this.dx,
                        dy : this.dy,
                        width : this.MainImageWidth,
                        height : this.MainImageHeight
                    }; */
                    var prevcenterx = (canvasowidth - (stats.width * stats.dscale)) / 2;
                    var prevcentery = (canvasoheight - (stats.height * stats.dscale)) / 2;
                    var diffx = prevcenterx - stats.dx;
                    var diffy = prevcentery - stats.dy;
                    if (bIn) {
                        stats.dscale = stats.dscale * factor;
                    }
                    else {
                        stats.dscale = stats.dscale / factor;
                    }
                    var centerx = ((canvasowidth - (stats.width * stats.dscale)) / 2);
                    var centery = ((canvasoheight - (stats.height * stats.dscale)) / 2);
                    if (center) {
                        stats.dx = centerx;
                        stats.dy = centery;
                    }
                    else {
                        if (bIn) {
                            stats.dx = centerx - (diffx * factor);
                            stats.dy = centery - (diffy * factor);
                        }
                        else {
                            stats.dx = centerx - (diffx / factor);
                            stats.dy = centery - (diffy / factor);
                        }
                    }
                    var startx = stats.dx;
                    var starty = stats.dy;
                    var endx = (stats.width * stats.dscale) + startx;
                    var endy = (stats.height * stats.dscale) + starty;
                    thispage.setpagedimsize(startx, starty, endx, endy, true);
                    return {
                        dscale: stats.dscale,
                        dx: stats.dx,
                        dy: stats.dy,
                        startx: startx,
                        starty: starty,
                        endx: endx,
                        endy: endy
                    };
                }

