                this.SelectText = function(bstart, bend, startpos, mousepos){

                    thispage.textselectobj.bstart = bstart;
                    thispage.textselectobj.bend = bend;
                    //thispage.textselectobj.bend = complete;


                    if(bstart){
                        thispage.textselectobj.rectarray = undefined;
                        thispage.textselectobj.start = -1;
                        thispage.textselectobj.end = -1;
                        thispage.textselectobj.$handler = null;
                    }

                    //this.selectText = function(npagenum, bstart, startpoint, movepoint){

                    if (mousepos) {
                        var rotatedpoint = { x: mousepos.x, y: mousepos.y };
                        var rotatedspoint = { x: startpos.x, y: startpos.y };

                        rotatedpoint = { x: mousepos.xus, y: mousepos.yus };
                        rotatedspoint = { x: startpos.xus, y: startpos.yus };


                        if (thispage.getpageRotation() != 0) {
                            rotatedpoint = mouse_rotated(mousepos.x, mousepos.y);
                            rotatedspoint = mouse_rotated(startpos.x, startpos.y);

                            rotatedpoint = mouse_rotated(mousepos.xus, mousepos.yus);
                            rotatedspoint = mouse_rotated(startpos.xus, startpos.yus);

                        }


                        //var pdfpoint = thispage.getPDFcoords(rotatedpoint.x, rotatedpoint.y);
                        var pdfpoint = thispage.getPDFCoordsRot(rotatedpoint);


                        //var pdfspoint = thispage.getPDFcoords(rotatedspoint.x, rotatedspoint.y);
                        var pdfspoint = thispage.getPDFCoordsRot(rotatedspoint);



                        thispage.textselectobj.startpos = [pdfspoint.x, pdfspoint.y];
                        thispage.textselectobj.endpos = [pdfpoint.x, pdfpoint.y];


                        if (thispage.DocRef.foxitdoc != null) {

                            thispage.DocRef.foxitdoc.selectText(thispage.pagenumber, thispage.textselectobj, thispage.textselectreturn);
                        }

                    }

                };

                function getPDFOrigo(){

                    var origox = 0;
                    var origoy = 0;

                    if(thispage.dxpdf > 0){
                        origox = 8;
                    }
                    if(thispage.dypdf > 0){
                        origoy = 8;
                    }

                    var origo = {x: origox, y: origoy};


                    switch(thispage.getpageRotation()){
                        case 0 :
                            origo = {x: origox, y: origoy};
                            break;
                        case 90 :
                            origo = {x: canvasowidthsize, y : origoy};
                            //origo = {x: origox, y: canvasoheightsize};
                            break;
                        case 180 :
                            origo = {x: canvasowidthsize, y: canvasoheightsize};
                        break;
                        case 270 :
                            origo = {x: origox, y: canvasoheightsize};
                            //origo = {x: canvasowidthsize, y : origoy};

                        break;


                    }
                    return origo;

                }




