                                    diffxpdf = prevcenterxpdf - this.dxpdf;
                                    diffypdf = prevcenterypdf - this.dypdf;
                                    //this.dscalepdf = newscalepdf;
                                    centerxpdf = ((canvasowidth - (pcanvwidth * this.dscalepdf)) / 2);
                                    centerypdf = ((canvasoheight - (pcanvheight * this.dscalepdf)) / 2);

                                    centerxpdf = ((canvasowidthsize - (pcanvwidth * this.dscalepdf)) / 2);
                                    centerypdf = ((canvasoheightsize - (pcanvheight * this.dscalepdf)) / 2);



                                    var rotcenter = mouse_rotated(rectCenterX,rectCenterY);

                                    //zoomtopoint = thispage.getPDFcoords(rotcenter.x,rotcenter.y);
                                    zoomtopoint = thispage.getPDFCoordsRot(rectCenternorot);

                                    thispage.setpdfscaleNoOffset(newscalepdf);

