                                var tempdxpdf = (rectCenterX - this.dxpdf) + (canvasowidth / 2);
                                var tempdypdf = (rectCenterY - this.dypdf) + (canvasoheight / 2);

                                tempdxpdf = (rectCenterX - this.dxpdf) + (canvasowidthsize / 2);
                                tempdypdf = (rectCenterY - this.dypdf) + (canvasoheightsize / 2);



