                this.MarkupFindText = function(SearchExpr){

                    var searchmarkuplist = [];

                    for(var mi = 0; mi < thispage.DocRef.markuplist.length; mi++){
                        if (thispage.DocRef.markuplist[mi].FindText(SearchExpr)) {
                            searchmarkuplist.push(thispage.DocRef.markuplist[mi]);
                        }
                    }

                    return searchmarkuplist;
                };

                this.getMarkupPos = function(markup){

                    var hscaled = markup.hscaled;
                    var wscaled = markup.wscaled;
                    var xscaled = markup.xscaled;
                    var yscaled = markup.yscaled;

                    if(markup.bisTextArrow && markup.textBoxConnected != null){

                        hscaled = Math.max(markup.hscaled, markup.textBoxConnected.hscaled);
                        wscaled = Math.max(markup.wscaled, markup.textBoxConnected.wscaled);
                        xscaled = Math.min(markup.xscaled, markup.textBoxConnected.xscaled);
                        yscaled = Math.min(markup.yscaled, markup.textBoxConnected.yscaled);


                    }


                    var npage = markup.pagenumber;

                    switch (this.getpageRotation()) {
                        case 0:
                            switch (markup.type) {
                                case 0:
                                    wscaled = wscaled - xscaled;
                                    hscaled = hscaled - yscaled;
                                    break;
                                case 1:
                                    wscaled = wscaled - xscaled;
                                    hscaled = hscaled - yscaled;
                                    break;
                                case 2:
                                    wscaled = wscaled - xscaled;
                                    hscaled = hscaled - yscaled;
                                    break;
                                case 6:
                                    wscaled = wscaled - xscaled;
                                    hscaled = hscaled - yscaled;
                                    break;
                                case 7:
                                    wscaled = wscaled - xscaled;
                                    hscaled = hscaled - yscaled;
                                    break;
                                case 8:
                                    wscaled = wscaled - xscaled;
                                    hscaled = hscaled - yscaled;
                                    break;
                                case 9:
                                    //yscaled = yscaled - hscaled;
                                    break;

                                case 13:
                                    wscaled = wscaled - xscaled;
                                    hscaled = hscaled - yscaled;
                                    break;

                                default:
                                    break;
                            }
                            break;
                        case 90:
                            //all values are absolute for all markup types.
                            hscaled = markup.rotatedrect.h;
                            wscaled = markup.rotatedrect.w;
                            xscaled = markup.rotatedrect.x;
                            yscaled = markup.rotatedrect.y;
                            //switch rect values to comply with orientation
                            //switch x and w
                            var wxtemp = xscaled;
                            xscaled = wscaled;
                            wscaled = wxtemp;
                            //change absolute rect values to relative
                            wscaled = wscaled - xscaled;
                            hscaled = hscaled - yscaled;
                            break;
                        case 180:
                            //all values are absolute for all markup types.
                            hscaled = markup.rotatedrect.h;
                            wscaled = markup.rotatedrect.w;
                            xscaled = markup.rotatedrect.x;
                            yscaled = markup.rotatedrect.y;
                            //switch rect values to comply with orientation
                            //both x,w and y,h is switched
                            var xtemp = xscaled;
                            var ytemp = yscaled;
                            xscaled = wscaled;
                            yscaled = hscaled;
                            wscaled = xtemp;
                            hscaled = ytemp;
                            //change absolute rect values to relative
                            wscaled = wscaled - xscaled;
                            hscaled = hscaled - yscaled;
                            break;
                        case 270:
                            //all values are absolute for all markup types.
                            hscaled = markup.rotatedrect.h;
                            wscaled = markup.rotatedrect.w;
                            xscaled = markup.rotatedrect.x;
                            yscaled = markup.rotatedrect.y;
                            //switch rect values to comply with orientation
                            var wytemp = yscaled;
                            yscaled = hscaled;
                            hscaled = wytemp;
                            //yscaled -= wscaled;
                            //var hwtemp = wscaled;
                            //wscaled = hscaled;
                            //hscaled = hwtemp;
                            //change absolute rect values to relative
                            wscaled = wscaled - xscaled;
                            hscaled = hscaled - yscaled;
                            break;
                    }

                    return {x : xscaled, y : yscaled, w : wscaled, h : hscaled};

                };

                this.panToMarkup = function(markup){

                        //var divpos = thispage.getdivpos(counter);

                        if (markup.selected || markup.selectedit) {
                            markup.drawmescaled(context);
                        }else{
                            markup.drawmescaled(cntximg);
                        }



                        var mpos = thispage.getMarkupPos(markup);

                        thispage.pan_update(0, 0);
                        //console.log(divpos);
                        //var visible = this.istextvisible(divpos.x, divpos.y);
                        /*
                        0 = right
                        1 = left
                        2 = up
                        3 = down
                       */
                        var centery = canvasoheight / 2;
                        var centerx = canvasowidth / 2;
                        var panx = 0;
                        var pany = 0;
                        var pagerect = thispage.getpagerect();

                        var mcenterx = (mpos.x + (mpos.w * 0.5));
                        var mcentery = (mpos.y + (mpos.h * 0.5));



                        if (thispage.getpageRotation() != 0) {
                            var rotpos = thispage.getrotcoords(centerx, centery, mcenterx, mcentery, -thispage.getpageRotation());
                            //divpos.x = rotpos.x;
                            //divpos.y = rotpos.y;
                            distancexright = Math.max(rotpos.x, canvasowidth) - Math.min(rotpos.x, canvasowidth);
                            if (Math.max(rotpos.x, canvasowidth) == rotpos.x) {
                                move = 1;
                                //panx =  distancexright + 300;
                                panx = rotpos.x - centerx;
                            }
                            else if (distancexright < 300) {
                                move = 1;
                                panx = rotpos.x - centerx;
                            }
                            distanceybottom = Math.max(rotpos.y, canvasoheight) - Math.min(rotpos.y, canvasoheight);
                            if (Math.max(rotpos.y, canvasoheight) == rotpos.y) {
                                move = 2;
                                pany = rotpos.y - centery;
                            }
                            else if (distanceybottom < 100) {
                                move = 2;
                                pany = rotpos.y - centery;
                            }
                            distancexleft = Math.max(rotpos.x, 0) - Math.min(rotpos.x, 0);
                            if (Math.min(rotpos.x, 0) == rotpos.x) {
                                move = 0;
                                panx = -(centerx - rotpos.x);
                            }
                            else if (distancexleft < 100) {
                                move = 0;
                                panx = -(centerx - rotpos.x);
                            }
                            distanceytop = Math.max(rotpos.y, 0) - Math.min(rotpos.y, 0);
                            if (Math.min(rotpos.y, 0) == rotpos.y) {
                                move = 3;
                                pany = -(centery - rotpos.y);
                            }
                            else if (distanceytop < 100) {
                                move = 3;
                                pany = -(centery - rotpos.y);
                            }
                            /*switch (thispage.getpageRotation()) {
                                case 90:
                                    //this.dxvector -= sy;
                                    //this.dyvector += sx;
                                    thispage.pan_update(pany,-panx);

                                    break;
                                case 180:
                                    //this.dxvector += sx;
                                    //this.dyvector += sy;
                                    thispage.pan_update(-panx,-pany);
                                    break;
                                case 270:
                                    //this.dxvector += sy;
                                    //this.dyvector -= sx;
                                    thispage.pan_update(-pany,panx);
                                    break;
                            }*/
                            thispage.pan_update(panx, pany);
                        }
                        else {
                            var distancexright = Math.max(mcenterx, canvasowidth) - Math.min(mcenterx, canvasowidth);
                            if (Math.max(mcenterx, canvasowidth) == mcenterx) {
                                move = 1;
                                //panx =  distancexright + 300;
                                panx = mcenterx - centerx;
                            }
                            else if (distancexright < 300) {
                                move = 1;
                                panx = mcenterx - centerx;
                            }
                            var distanceybottom = Math.max(mcentery, canvasoheight) - Math.min(mcentery, canvasoheight);
                            if (Math.max(mcentery, canvasoheight) == mcentery) {
                                move = 2;
                                pany = mcentery - centery;
                            }
                            else if (distanceybottom < 100) {
                                move = 2;
                                pany = mcentery - centery;
                            }
                            var distancexleft = Math.max(mcenterx, 0) - Math.min(mcenterx, 0);
                            if (Math.min(mcenterx, 0) == mcenterx) {
                                var move = 0;
                                panx = -(centerx - mcenterx);
                                //var panx = distancexleft - 200;
                            }
                            else if (distancexleft < 100) {
                                move = 0;
                                panx = -(centerx - mcenterx);
                            }
                            var distanceytop = Math.max(mcentery, 0) - Math.min(mcentery, 0);
                            if (Math.min(mcentery, 0) == mcentery) {
                                move = 3;
                                pany = -(centery - mcentery);
                            }
                            else if (distanceytop < 100) {
                                move = 3;
                                pany = -(centery - mcentery);
                            }
                            if (pagerect.w <= canvasowidth && thispage.usepdfjs) {
                                //thispage.pan_update(0,pany);
                                panx = 0;
                            }
                            /*if (thispage.pagenumber == 0 && thispage.usepdfjs) {
                                if (pany < 0) {
                                    pany = 0;
                                }
                            }*/
                            thispage.pan_update(panx, pany);
                        }

                };

