                this.removevisibleTile = function (r, c) {
                    for (var i = 0; i < thispage.visibleTiles.length; i++) {
                        if (thispage.visibleTiles[i].r == r && thispage.visibleTiles[i].c == c) {
                            //remove from array
                            thispage.visibleTiles.splice(i, 1);
                        }
                    }
                };
                this.addvisibleTile = function (r, c) {
                    thispage.visibleTiles = [];
                    thispage.visibleTiles.push({ row: r, column: c });
                };
                this.draw_tiled_cavas = function (ctx, dx, dy, dscalepdf) {
                    if (thispage.canvtileArray.length == 0) {
                        return;
                    }
                    if (thispage.canvtileArray[0][0] == undefined || thispage.canvtileArray[0][0].cnv == undefined) {
                        return;
                    }
                    var offscreenwidth = thispage.canvtileArray[0][0].cnv.width;
                    var offscreenheight = thispage.canvtileArray[0][0].cnv.height;
                    var ulx = dx;
                    var uly = dy;
                    var xoffset = 0;
                    var yoffset = 0;
                    thispage.tilevisibiltychanged = false;
                    for (var i = 0; i < thispage.canvtileArray.length; i++) {
                        for (var j = 0; j < thispage.canvtileArray[i].length; j++) {
                            offscreenwidth = thispage.canvtileArray[i][j].cnv.width;
                            offscreenheight = thispage.canvtileArray[i][j].cnv.height;
                            xoffset = thispage.canvtileArray[i][j].xoffset;
                            yoffset = thispage.canvtileArray[i][j].yoffset;
                            var nowidth = (thispage.canvtileArray[i][j].cnv.width != 0);
                            var noheight = (thispage.canvtileArray[i][j].cnv.height != 0);


                            if ((ulx < canvasowidth && uly < canvasoheight) && ((ulx + (offscreenwidth * dscalepdf)) > 0 && (uly + (offscreenheight * dscalepdf)) > 0)) {

                                if(nowidth && noheight){
                                    ctx.drawImage(thispage.canvtileArray[i][j].cnv, ulx, uly, offscreenwidth * dscalepdf, offscreenheight * dscalepdf);
                                }

                                if (!thispage.canvtileArray[i][j].visible) {
                                    //console.log('visibility changed to true', i, j);
                                    thispage.tilevisibiltychanged = true;
                                    //addvisibleTile(i, j);
                                }
                                else {
                                    //thispage.tilevisibiltychanged = false;
                                }
                                thispage.canvtileArray[i][j].visible = true;
                                //thispage.addvisibleTile(i,j);
                                if (thispage.tilespending) {
                                    thispage.tilespending = false;
                                }
                                if (thispage.prioritytilespending) {
                                    thispage.prioritytilespending = false;
                                }
                            }
                            else {
                                if (thispage.canvtileArray[i][j].visible) {
                                    //console.log('visibility changed to false', i, j);
                                    thispage.tilevisibiltychanged = true;
                                }
                                else {
                                    //thispage.tilevisibiltychanged = false;
                                }
                                thispage.canvtileArray[i][j].visible = false;
                            }
                            /*if (i = 0 && j == 0){

                            }else{
                                contexto.drawImage(thispage.canvtileArray[i][j].cnv, ulx, uly, offscreenwidth * this.dscalepdf, offscreenheight * this.dscalepdf);
                            }*/
                            //ulx += (offscreenwidth * dscalepdf) - 1;
                            /*if (j < thispage.canvtileArray[i].length - 1){
                                ulx += (xoffset * dscalepdf);
                            }*/
                            ulx += (xoffset * dscalepdf);
                        }
                        //uly += (offscreenheight * dscalepdf) - 1;
                        uly += (yoffset * dscalepdf);
                        ulx = dx;
                    }
                };
                this.draw_foxit_annots = function (ctx, dx, dy, dscalepdf) {
                    //var offscreenwidth = thispage.annotArray[0].cnv.width;
                    //var offscreenheight = thispage.annotArray[0].cnv.height;
                    var ulx = dx;
                    var uly = dy;
                    for (var i = 0; i < thispage.annotArray.length; i++) {
                        var offscreenwidth = thispage.annotArray[i].cnv.width;
                        var offscreenheight = thispage.annotArray[i].cnv.height;
                        var offsetx = thispage.annotArray[i].pos.left * dscalepdf;
                        var offsety = thispage.annotArray[i].pos.top * dscalepdf;
                        //var offsetx = thispage.annotArray[i].pos.left + ulx;
                        //var offsety = thispage.annotArray[i].pos.top + uly;
                        offsetx += ulx;
                        offsety += uly;
                        ctx.drawImage(thispage.annotArray[i].cnv, offsetx, offsety, thispage.annotArray[i].pos.width * dscalepdf * thispage.annotArray[i].pos.scale, thispage.annotArray[i].pos.height * dscalepdf * thispage.annotArray[i].pos.scale);
                    }
                };

