                this.drawsearchRect = function () {

                    var pxscale = getPixelRatio();

                    if (thispage.DocRef.foxitsearchobj.page == thispage.pagenumber && thispage.DocRef.foxitsearchobj.active) {
                        //contexto.save();
                        cntximg.save();
                        var curmatch = thispage.DocRef.foxitsearchobj.getcurmatch();
                        if(!curmatch) return;

                        var x = ((curmatch.rectArray[0].left * (thispage.curpagescale * thispage.dscalepdf)) + thispage.dxpdf);
                        var y = (((thispage.pdfpageheight - curmatch.rectArray[0].top) * (thispage.curpagescale * thispage.dscalepdf)) + thispage.dypdf);
                        var right = ((curmatch.rectArray[0].right * (thispage.curpagescale * thispage.dscalepdf)) + thispage.dxpdf);
                        var bottom = (((thispage.pdfpageheight - curmatch.rectArray[0].bottom) * (thispage.curpagescale * thispage.dscalepdf)) + thispage.dypdf);
                        var width = right - x;
                        var height = bottom - y;

                        x = x * pxscale;
                        y = y * pxscale;

                        width = width * pxscale;
                        height = height * pxscale;

                        cntximg.clearRect(x, y, width, height);
                        //contexto.fillStyle = "rgba(238, 238, 0, 0.3)";
                        cntximg.fillStyle = "rgba(238, 238, 0, 0.3)";
                        //contexto.fillRect(x, y, width, height);

                        cntximg.fillRect(x, y, width, height);
                        //contexto.restore();
                        //console.log(x, y, width, height);

                        cntximg.restore();
                    }
                };
