                this.foxitSearchText = function (text, forward, casesens) {
                    if (text == thisdocument.foxitsearchobj.expr && thisdocument.foxitsearchobj.active) {
                        if (forward) {
                            thisdocument.pages[thisdocument.currentpage].foxitClearSearch();
                            thisdocument.foxitsearchobj.next();
                            if (thisdocument.foxitsearchobj.page != thisdocument.currentpage) {
                                thisdocument.GotoPage(thisdocument.foxitsearchobj.page);
                                thisdocument.pageSearchArr.push(thisdocument.foxitsearchobj.page);
                            }
                            else {
                                //thisdocument.pages[thisdocument.currentpage].clearSearch();
                                thisdocument.pages[thisdocument.currentpage].showFoxitSearch();
                                //thisdocument.pages[thisdocument.currentpage].showFoxitSearchOnUpdate();

                            }
                        }
                        if (!forward) {
                            thisdocument.pages[thisdocument.currentpage].foxitClearSearch();
                            thisdocument.foxitsearchobj.previous();
                            if (thisdocument.foxitsearchobj.page != thisdocument.currentpage) {
                                thisdocument.GotoPage(thisdocument.foxitsearchobj.page);
                                thisdocument.pageSearchArr.push(thisdocument.foxitsearchobj.page);
                            }
                            else {
                                thisdocument.pages[thisdocument.currentpage].showFoxitSearch();
                                //thisdocument.pages[thisdocument.currentpage].showFoxitSearchOnUpdate();
                            }
                        }
                    }
                    else {
                        if (thisdocument.foxitsearchobj.active) {
                            thisdocument.pages[thisdocument.currentpage].foxitClearSearch();
                        }
                        thisdocument.foxitsearchobj.matcharray = [];
                        thisdocument.foxitsearchobj.forward = forward;
                        thisdocument.foxitsearchobj.expr = text;
                        thisdocument.foxitsearchobj.casesens = casesens;
                        thisdocument.foxitsearchobj.active = false;
                        thisdocument.foxitsearchobj.outerindx = 0;
                        thisdocument.foxitsearchobj.innerindx = 0;
                        thisdocument.foxitsearchobj.page = 0;
                        if (thisdocument.foxitdoc != null) {
                            var pgindex = 0;
                            //thisdocument.foxitdoc.getTextSearch(text, pgindex, thisdocument.getsearchresult);
                            thisdocument.foxitdoc.getTextSearch(text, pgindex, thisdocument.getsearchresult, thisdocument.foxitsearchobj.casesens);
                        }
                    }
                    //thisdocument.foxitSearcMatches = [];
                };


