                this.clearDocumentTextSearch = function () {
                    if (thisdocument.foxitdoc != null) {
                        thisdocument.searchMatches = {};
                        thisdocument.foxitsearchobj.clonearray = [];
                        thisdocument.foxitsearchobj.forward = true;
                        thisdocument.foxitsearchobj.expr = "";
                        thisdocument.foxitsearchobj.casesens = false;
                        thisdocument.foxitsearchobj.active = false;
                        thisdocument.foxitsearchobj.outerindx = 0;
                        thisdocument.foxitsearchobj.innerindx = 0;
                        thisdocument.foxitsearchobj.page = 0;
                        thisdocument.foxitsearchobj.wholeword = "";
                        thisdocument.foxitsearchobj.wholedocument = false;
                    }
                };

                this.getSearchWholeDocument = function (searchres, text, pgindex) {
                    let list = searchres.list;
                    const isCaseSensitive = thisdocument.foxitsearchobj.casesens;
                    const isWholeText = thisdocument.foxitsearchobj.wholeword;

                    thisdocument.searchMatches[pgindex] = { text, pgindex, list: [] };

                    list.forEach((item) => {
                        const pageIndex = item.match.pageIndex;

                        if (!thisdocument.searchMatches[pageIndex]) {
                            thisdocument.searchMatches[pageIndex] = {text, pgindex: pageIndex, list: []};
                        }
                        thisdocument.searchMatches[pageIndex].list.push(item);
                    });

                    if (pgindex < thisdocument.pages.length - 1) {
                        thisdocument.foxitdoc.getTextSearch( text, pgindex + 1, thisdocument.getSearchWholeDocument, isCaseSensitive, isWholeText );
                    } else {
                        const result = Object.values(thisdocument.searchMatches);
                        RxCore_GUI_DocumentSearch.matchesFound(result);
                        thisdocument.foxitsearchobj.active = true;
                        thisdocument.foxitsearchobj.wholedocument = true;
                        thisdocument.foxitsearchobj.matcharray = result;
                        thisdocument.foxitsearchobj.clonearray = result.map((item) => item.list);
                    }
                };

                this.documentTextSearch = function (text, casesens, wholeword) {
                    if (thisdocument.foxitdoc != null) {
                        if (thisdocument.foxitsearchobj.active) {
                            thisdocument.pages[thisdocument.currentpage].foxitClearSearch();
                        }

                        thisdocument.searchMatches = {};
                        thisdocument.foxitsearchobj.forward = true;
                        thisdocument.foxitsearchobj.expr = text;
                        thisdocument.foxitsearchobj.casesens = casesens;
                        thisdocument.foxitsearchobj.active = false;
                        thisdocument.foxitsearchobj.outerindx = 0;
                        thisdocument.foxitsearchobj.innerindx = 0;
                        thisdocument.foxitsearchobj.page = 0;
                        thisdocument.foxitsearchobj.wholeword = wholeword;
                        thisdocument.foxitsearchobj.wholedocument = true;
                        if (thisdocument.foxitdoc != null) {
                            var pgindex = 0;
                            thisdocument.foxitdoc.getTextSearch(text, pgindex, thisdocument.getSearchWholeDocument, casesens, wholeword);
                        }
                    }
                };

                this.markupTextWithOrange = function (item) {
                    if (thisdocument.foxitdoc != null) {
                        thisdocument.foxitsearchobj.orangeItem = item;
                        const page = thisdocument.pages[thisdocument.currentpage];
                        var x = item.match.rectArray[0].left * (page.curpagescale * page.dscalepdf) + page.dxpdf;
                        var y = (page.pdfpageheight - item.match.rectArray[0].top) * (page.curpagescale * page.dscalepdf) + page.dypdf;
                        var panto = page.getsearchpanupdate(x, y);
                        page.pan_update(panto.x, panto.y);
                    }
                };

                this.movePageTo = function (pageRange, destIndex) {
                    if (thisdocument.foxitdoc != null) {
                        thisdocument.foxitdoc.movePageTo(pageRange, destIndex).then((pages) => {

                            const array = this.findChangedIndices(pageRange, destIndex);
                            const pagexmlobj = xmlDoc.getElementsByTagName("Page");

                            array.forEach((id) => {
                                if (id < thisdocument.thumbnails.length) {
                                    const thumbnail = new ThumbnailObject( pagexmlobj[0], "Default", thisdocument, id );
                                    thisdocument.thumbnails[id] = thumbnail;
                                    thisdocument.foxitdoc.getThumbnail(id);
                                }
                            });

                            RxCore_GUI_pagethumbs.setThumbnails(thisdocument.thumbnails);

                            if (thisdocument.foxitsearchobj.clonearray != []) {
                                thisdocument.foxitsearchobj.clonearray = [];
                                this.documentTextSearch( thisdocument.foxitsearchobj.expr, thisdocument.foxitsearchobj.casesens, thisdocument.foxitsearchobj.wholeword);
                            }
                        });
                    }
                };

                this.removePage = function (pageRange) {
                    if (thisdocument.foxitdoc != null) {

                        thisdocument.foxitdoc.removePage(pageRange).then(() => {

                            const count = this.countItemsInRanges(pageRange);

                            thisdocument.pages.splice(thisdocument.pages.length - count, count );
                            thisdocument.thumbnails = this.removeItemsByIndices( thisdocument.thumbnails, pageRange );

                            RxCore_GUI_pagethumbs.setThumbnails(thisdocument.thumbnails);

                            RxCore_GUI_PageCountChanged.countChanged( thisdocument.pages.length );

                            if (thisdocument.foxitsearchobj.clonearray != []) {
                                thisdocument.foxitsearchobj.matcharray = this.removeItemsByIndices( thisdocument.foxitsearchobj.matcharray, pageRange );
                                this.refreshSearchResult();
                            }
                        });
                    }
                };

                this.extractPage = function (pageRange, remove) {
                    if (thisdocument.foxitdoc != null) {
                        thisdocument.foxitdoc.extractPage(pageRange).then(() => {
                            if (remove) {
                                this.removePage(pageRange);
                            }
                        });
                    }
                };

                this.refreshPages = function () {
                    if (thisdocument.foxitdoc != null) {
                        thisdocument.pages = thisdocument.pages.map((page, id) => {
                            if (page != undefined) {
                                return { ...page, PageName: `Page ${id + 1}`, firstpage: id === 0, pagenumber: id, printobj: { ...page.printobj, pagenumber: id} };
                            } else {
                                return undefined;
                            }
                        });
                    }
                };

                this.refreshSearchResult = function () {
                    thisdocument.foxitsearchobj.matcharray = thisdocument.foxitsearchobj.matcharray.map((item, id) => {
                        let list = [];
                        if (item && item.list) {
                            list = item.list.map((item) => ({ match: { ...item.match, pageIndex: id}}));
                        }
                        return {
                            text: thisdocument.foxitsearchobj.expr,
                            pgindex: id,
                            list
                        };
                    });
                    thisdocument.foxitsearchobj.clonearray = thisdocument.foxitsearchobj.matcharray.map((item) => item.list);
                    RxCore_GUI_DocumentSearch.matchesFound( thisdocument.foxitsearchobj.matcharray );

                };

                this.insertBlankPages = function (pageRange, count, width, height) {
                    if (thisdocument.foxitdoc != null) {
                        thisdocument.foxitdoc.insertBlankPages(pageRange, count, width, height).then(() => {
                            var pagexmlobj = xmlDoc.getElementsByTagName("Page");
                            const flattenRanges = this.flattenRanges(pageRange);
                            const rangeCount = this.countItemsInRanges(pageRange);
                            new Array(rangeCount).fill(0).forEach((item, id) => {

                                new Array(count).fill(0).forEach(() => {
                                    console.log(flattenRanges[id]);
                                    const PageObj = new PageObject( pagexmlobj[0], "Default", false, "", flattenRanges[id], thisdocument );
                                    DocObj.addpage(PageObj, false);
                                });
                            });

                            this.refreshThumbnails();

                            this.refreshPages();

                            thisdocument.pages.forEach((item, id) => {
                                thisdocument.foxitdoc.getThumbnail(id);
                            });
                            if (thisdocument.foxitsearchobj.clonearray != []) {
                                thisdocument.foxitsearchobj.clonearray = [];
                                this.documentTextSearch( thisdocument.foxitsearchobj.expr, thisdocument.foxitsearchobj.casesens, thisdocument.foxitsearchobj.wholeword );
                            }
                        });
                    }
                };

                this.importPages = function ( file, pageRange, pageArray, isReplace, count, width, height ) {
                    if (thisdocument.foxitdoc != null) {

                        return thisdocument.foxitdoc.importPages( file, pageRange, pageArray, isReplace, count, width, height ).then(() => {

                            var pagexmlobj = xmlDoc.getElementsByTagName("Page");

                            if (isReplace) {
                                const deleteCount = this.countItemsInRanges(pageRange);
                                thisdocument.pages.splice( thisdocument.pages.length - deleteCount, deleteCount );
                            }

                            new Array(count).fill(0).forEach((item, id) => {
                                const PageObj = new PageObject( pagexmlobj[0], "Default", false, "", pageRange[0][0] + id, thisdocument );
                                DocObj.addpage(PageObj, false);
                            });

                            this.refreshThumbnails();
                            this.refreshPages();
                            thisdocument.pages.forEach((item, id) => {
                                thisdocument.foxitdoc.getThumbnail(id);
                            });

                            if (thisdocument.foxitsearchobj.clonearray != []) {
                                thisdocument.foxitsearchobj.clonearray = [];
                                this.documentTextSearch(thisdocument.foxitsearchobj.expr, thisdocument.foxitsearchobj.casesens, thisdocument.foxitsearchobj.wholeword );
                            }

                            RxCore_GUI_PageCountChanged.countChanged( thisdocument.pages.length );
                            return Promise.resolve();
                        });
                    } else return Promise.reject();
                };

