                this.markupTextSearch = function(text, forward, casesens, padding){


                    if (text == thisdocument.markupsearchobj.expr && thisdocument.markupsearchobj.active) {
                        if (forward) {

                            thisdocument.markupsearchobj.next();
                            if (thisdocument.markupsearchobj.page != thisdocument.currentpage) {

                                thisdocument.GotoPage(thisdocument.markupsearchobj.page);
                            }
                            //thisdocument.pages[thisdocument.currentpage].clearSearch();
                            //thisdocument.pages[thisdocument.currentpage].showSearch();
                            thisdocument.pages[thisdocument.currentpage].zoomToMarkup(thisdocument.markupsearchobj.matcharray[thisdocument.markupsearchobj.indx], thisdocument.markupsearchobj.padding);
                        }
                        if (!forward) {
                            //thisdocument.pages[thisdocument.currentpage].clearSearch();

                            thisdocument.markupsearchobj.previous();
                            if (thisdocument.markupsearchobj.page != thisdocument.currentpage) {
                                thisdocument.GotoPage(thisdocument.markupsearchobj.page);
                            }
                            thisdocument.pages[thisdocument.currentpage].zoomToMarkup(thisdocument.markupsearchobj.matcharray[thisdocument.markupsearchobj.indx], thisdocument.markupsearchobj.padding);
                            //thisdocument.pages[thisdocument.currentpage].showSearch();
                            //gotomarkupobject
                        }
                    }
                    else {
                        thisdocument.markupsearchobj.matcharray = [];
                        thisdocument.markupsearchobj.expr = text;
                        thisdocument.markupsearchobj.forward = forward;
                        thisdocument.markupsearchobj.casesens = casesens;
                        thisdocument.markupsearchobj.active = false;
                        thisdocument.markupsearchobj.indx = 0;
                        thisdocument.markupsearchobj.page = 0;
                        if(padding){
                            thisdocument.markupsearchobj.padding = padding;
                        }



                        if (thisdocument.markupsearchobj.expr != ""){
                            for(var mi = 0; mi < thisdocument.markuplist.length; mi++){
                                if (thisdocument.markuplist[mi].FindText(thisdocument.markupsearchobj.expr, thisdocument.markupsearchobj.casesens)) {
                                    thisdocument.markupsearchobj.matcharray.push(thisdocument.markuplist[mi]);
                                }
                            }

                            thisdocument.markupSearchComplete();
                        }



                    }

                };


