                            //this.pages[i].dscalepdf = (this.pages[this.currentpage].pagecanvas.width * dscale) / this.pages[i].pagecanvas.width;
                            if (zoomin) {

                                //dscalepdf modified
                                thisdocument.pages[i].dscalepdf = thisdocument.pages[i].dscalepdf * factor;
                            }
                            else {
                                //dscalepdf modified
                                thisdocument.pages[i].dscalepdf = thisdocument.pages[i].dscalepdf / factor;
                            }
                            thisdocument.pages[i].dxpdf = thisdocument.pages[i].dxpdf - xdiff;
                            thisdocument.pages[i].pdfisrendered = false;
                            //console.log('recalcPages invalidation');
                            //this.dscalepdf = this.dscalepdf / factor;
