                this.setthumbnail = function (width, height, pagenumber) {


                    var thumbnail = thisdocument.getThumb(pagenumber);

                    if(thumbnail == undefined){
                        return;
                    }

                    var yscale = thumbnail.thumbnailobj.thumbnail.height / height;
                    var xscale = thumbnail.thumbnailobj.thumbnail.width / width;
                    var dscalelocal = Math.min(xscale, yscale);

                    //var dxlocal = (thisdocument.thumbnails[pagenumber].thumbnailobj.thumbnail.width - (width*dscalelocal)) / 2;
                    //var dylocal = (thisdocument.thumbnails[pagenumber].thumbnailobj.thumbnail.height - (height*dscalelocal)) / 2;
                    thumbnail.setthumbnail(0, 0, dscalelocal);

                    //thispage.setthumbnail(dxlocal,dylocal,dscalelocal);
                    if (thisdocument.pages[0] != undefined) {
                        if (thisdocument.pages[0].usepdfjs) {
                            thisdocument.thumbnails[pagenumber].setPDFdim(width, height);
                        }
                    }
                };
