                    if(pageindex > -1){
                        thisdocument.pages.splice(pageindex, 1);
                    }

                    if(thisdocument.pages.length == 0){
                        //no pages clase doc
                        //internalClosedoc(thisdocument.fileindex);
                        documentopen = true;
                        internalClosedocOrg(thisdocument.fileindex);

                    }else{
                        thisdocument.GotoPage(thisdocument.prevpage);
                    }


