                    //get array of pageobjects position.
                    var pgpos = thisdocument.getpagePositions(targetpagenum);
                    if (pgpos.positions[0] == 1 && targetpagenum < pgpos.midpage) {
                        //page range in start position and middle of page range not yet reached exit
                        return;
                    }
                    if (pgpos.positions[nMaxpages - 2] == thisdocument.pages.length - 1 && targetpagenum > pgpos.midpage) {
                        //page range in end position and middle of page range not yet reached exit
                        return;
                    }
                    if (pgpos.positions.length != 0) {
                        var targetpos = thisdocument.getTargetPositions(targetpagenum, pgpos);
                    }

