                this.clearHoverSpace = function(){
                    thisdocument.hoverspace = null;

                };
                this.drawHoverSpace = function(ctx){
                    if(thisdocument.hoverspace != null){

                        var scalefactor = thisdocument.getCurrentpage().dscalevector;
                        var xoffset = thisdocument.getCurrentpage().dxvector;
                        var yoffset = thisdocument.getCurrentpage().dyvector;
                        var mediax = thisdocument.getCurrentpage().VectorPageObj.x;
                        var mediay = thisdocument.getCurrentpage().VectorPageObj.y;
                        var mediah = thisdocument.getCurrentpage().VectorPageObj.h;

                        var xscaled = (thisdocument.hoverspace.path[0].x - mediax) * scalefactor;
                        var yscaled = (mediah - thisdocument.hoverspace.path[0].y) * scalefactor;

                        xscaled += xoffset;
                        yscaled += yoffset;

                        ctx.save();
                        ctx.lineWidth = 0;
                        ctx.fillStyle = thisdocument.hoverspace.color;
                        ctx.beginPath();

                        ctx.moveTo(xscaled, yscaled);

                        for (var counter = 1; counter < thisdocument.hoverspace.path.length; counter++) {
                            xscaled = ((thisdocument.hoverspace.path[counter].x - mediax) * scalefactor);
                            yscaled = ((mediah - thisdocument.hoverspace.path[counter].y) * scalefactor);

                            xscaled += xoffset;
                            yscaled += yoffset;

                            ctx.lineTo(xscaled, yscaled);
                        }

                        ctx.closePath();
                        ctx.fill();
                        ctx.restore();
                    }

                };
