                                    thisdocument.pages[this.currentpage - 1].dy = thisdocument.pages[this.currentpage].dy - (thisdocument.pages[this.currentpage].MainImageHeight * thisdocument.pages[this.currentpage].dscale) - 10;
                                    thisdocument.pages[this.currentpage - 1].dx = thisdocument.pages[this.currentpage].dx;
