                function checkpagestate(newpagenum) {
                    //no page object in posistion.
                    var bpgeundefined = (thisdocument.pages[newpagenum] == undefined);
                    if (bpgeundefined) {
                        var pageloaded = false;
                        var pdfdiminitset = false;
                    }
                    else {
                        pageloaded = thisdocument.pages[newpagenum].pageloaded;
                        pdfdiminitset = thisdocument.pages[newpagenum].pdfdiminitset;
                    }
                    return { havepage: !bpgeundefined, loaded: pageloaded, pdfdimset: pdfdiminitset };
                }
                function drawdummypagesabove(dx, dy, w, h, curpagenum, lastpage) {
                    /*var pgedbpos = getpagepos(dytemppdf, dytemppdf + heighttemppdf, thisdocument.currentpage - 1, thisdocument.pages.length - 1);
                    if(pgedbpos.bt){
                        drawdummypage(dxtemppdf, (dytemppdf + heighttemppdf) - 10, widthtemppdf, heighttemppdf);
                    }*/
                    //drawdummypage(dx, dy, w, h);
                    var nxtpage = 1;
                    var pagesep = 10;
                    var curpage = curpagenum;
                    var visiblepage = lastpage;
                    var pagestart = dy;
                    var pageend = pagestart + h;
                    //var pagestart = (dy - pagesep) - h;
                    //var pageend = pagestart + h;
                    //var curpage = curpagenum - nxtpage;
                    //var lastpage = lastpage;
                    //var pagepos = getpagepos(pagestart, pageend,curpage, lastpage);
                    while (curpage >= 0) {
                        if (pageend > pagesep) {
                            //drawdummypage(dx, pagestart, w, h);
                            visiblepage = curpage;
                        }
                        curpage = curpage - nxtpage;
                        pagestart = (pagestart - pagesep) - h;
                        pageend = pagestart + h;
                        //pageend = pagestart + h;
                        //var pagepos = getpagepos(pagestart, pageend,curpage, lastpage);
                    }
                    return visiblepage;
                }
                function drawdummypagesbelow(dx, dy, w, h, curpagenum, lastpage) {
                    //var pgedapos = getpagepos(dytemppdf, dytemppdf + heighttemppdf, thisdocument.currentpage + 1, thisdocument.pages.length - 1);
                    //if(pgedapos.ab){
                    //drawdummypage(dxtemppdf, dytemppdf + heighttemppdf + 10, widthtemppdf, heighttemppdf);
                    //}
                    //drawdummypage(dx, dy, w, h);
                    var pagestart = dy;
                    var curpage = curpagenum;
                    var visiblepage = 0;
                    //console.log('dummypage', pagestart);
                    var nxtpage = 1;
                    var pagesep = 10;
                    //var pagestart = dy + h + pagesep;
                    //var pageend = pagestart + h;
                    //var curpage = curpagenum + nxtpage;
                    //var lastpage = lastpage;
                    //var pagepos = getpagepos(pagestart, pageend,curpage, lastpage);
                    while (curpage <= lastpage) {
                        if (pagestart < canvasoheight) {
                            //drawdummypage(dx, pagestart, w, h);
                            //var curpos =  getpagepos(pagestart, pagestart + h, curpage, lastpage);
                            visiblepage = curpage;
                        }
                        curpage = curpage + nxtpage;
                        pagestart = pagestart + h + pagesep;
                        //pageend = pagestart + h;
                        //var pagepos = getpagepos(pagestart, pageend,curpage, lastpage);
                    }
                    return visiblepage;
                }
                function getpagepos(pagestart, pageend, curpagenum, lastpage) {
                    var ty = (canvasoheight / 2);
                    var bBelowTop = false;
                    var bBelowCenter = false;
                    var bAboveBottom = false;
                    var bAboveCenter = false;
                    //page below top = prev page visible
                    bBelowTop = (pagestart > 10 && curpagenum > 0);
                    //page below center switch to previous page
                    bBelowCenter = (pagestart - 10 > ty && curpagenum > 0);
                    //page above bottom = next page visible
                    bAboveBottom = (pageend < canvasoheight && curpagenum < lastpage);
                    //page above center switch to next page
                    bAboveCenter = (pageend + 10 < ty && curpagenum < lastpage);
                    return { bt: bBelowTop, bc: bBelowCenter, ab: bAboveBottom, ac: bAboveCenter };
                }
                function pagechange(pagepos, curpagenum) {
                    var newpage = curpagenum;
                    if (pagepos.bc) {
                        newpage -= 1;
                    }
                    if (pagepos.ac) {
                        newpage += 1;
                    }
                    return newpage;
                }
