    function getFileaddtoGLTF(Filepath){

        var PageObj;


        var XMLGetFile = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>";
        XMLGetFile += "<RxViewServer>";
        XMLGetFile += "<Command>GetFile</Command>";
        XMLGetFile += "<LicenseID>" + LicenseID + "</LicenseID>";
        XMLGetFile += "<FileURL>" + Filepath + "</FileURL>";
        XMLGetFile += "</RxViewServer>";


        sendHttpRequestXML('POST', xmlurl, XMLGetFile).then(function (xmlDoc){

            var i, j = 0;

            var totalpages = 0;

            var relpath = xmlurlrel;

            var layoutxmlobj = xmlDoc.getElementsByTagName('Layout');
            for (i = 0; i < layoutxmlobj.length; i++) {
                var layoutname = layoutxmlobj[i].getElementsByTagName("LayoutName")[0].firstChild.nodeValue;
                //DocObj.addlayout(layoutname);

                var pagexmlobj = layoutxmlobj[i].getElementsByTagName('Page');

                for (j = 0; j < pagexmlobj.length; j++) {

                    if (j == 0 && i == 0) {
                        //PageObj = new PageObject(pagexmlobj[j], layoutname, true, path, j, DocObj);
                        //DocObj.addthumbnail(new ThumbnailObject(pagexmlobj[j],layoutname, DocObj,  j));
                        //DocObj.addpage(PageObj, true);
                        //<VectorGLTF3DSRC>/cache/20160125westriverside hospital-ifc2x3-autodesk_hospital_metric_plumbing_2015-17d7408-5172689d/1_1.glb</VectorGLTF3DSRC>
                        if (pagexmlobj[j].getElementsByTagName("VectorGLTF3DSRC")[0] != undefined) {
                            var Vector3DBinarySRC = encodeURI(relpath + pagexmlobj[j].getElementsByTagName("VectorGLTF3DSRC")[0].firstChild.nodeValue);
                            var VectorMetadataSRC = encodeURI(relpath + pagexmlobj[j].getElementsByTagName("VectorMetadataSRC")[0].firstChild.nodeValue);

                            DocObj.getCurrentpage().addtoGLTFScene(Vector3DBinarySRC, VectorMetadataSRC);
                        }

                    }

                }

                totalpages += j;

            }

        }).catch(function(error){

            commonErrorCatchEx("getFileaddtoGLTF", error);

        });


    }

