    function getGUIDEx(operation, markupobject){

            //GetGUID

            if(!operation.created && markupobject.uniqueID != 0){

                if(RxCore_GUI_GuidRecieved != undefined){
                    RxCore_GUI_GuidRecieved.guidcomplete(markupobject.uniqueID, operation, true);
                }
                return;

            }


            var XMLGetGUID = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>";
            XMLGetGUID += "<RxViewServer>";
            XMLGetGUID += "<Command>GetGUID</Command>";
            XMLGetGUID += "<LicenseID>" + LicenseID + "</LicenseID>";
            XMLGetGUID += "</RxViewServer>";

            sendHttpRequest('POST', xmlurl, '', XMLGetGUID).then(function (response){
                var GUID = response;

                markupobject.setUniqueID(GUID);

                if(RxCore_GUI_GuidRecieved != undefined){
                    RxCore_GUI_GuidRecieved.guidcomplete(GUID, operation, true);
                }

            }).catch(function(error){

                if(error.status){
                     console.log(error.status);
                }else{
                    console.log(error);
                }
                if(RxCore_GUI_GuidRecieved != undefined){
                    RxCore_GUI_GuidRecieved.guidcomplete(error,operation, false);
                }


            });

    }


