    function getMarkup(MarkupFile, DocRef) {

        var PageObj;

        sendHttpRequestXML('GET', MarkupFile).then(function (xmlDoc){



            markupXMLhandler(xmlDoc, DocRef, MarkupFile);




        }).catch( function(error) {

            if(error.status){
                if (error.status == 404) {
                    console.log("XML could not be found");
                } else if (error.status == 503) {
                    console.log("Server is down");
                } else if (error.status == 501) {
                    console.log("Markup could not be loaded");
                }
            }else{
                console.log(error);
            }
        });

    }


