                                var linescale = ( localLinewidth / fixedscale);
                                var linescalesegment = ( localLinewidthSegment / fixedscale);

                                createAndAppendElement(entityNode, "LineWidth", linescale);
                                createAndAppendElement(entityNode, "LineWidthSegment", linescalesegment);


