    async function openDatabase(storeName) {
        //debugger
        return new Promise((resolve, reject) => {
          const request = indexedDB.open("myAppDatabase", 1);

          // Upgrade database if necessary
          request.onupgradeneeded = function(event) {
            const db = event.target.result;
      //debugger
            // Create an object store for saving images, stamps, symbols, and signatures
            if (!db.objectStoreNames.contains(storeName)) {
                if (storeName === 'Rxlic') {
                    const objectStore = db.createObjectStore(storeName, { keyPath: "id", autoIncrement: true });
                        objectStore.createIndex("Rxlic", "Rxlic", { unique: false });
                } else if (storeName === 'User') {
                    const objectStore = db.createObjectStore(storeName, { keyPath: "id", autoIncrement: true });
                        objectStore.createIndex("User", "User", { unique: false });
                        objectStore.createIndex("UserName", "UserName", { unique: false });
                }
            }
          };

          request.onsuccess = function(event) {
            resolve(event.target.result);
          };

          request.onerror = function(event) {
            reject("Database error: " + event.target.errorCode);
          };
        });
      }

      // Function to save data in IndexedDB
      async function saveDataToIndexedDB(data) {
        //debugger
        const db = await openDatabase(data.store);

        const transaction = db.transaction(data.store, "readwrite");
        const store = transaction.objectStore(data.store);

        // Add the data to the store
        const request = store.add({ fileData: data });

        request.onsuccess = function() {
          console.log("Data successfully saved to IndexedDB!");
        };

        request.onerror = function(event) {
          console.error("Error saving data to IndexedDB: ", event.target.errorCode);
        };
      }

      // Function to retrieve data from IndexedDB
      async function getDataFromIndexedDB(id) {
        let db = await openDatabase();

        let transaction = db.transaction("assetsStore", "readonly");
        let store = transaction.objectStore("assetsStore");

        let request = store.get(id);

        return new Promise((resolve, reject) => {
          request.onsuccess = function(event) {
            resolve(event.target.result);
          };

          request.onerror = function(event) {
            reject("Error retrieving data from IndexedDB: " + event.target.errorCode);
          };
        });
      }

