    function printDiv(){

        hasnotprinted = true;


        if(rxprintcontainer == undefined){
            return;
        }

        if(RxCore_printhelper().docObj == null){
            return;
        }

        //pageCanvases = [];
        //aDrawpages = [];
        //canvimages = [];
        //var aDrawmarkup = [];
        //var canvimages = [];
        //canvaspages = [];
        clearPrintDiv();

        //const paperwidthA4px = 2460;
        //const paperheightA4px = 3480;

        try {
            PaperHeight = RxCore_printhelper().getPaperHeight();
             //PaperHeight = 3480;
         }
         catch (e) {
             PaperHeight = paperheightA4px;
         }

         try {
            PaperWidth = RxCore_printhelper().getPaperWidth();
            //PaperWidth = 2460;
        }
        catch (e) {
            PaperWidth = paperwidthA4px;

        }

        try {
          PrintRect = RxCore_printhelper().getPrintRect();

        }
        catch(e){
          PrintRect = undefined;
        }

        var paperobj = {
            width : PaperWidth,
            height : PaperHeight,
            printrect : PrintRect
          };

        var pwidth = (paperobj.width / 25.4)* 96;
        var pheight = (paperobj.height / 25.4)* 96;

        var pwidthpx = pwidth + "px";
        var pheightpx = pheight + "px";

        var canvashireswidth = (paperobj.width / 25.4)* 300;
        var canvashiresheight = (paperobj.height / 25.4)* 300;

        //canvaso.width = canvashireswidth;
        //canvaso.height = canvashiresheight;

        //canvaso.style.width = pwidth + "px";
        //canvaso.style.height = pheight + "px";


        var numpages = RxCore_printhelper().docObj.pages.length;



        for(var i = 0; i < numpages; i++){
            //var container = rxprintcontainer;

            var canvpage = document.createElement('canvas');
            if(!canvpage){
            alert('Error: I cannot create a new canvas element!');
                return;
            }

            canvpage.id     = 'page' + i;

            canvpage.width  = canvashireswidth;
            canvpage.height = canvashiresheight;

            canvpage.style.width  = pwidthpx;
            canvpage.style.height = pheightpx;

            rxprintcontainer.appendChild(canvpage);

            aDrawpages[i] = false;

            var contextpg = canvpage.getContext('2d');

            if (!contextpg) {
                alert('Error: failed to getContext!');
                return;
            }

            pageCanvases.push(contextpg);
        }



        /*if (RxCore_printhelper().docObj.foxitdoc != null){




            for (var pg = 0; pg < numpages; pg++) {

                canvaspages.push(new printpdfpageobject(pg, paperobj));

                //canvaspages[pg].queueRenderPage();

            }


        }*/

        RxCore_printhelper().onPrintpage.connect(onPrintpage);
        RxCore_printhelper().docObj.printDocument(paperobj);

        /*if (RxCore_printhelper().docObj.pdfDoc != null){

            for (var pg = 0; pg < numpages; pg++) {

                canvaspages.push(new printpdfpageobject(pg, paperobj));
                canvaspages[pg].queueRenderPage();

            }


        }else{



        }*/



    }

