    function imageload(ev) {
        var yscale = 0.0;
        var xscale = 0.0;
        var dxlocal = 0.0;
        var dylocal = 0.0;
        var dscalelocal = 0.0;
        var imagewidth = 0;
        var imageheight = 0;

        var target = ev.target || ev.srcElement;

        //if (ev.srcElement.src.toLowerCase() == DocObj.getCurrentpage().MainImageSRC.toLowerCase()){
        if (target.src.toLowerCase() == DocObj.getCurrentpage().MainImageSRC.toLowerCase()) {
            //largeimageloaded = true;
            //SetImageDim(ev.srcElement); //use width and height from xml instead of calculating
            imagewidth = DocObj.getCurrentpage().MainImageWidth;
            imageheight = DocObj.getCurrentpage().MainImageHeight;

            //set image fixed scale for markup
            yscale = fixedScaleSize.height / DocObj.getCurrentpage().MainImageHeight; //thispage.MainImageHeight;
            xscale = fixedScaleSize.width / DocObj.getCurrentpage().MainImageWidth; // thispage.MainImageWidth;
            DocObj.getCurrentpage().fixedScale = Math.min(xscale, yscale);


            yscale = canvasoheight / imageheight;
            xscale = canvasowidth / imagewidth;
            dscalelocal = Math.min(xscale, yscale);
            //DocObj.getCurrentpage().dscale = dscalelocal;

            dxlocal = (canvasowidth - (imagewidth * dscalelocal)) / 2;
            dylocal = (canvasoheight - (imageheight * dscalelocal)) / 2;

            //DocObj.getCurrentpage().dx = dxlocal;
            //DocObj.getCurrentpage().dy = dylocal;

            DocObj.getCurrentpage().setimagedimlarge(dxlocal, dylocal, dscalelocal);
            //hideDownloadDialog();
            if (RxCore_GUI_Download != undefined) {
                RxCore_GUI_Download.setDownload("hide");
            }


        }

        //if (ev.srcElement.src.toLowerCase() == DocObj.getCurrentpage().SmallImageSRC.toLowerCase()){
        if (target.src.toLowerCase() == DocObj.getCurrentpage().SmallImageSRC.toLowerCase()) {
            //smallimageloaded = true;
            //SetImageDim(ev.srcElement); //use width and height from xml instead of calculating
            imagewidth = DocObj.getCurrentpage().SmallImageWidth;
            imageheight = DocObj.getCurrentpage().SmallImageHeight;

            yscale = canvasoheight / imageheight;
            xscale = canvasowidth / imagewidth;
            dscalelocal = Math.min(xscale, yscale);

            dxlocal = (canvasowidth - (imagewidth * dscalelocal)) / 2;
            dylocal = (canvasoheight - (imageheight * dscalelocal)) / 2;


            DocObj.getCurrentpage().setimagedimsmall(dxlocal, dylocal, dscalelocal);
            //hideDownloadDialog();
            if (RxCore_GUI_Download != undefined) {
                RxCore_GUI_Download.setDownload("hide");
            }

            //draw_image(ev.srcElement);
            //DocObj.getCurrentpage().draw_image();

        }

        //imageloaded = true;
        //drawmarkupAll(cntximg);


    }

    function get_splash(url, image) {
        image.addEventListener('load', splashload, false);
        image.src = url;
    }


    function get_image(url, image) {

        //showDownloadDialog();

        if (RxCore_GUI_Download != undefined) {
            RxCore_GUI_Download.setDownload("show");
        }

        image.addEventListener('load', imageload, false);
        image.addEventListener('progress', imageloadprogress, false);
        image.src = url;


    }

