        docobjxmltxt += "<LayoutName>Default</LayoutName>\n";
        docobjxmltxt += "</Layout>\n";
        docobjxmltxt += "</RxViewServer>\n";

        var docobjxml = parseXML(docobjxmltxt);

        var numpagenode = docobjxml.createElement("NumPages");

        var pageNode = docobjxml.createElement("Page");

        var szpagenum = docobjxml.createTextNode("1");
        numpagenode.appendChild(szpagenum);

        docobjxml.getElementsByTagName("RxViewServer")[0].appendChild(numpagenode);

        createAndAppendElement(pageNode, "PageName", "Default");
        createAndAppendElement(pageNode, "Compression", "---");
        createAndAppendElement(pageNode, "DPI", "0.02540000");
        createAndAppendElement(pageNode, "OffsetX", "0.00000");
        createAndAppendElement(pageNode, "OffsetY", "0.00000");
        createAndAppendElement(pageNode, "OriginalScale", "1.00000");

        createAndAppendElement(pageNode, "OriginalScale", "1.00000");


