    const sendHttpRequestwevents = function(method, url, rtype, eventlist, data){

        const xhr = new XMLHttpRequest();

        xhr.withCredentials = bUseCredentials;

        /*var eventlist = [
            {event : "progress", func : uploadPDFSilent},
            {event : "load", func : uploadPDFSilentComplete},
            {event : "error", func : uploadFailed},
            {event : "abort", func : uploadCanceled}
        ];*/

        for(var ei = 0; ei < eventlist.length; ei++ ){

            if(eventlist[ei].event == "progress" && eventlist[ei].bupload){
                xhr.upload.addEventListener(eventlist[ei].event, eventlist[ei].func, false);
            }else{
                xhr.addEventListener(eventlist[ei].event, eventlist[ei].func, false);
            }

        }

        try {
            xhr.open(method,url);
        } catch (e) {
            reject("Error 1 - " + e);
        }

        try {
            xhr.responseType = rtype;
        } catch (e) {
            reject("Error 2 - " + e);
        }

        if(buseAuth){
            var auth = getAuth();

            if (auth.authset){
                xhr.setRequestHeader('Authorization', auth.authString + auth.baseuserstring);
            }

        }

        if(data){
            xhr.send(data);
        }else{
            xhr.send();
        }

        //xhr.upload.addEventListener("progress", uploadPDFSilent, false);
        //xhr.addEventListener("load", uploadPDFSilentComplete, false);
        //xhr.addEventListener("error", uploadFailed, false);
        //xhr.addEventListener("abort", uploadCanceled, false);

    }

    function getAuth(){

        var auth = {authString : "", baseuserstring : "", authset : false};

        if(buseAuth){

            auth.authString = AuthType + " ";

            if (buseEncToken){

                auth.baseuserstring = AuthToken;
                auth.authset = true;

            }else{

                var userString = AuthName;
                userString += ":";
                userString += AuthPass;
                auth.baseuserstring = window.btoa(userString);
                auth.authset = true;
            }

        }

        return auth;
    }

    const sendHttpRequestXML = function(method, url, data, callbacklist){
        const xhrpromise = new Promise(function(resolve,reject){
            const xhr = new XMLHttpRequest();

            //callbacklist

            xhr.withCredentials = bUseCredentials;

            try {
                xhr.open(method,url);
            } catch (e) {
                reject("Error 1 - " + e);
            }
            try {
                xhr.responseType = '';
            } catch (e) {
                reject("Error 2 - " + e);
            }


            if(buseAuth){

                var auth = getAuth();

                if (auth.authset){
                    xhr.setRequestHeader('Authorization', auth.authString + auth.baseuserstring);
                }

            }

            xhr.onload = function(ev){
                if (this.status == 200) {

                    var xmlDoc = this.responseXML;


                    if (xmlDoc == null || xmlDoc.documentElement == null) {


                        xmlDoc = parseXML(this.responseText);

                        /*XMLParser(this.responseText).then(function (xml){

                            xmlDoc = xml;
                            resolve(xmlDoc);

                        }).catch(function (error){

                            reject('Unable to get XML');

                        });*/

                        //xmlDoc = $.parseXML(this.responseText).documentElement;
                    }

                    szLatestresponseHeaders = this.getAllResponseHeaders();

                    if(RxCore_GUI_getResponsHeaders != undefined){
                        RxCore_GUI_getResponsHeaders.setRespHeaders(szLatestresponseHeaders);
                    }

                    if(xmlDoc == null || xmlDoc.documentElement == null){
                        reject('Unable to get XML');
                    }else{
                        resolve(xmlDoc);
                    }

                }else{
                    reject(this);
                }

                if(callbacklist){
                    for(var i = 0;i < callbacklist.length; i++){
                        if(callbacklist[i].event == "callback"){
                            if (callbacklist[i].func && typeof callbacklist[i].func === "function") {
                                callbacklist[i].func(this);
                            }
                        }
                    }

                }



            };

            xhr.onerror = function(ev){
                //reject('Something went wrong');
                reject('Failed to connect to ' + url);

            };

            //Download progress
            xhr.addEventListener("progress", function (evt) {
                if (evt.lengthComputable) {
                    var percentComplete = evt.loaded / evt.total;

                    if(callbacklist){
                        for(var i = 0;i < callbacklist.length; i++){
                            if(callbacklist[i].event == "progressCallBack"){
                                if (callbacklist[i].func && typeof callbacklist[i].func === "function") {
                                    callbacklist[i].func(percentComplete);
                                }
                            }
                        }
                    }
                }
            }, false);

            xhr.send(data);

        });

        return xhrpromise;
    };

    const getRxUniqueID = function(reqheader){


        const xhrpromise = new Promise(function(resolve,reject){
            const xhr = new XMLHttpRequest();

            var XMLGetGUID = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>";
            XMLGetGUID += "<RxViewServer>";
            XMLGetGUID += "<Command>GetGUID</Command>";
            XMLGetGUID += "<LicenseID>" + LicenseID + "</LicenseID>";
            XMLGetGUID += "</RxViewServer>";



            xhr.open('POST', xmlurl);

            if(buseAuth){

                var auth = getAuth();

                if (auth.authset){
                    xhr.setRequestHeader('Authorization', auth.authString + auth.baseuserstring);
                }

            }

            try {
                xhr.responseType = '';
            } catch (e) {
                reject("Error 2 - " + e);
            }

            if(reqheader){
                xhr.setRequestHeader(reqheader.name, reqheader.value);
            }

            xhr.onload = function(ev){
                if (this.status == 200) {
                    resolve(xhr.response);
                }else{
                    reject(this);
                }
            };

            xhr.onerror = function(ev){
                reject('Something went wrong');

            };

            xhr.send(XMLGetGUID);



        });

        return xhrpromise;
    }

    const sendHttpRequest = function(method, url, rtype, data, reqheader){

        const xhrpromise = new Promise(function(resolve,reject){
            const xhr = new XMLHttpRequest();

            xhr.open(method,url);

            if(buseAuth){

                var auth = getAuth();

                if (auth.authset){
                    xhr.setRequestHeader('Authorization', auth.authString + auth.baseuserstring);
                }

            }

            try {
                xhr.responseType = rtype;
            } catch (e) {
                reject("Error 2 - " + e);
            }

            if(reqheader){
                xhr.setRequestHeader(reqheader.name, reqheader.value);
            }

            xhr.onload = function(ev){
                if (this.status == 200) {
                    resolve(xhr.response);
                }else{
                    reject(this);
                }
            };

            xhr.onerror = function(ev){
                reject('Something went wrong');

            };


            if(data){
                xhr.send(data);
            }else{
                xhr.send();
            }

        });

        return xhrpromise;

    };


    function downloadSignature(username, binitial){

        if(signatureGet == undefined){
            return;
        }

        if(binitial && initialGet == undefined){
            return;
        }



        var downloadURL = signatureGet + '&' + username;

        if(binitial){
            downloadURL = initialGet + '&' + username;
        }


        sendHttpRequest('GET', downloadURL,"arraybuffer").then(function (response){

            //var url = URL.createObjectURL(response);

            var singaturePNGData = new Blob([response], {type: "image/png"});

            if (response) {

                const img = new Image();
                img.src = URL.createObjectURL(singaturePNGData);

                img.onload = function() {

                  //console.log(img.width, img.height)

                  var signatureinfo = { data : singaturePNGData, width : img.width, height : img.height,  username : username, initials : binitial};

                  if (RxCore_GUI_getsignatureComplete != undefined){
                      RxCore_GUI_getsignatureComplete.onSignReceived(signatureinfo);
                  }

                }


            }

        }).catch(function(error){

            if(error.status){
                console.log("signatureload", error.status);
            }else{
                console.log("signatureload", error);
            }

        });


    }

