    function touchEvents(ev) {

        if(!bIsmobile){
            return;
        }

        ev.preventDefault();

        var posX = 0;
        var posY = 0;
        var moveint = 0;

        if (RxCore_GUI_3DWalkthrough != undefined) {
            var _wheelImg = RxCore_GUI_3DWalkthrough._wheelImg;
            if (_wheelImg != undefined) {
                if (_wheelImg.x == undefined) {
                    var elemRect = _wheelImg.getBoundingClientRect();
                    var _wheelImgX = elemRect.left + 100;
                    var _wheelImgY = elemRect.top + 100;
                } else {
                    _wheelImgX = _wheelImg.x + 100;
                    _wheelImgY = _wheelImg.y + 100;

                }
            }

        } else {
            _wheelImgX = 0;
            _wheelImgY = 0;
        }


        switch (ev.type) {
            case 'mousedown':
                ev.preventDefault();
                posX = ev.pageX;
                posY = ev.pageY;
                moveint = 1;

                getAngleWithXAxis(100, posX - _wheelImgX, -posY + _wheelImgY, moveint);

                break;
            case 'MSPointerDown':
                ev.preventDefault();
                posX = ev.pageX;
                posY = ev.pageY;
                moveint = 1;
                getAngleWithXAxis(100, posX - _wheelImgX, -posY + _wheelImgY, moveint);

                break;
            case 'pointerdown':
                ev.preventDefault();
                posX = ev.pageX;
                posY = ev.pageY;
                moveint = 1;
                getAngleWithXAxis(100, posX - _wheelImgX, -posY + _wheelImgY, moveint);

                break;
            case 'mousemove':
                break;
            case 'touchstart':
                ev.preventDefault();
                posX = ev.targetTouches[0].pageX;
                posY = ev.targetTouches[0].pageY;
                moveint = 1;
                getAngleWithXAxis(100, posX - _wheelImgX, -posY + _wheelImgY, moveint);
                break;
            case 'touchmove':
                break;
            case 'mouseup':
                posX = ev.pageX;
                posY = ev.pageY;
                moveint = 0;
                getAngleWithXAxis(100, posX - _wheelImgX, -posY + _wheelImgY, moveint);
                break;
            case 'MSPointerUp':
                posX = ev.pageX;
                posY = ev.pageY;
                moveint = 0;
                getAngleWithXAxis(100, posX - _wheelImgX, -posY + _wheelImgY, moveint);
                break;
            case 'pointerup':
                posX = ev.pageX;
                posY = ev.pageY;
                moveint = 0;
                getAngleWithXAxis(100, posX - _wheelImgX, -posY + _wheelImgY, moveint);

                break;
            case 'mouseout':

                for (var diri = 1; diri < 7;diri++){
                    if(DocObj.getCurrentpage().walkthroughcontrol.movedirection){
                        DocObj.getCurrentpage().walkthroughcontrol.movedirection(diri,false);
                    }

                }
                /*DocObj.getCurrentpage().walkthroughcontrol.moveForward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveBackward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveLeft = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveRight = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveUp = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveDown = false;*/

                moveint = 0;
                break;
            case 'MSPointerOut':

                for (var diri = 1; diri < 7;diri++){
                    if(DocObj.getCurrentpage().walkthroughcontrol.movedirection){
                        DocObj.getCurrentpage().walkthroughcontrol.movedirection(diri,false);
                    }

                }

                /*DocObj.getCurrentpage().walkthroughcontrol.moveForward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveBackward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveLeft = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveRight = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveUp = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveDown = false;*/

                moveint = 0;
                break;
            case 'pointerout':

                for (var diri = 1; diri < 7;diri++){
                    if(DocObj.getCurrentpage().walkthroughcontrol.movedirection){
                        DocObj.getCurrentpage().walkthroughcontrol.movedirection(diri,false);
                    }

                }

                /*DocObj.getCurrentpage().walkthroughcontrol.moveForward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveBackward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveLeft = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveRight = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveUp = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveDown = false;*/

                moveint = 0;
                break;

            case 'touchcancel':
                ev.preventDefault();

                for (var diri = 1; diri < 7;diri++){
                    if(DocObj.getCurrentpage().walkthroughcontrol.movedirection){
                        DocObj.getCurrentpage().walkthroughcontrol.movedirection(diri,false);
                    }

                }
                /*DocObj.getCurrentpage().walkthroughcontrol.moveForward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveBackward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveLeft = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveRight = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveUp = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveDown = false;*/
                moveint = 0;
                break;
            case 'touchend':
                //alert('touchend');
                ev.preventDefault();
                for (var diri = 1; diri < 7;diri++){
                    if(DocObj.getCurrentpage().walkthroughcontrol.movedirection){
                        DocObj.getCurrentpage().walkthroughcontrol.movedirection(diri,false);
                    }

                }
                //posX = ev.targetTouches[0].pageX;
                //posY = ev.targetTouches[0].pageY;
                //posX = ev.changedTouches[0].pageX;
                //posY = ev.changedTouches[0].pageY;
                /*DocObj.getCurrentpage().walkthroughcontrol.moveForward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveBackward = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveLeft = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveRight = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveUp = false;
                DocObj.getCurrentpage().walkthroughcontrol.moveDown = false;*/




                moveint = 0;
                //getAngleWithXAxis(100, posX - _wheelImgX, - posY + _wheelImgY, moveint);

                break;
        }
        //DocObj.getCurrentpage().walkthroughcontrol.updateMovementVector();
        //DocObj.getCurrentpage().walkthroughcontrol.updateRotationVector();


    }

    function regEventsgeneric(element, func){
        //ev_canvas
        element.addEventListener("touchstart", func, false);
        element.addEventListener("touchmove", func, true);
        element.addEventListener("touchend", func, false);
        element.addEventListener("touchcancel", func, false);

        element.oncontextmenu = function () {
            return false;
        };

        //canvas.addEventListener("dbltap", ev_canvas, false);
        //canvas.addEventListener("dblclick", ev_canvas, false);

        //canvas.addEventListener('wheel', ev_canvas, true);
        //canvas.addEventListener('mousewheel', ev_canvas, true);
        //canvas.addEventListener('DOMMouseScroll', ev_canvas, true);

        //canvas.addEventListener("drop", ev_canvas, false);
        //canvas.addEventListener("dragover", ev_canvas, false);



        if(bDisableMSIE11Eventcheck){

            element.addEventListener('mousemove', func, false);
            element.addEventListener('mousedown', func, false);
            element.addEventListener('mouseup', func, false);
            element.addEventListener('mouseout', func, false);



        }else{
            if (window.navigator.msPointerEnabled) {
                element.addEventListener('MSPointerMove', func, false);
                element.addEventListener('MSPointerDown', func, false);
                element.addEventListener('MSPointerUp', func, false);
                element.addEventListener('MSPointerOut', func, false);



            } else {
                element.addEventListener('mousemove', func, false);
                element.addEventListener('mousedown', func, false);
                element.addEventListener('mouseup', func, false);
                element.addEventListener('mouseout', func, false);

            }
        }

    }

    function regEvents(element) {

        element.addEventListener('touchstart', touchEvents);
        element.addEventListener('touchmove', touchEvents);
        element.addEventListener('touchcancel', touchEvents);
        element.addEventListener('touchend', touchEvents);

        if(bDisableMSIE11Eventcheck){
            element.addEventListener('mousemove', touchEvents);
            element.addEventListener('mousedown', touchEvents);
            element.addEventListener('mouseup', touchEvents);
            element.addEventListener('mouseout', touchEvents);

        }else{
            if (window.navigator.msPointerEnabled) {
                element.addEventListener('MSPointerMove', touchEvents);
                element.addEventListener('MSPointerDown', touchEvents);
                element.addEventListener('MSPointerUp', touchEvents);
                element.addEventListener('MSPointerOut', touchEvents);

            }else{
                element.addEventListener('mousemove', touchEvents);
                element.addEventListener('mousedown', touchEvents);
                element.addEventListener('mouseup', touchEvents);
                element.addEventListener('mouseout', touchEvents);

            }
        }



    }

