        class Rx_GUIDocumentSearch {
        constructor(callback) {
          var scope = this;
          //Set to true if a page in document has text. Do not set back to false
          this.hastext = false;
          this.seachText = "";
          this.wholeText = false;
          this.casesens = false;
          this.callback = [callback];
          this.connect = function (callback) {
            scope.callback = [...scope.callback, callback];
          };
          this.setFilter = function (text, casesens, wholeText) {
            this.seachText = text;
            this.casesens = casesens;
            this.wholeText = wholeText;
          };
          this.matchesFound = function (matches) {
            scope.callback.forEach((callback) => {
              if (typeof callback === "function") {
                callback(matches);
              }
            });
          };
          this.isCaseSensitive = function () {
            return this.casesens;
          };
        }
      }


