        class Rx_PageThumbnailConn {
            constructor(callback) {
                var scope = this;
                this.callback = callback;
                this.connect = function (callback) {
                    scope.callback = callback;
                };
                this.getHeight = function () {
                    return canvasoheight;
                };
                this.getCurrentPage = function () {
                    return DocObj.getcurPage();
                };
                this.hasmarkup = function (page) {
                    var hasmarkup = false;
                    for (var i = 0; i < DocObj.markuplist.length; i++) {
                        if (DocObj.markuplist[i].pagenumber == page) {
                            hasmarkup = true;
                        }
                    }
                    return hasmarkup;
                };
                this.notify = function () {
                    if (typeof scope.callback === "function") {
                        scope.callback(this.pageindex, this.thumbnail);
                    }
                };
                this.setThumbnail = function (pgindex, thumbnail) {
                    this.thumbnail = thumbnail;
                    this.pageindex = pgindex;
                    this.notify();
                };
            }
        }

