        class Rx_CalibrateConn {
            constructor(callback) {
                var scope = this;
                this.callback = callback;
                this.connect = function (callback) {
                    scope.callback = callback;
                };
                this.getUnitlabel = function () {

                    //DocObj.getCurrentpage().scaleObject
                    //return DocObj.getCurrentpage().Unitlabel;

                    return DocObj.getCurrentpage().scaleObject.Unitlabel;



                };
                this.setCalibration = function (val) {
                    var pagenumber = -1;
                    if (documentopen) {
                        //nCalibrateScale = DocObj.getCurrentpage().setCalibration(val);
                        nCalibrateScale = DocObj.getCurrentpage().scaleObject.setCalibration(val);

                        pagenumber = DocObj.getCurrentpage().pagenumber;
                    }
                    else {
                        if (val) {
                            if (nCalibrateSet != 0) {
                                nCalibrateScale = nCalibrateMeasured / nCalibrateSet;
                                nCalibrateScale = 1 / nCalibrateScale;
                                //setCalibratebtn();
                                MeasureScale = nCalibrateScale;
                            }
                        }
                        else {
                            nCalibrateScale = 1;
                        }
                    }
                    var calibratedata = {
                        calibratescale: nCalibrateScale,
                        pagenumber: pagenumber
                    };
                    if (RxCore_GUI_CalibrateComplete != undefined) {
                        RxCore_GUI_CalibrateComplete.onCalibrate(calibratedata);
                    }
                };
                this.SetTempCal = function (value) {
                    nCalibrateSet = value;
                };

                this.setCalibrateScaleByLength = function () {
                    if (nCalibrateSet != 0) {
                        nCalibrateScale = nCalibrateMeasured / nCalibrateSet;
                        nCalibrateScale = 1 / nCalibrateScale;
                    }
                };

                this.setCalibrateScale = function (val) {
                    nCalibrateScale = val;
                };
                this.getMeasureScale = function () {
                    return nCalibrateScale;
                };

                this.setCalibrate = function (calibratedata) {
                    if (typeof scope.callback === "function") {
                        scope.callback(calibratedata);
                    }
                };


            }
        }


