        function hasDocPage(){
            var docpageNotready = true;

            if(DocObj == null || DocObj == undefined){
                docpageNotready = false;
            }else{
                var page = DocObj.getCurrentpage();

                if(page == undefined){
                    docpageNotready = false;
                }
            }

            return docpageNotready;

        }


        function docpagNotReady(){

            var docpageNotready = false;

            if (!documentopen) {
                docpageNotready = true;
            }

            if(DocObj == null || DocObj == undefined){
                docpageNotready = true;
            }else{
                var page = DocObj.getCurrentpage();

                if(page == undefined){
                    docpageNotready = true;
                }
            }

            return docpageNotready;

        }

        function RxCore_getMarkupTypebyname(sztypename){
            var markuptypes = RxCore_getMarkupTypes();

            var returntype = undefined;

            for(var ti = 0; ti < markuptypes; ti++){
                if (markuptypes[ti].typename == sztypename){
                    returntype = markuptypes[ti];
                }
            }

            return returntype;

        }



