    function RxCore_getfloorplanDocs(floorelvobj){

        //find all 3d navigation pages and check elevation

        var docpages = [];
        var doc = null;
        var page = null;
        var curfloor = null;

        for (var i = 0; i < OpenFiles.length; i++) {


            if (OpenFiles[i].pages.length > 0){

                for(var pi = 0; pi < OpenFiles[i].pages.length; pi++){

                    curfloor = OpenFiles[i].pages[pi].getFloorLevel();
                    if(floorelvobj.floorindex == curfloor.floorindex){
                        docpages.push({docindex : i, pageindex : pi, floorindex : curfloor.floorindex, replaced : curfloor.replaced});
                    }
                    //docpages.push({docindex : i, page : pages[pi]});
                }
            }

        }

        return docpages;

    }

