    function new_moveto3dpart(){


        if (DocObj.getCurrentpage().usevector3Dxml) {

            if (DocObj.getCurrentpage().Vector3DPageObj.getcur3DView() != null){
                return;
            }

            var mesharray = DocObj.getCurrentpage().Vector3DPageObj.getMeshChildren();
            var markuparray = DocObj.getCurrentpage().Vector3DPageObj.getMarkupChildren();
            var addedmesharray = DocObj.getCurrentpage().Vector3DPageObj.getAddedMeshChildren();


            if (mesharray.length == 0){
                return;
            }

            var partidobj = DocObj.getCurrentpage().Vector3DPageObj.getSelectedPart();


            if (partidobj.index !=-1){

                var raycaster = new THREE.Raycaster();

                DocObj.getCurrentpage().Vector3DPageObj.scene.updateMatrixWorld();


                var origox = DocObj.getCurrentpage().Vector3DPageObj.scene.position.x;
                var origoy = DocObj.getCurrentpage().Vector3DPageObj.scene.position.y;
                var origoz = DocObj.getCurrentpage().Vector3DPageObj.scene.position.z;

                var zdiff = 0;
                var modelscale = DocObj.getCurrentpage().Vector3DPageObj.scale;

                var offset = DocObj.getCurrentpage().Vector3DPageObj.getmminUnit(2500);
                var raynear = DocObj.getCurrentpage().Vector3DPageObj.getmminUnit(10);
                var zoffset = DocObj.getCurrentpage().Vector3DPageObj.getfloorheight();

                /*if(DocObj.getCurrentpage().Vector3DPageObj.unit == 1){
                    var offset = 2.5;
                    //var zoffset = (1.8 - zdiff) * modelscale;
                    var zoffset = 1.8;
                    var raynear = 0.01;
                }else if(DocObj.getCurrentpage().Vector3DPageObj.unit == 0){
                    offset = 2500;// * modelscale;
                    //zoffset = (1800 - zdiff) * modelscale;
                    zoffset = 1800;
                    raynear = 10;
                }else if(DocObj.getCurrentpage().Vector3DPageObj.unit == 2){
                    offset = 8.2;// * modelscale;
                    //zoffset = (1800 - zdiff) * modelscale;
                    zoffset = 5.9;
                    raynear = 0.03;

                }*/

                var pingarray = [];

                if(partidobj.isadded){

                    if (partidobj.group){

                        var partcenter = addedmesharray[partidobj.addedmeshindex][partidobj.index].children[partidobj.groupindex].geometry.boundingSphere.center.clone();
                    }else{
                        partcenter = addedmesharray[partidobj.addedmeshindex][partidobj.index].geometry.boundingSphere.center.clone();
                    }

                }else{

                    if (partidobj.group){
                        var partcenter = mesharray[partidobj.index].children[partidobj.groupindex].geometry.boundingSphere.center.clone();
                    }else if(partidobj.markup) {


                        partcenter = markuparray[partidobj.index].position.clone();
                    }else{
                        partcenter = mesharray[partidobj.index].geometry.boundingSphere.center.clone();
                    }

                }

                var directionPX = new THREE.Vector3(1, 0, 0).normalize();
                var directionNX = new THREE.Vector3(-1, 0, 0).normalize();
                var directionNY = new THREE.Vector3(0, -1, 0).normalize();
                var directionPY = new THREE.Vector3(0, 1, 0).normalize();
                //var raynear = DocObj.getCurrentpage().camera.near;

                var rayfar = DocObj.getCurrentpage().camera.far;

                //const dirNX = 0;
                //const dirPX = 1;
                //const dirNY = 2;
                //const dirPY = 3;

                pingarray.push({direction : directionNX, raycaster : new THREE.Raycaster(partcenter, directionNX, raynear, rayfar), intersects : null, distance : 0}); //negative x
                pingarray.push({direction : directionPX, raycaster : new THREE.Raycaster(partcenter, directionPX, raynear, rayfar ), intersects : null, distance : 0}); //postive x
                pingarray.push({direction : directionNY, raycaster : new THREE.Raycaster(partcenter, directionNY, raynear, rayfar), intersects : null, distance : 0}); //negative y
                pingarray.push({direction : directionPY, raycaster : new THREE.Raycaster(partcenter, directionPY, raynear, rayfar), intersects : null, distance : 0}); //postive y

                var maxdist = 0.0;
                var dirindex = 0;

                for(var pi = 0;pi < pingarray.length;pi++){

                    //pingarray[pi].raycaster.set ( partcenter, pingarray[pi].direction);
                    //pingarray[pi].intersects = pingarray[pi].raycaster.intersectObjects(mesharray, true);

                    if(partidobj.isadded){
                        pingarray[pi].intersects = pingarray[pi].raycaster.intersectObjects(addedmesharray, true);
                    }else{
                        pingarray[pi].intersects = pingarray[pi].raycaster.intersectObjects(mesharray, true);
                    }


                    if (pingarray[pi].intersects.length > 0) {

                        for (var is = 0; is < pingarray[pi].intersects.length; is++) {
                            if (pingarray[pi].intersects[is].object.visible && pingarray[pi].intersects[is].face != null ) {

                                if (partidobj.markup){
                                    pingarray[pi].distance = pingarray[pi].intersects[is].distance;
                                    if(pingarray[pi].distance > maxdist){
                                        maxdist = pingarray[pi].distance;
                                        dirindex = pi;
                                    }

                                    break;

                                }else{
                                    if(!pingarray[pi].intersects[is].object.userData.selected){
                                        pingarray[pi].distance = pingarray[pi].intersects[is].distance;
                                        if(pingarray[pi].distance > maxdist){
                                            maxdist = pingarray[pi].distance;
                                            dirindex = pi;
                                        }

                                        break;

                                    }
                                }
                            }
                        }
                    }
                }

                /*var szdirection = "none";
                if(dirNX == dirindex){
                    szdirection = "negative X";
                }else if (dirPX == dirindex){
                    szdirection = "postive X";
                }else if(dirNY == dirindex){
                    szdirection = "negative Y";
                }else if(dirPY == dirindex){
                    szdirection = "positive Y";
                }*/

                //console.log(pingarray[dirindex].distance, szdirection);

                DocObj.getCurrentpage().camera.position.copy(partcenter);

                DocObj.getCurrentpage().camera.lookAt(partcenter);

                const direction = (new THREE.Vector3())
                .subVectors(DocObj.getCurrentpage().camera.position, partcenter)
                .normalize();

                //.multiply(new THREE.Vector3(0, 1, -1))
                //DocObj.getCurrentpage().camera.position.copy(direction.multiplyScalar(offset).add(partcenter));
                if (pingarray[dirindex].distance >= offset){
                    DocObj.getCurrentpage().camera.position.copy(pingarray[dirindex].direction.multiplyScalar(offset).add(partcenter));
                }else{
                    DocObj.getCurrentpage().camera.position.copy(pingarray[dirindex].direction.multiplyScalar(pingarray[dirindex].distance).add(partcenter));
                }

                DocObj.getCurrentpage().camera.lookAt(partcenter);


                var camerapos = DocObj.getCurrentpage().Vector3DPageObj.checkfloorheight();

                if (camerapos != null){

                    DocObj.getCurrentpage().camera.position.copy(camerapos);
                    //console.log(DocObj.getCurrentpage().camera.position);
                    DocObj.getCurrentpage().camera.lookAt(partcenter);
                    DocObj.getCurrentpage().walkthroughcontrol.setTempWalkHeight(camerapos.z);
                    DocObj.getCurrentpage().camera.lookAt(partcenter);
                    var curfloor = DocObj.getCurrentpage().Vector3DPageObj.checkcurfloor();
                    var floorelevation = DocObj.getCurrentpage().Vector3DPageObj.getfloorElevation(0);




                }



                //DocObj.getCurrentpage().camera.position.copy(origin);

                //DocObj.getCurrentpage().walkthroughcontrol.setPartPos(partcenter, DocObj.getCurrentpage().camera.position);

                //var zdiff = partcenter.z - DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].minz;

                //var camerax = origox - partx; //- (DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].radius * 2);
                //var cameray = origoy - party; //- (DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].radius * 2);
                //var cameraz = origoz - partz;

                //partcenter
                var partPos = new THREE.Vector3(partcenter.x, partcenter.y, partcenter.z);


                //DocObj.getCurrentpage().camera.position.x = camerax;
                //DocObj.getCurrentpage().camera.position.y = cameray - offset;
                //DocObj.getCurrentpage().camera.position.z = cameraz + zoffset;
                //DocObj.getCurrentpage().camera.position.x = partcenter.x;
                //DocObj.getCurrentpage().camera.position.y = partcenter.y;
                //DocObj.getCurrentpage().camera.position.z = partcenter.z;

                //DocObj.getCurrentpage().camera.lookAt(partPos);
                //DocObj.getCurrentpage().camera.lookAt(partcenter);


                var xrot = DocObj.getCurrentpage().camera.rotation.x;
                var yrot = DocObj.getCurrentpage().camera.rotation.y;
                var zrot = DocObj.getCurrentpage().camera.rotation.z;


                //DocObj.getCurrentpage().walkthroughcontrol.firstxyrecieved = false;
                //DocObj.getCurrentpage().walkthroughcontrol.setInitial(-(xrot * (180 / Math.PI)),90,0,0);




                //var partx = -DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].vcentroid.x * modelscale;
                //var party = -DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].vcentroid.y * modelscale;
                //var partz = -DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].vcentroid.z * modelscale;
                //var zdiff = DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].vcentroid.z - DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].minz;



            }

        }

        if (RxCore_GUI_3DWalkthrough != undefined) {
            if(bIsmobile){
                RxCore_GUI_3DWalkthrough.setWalkthroughGUI(true);
                //$('div.wheelPanel').css('visibility', 'visible');

            }
        }
        set_tool('Walkthrough3D', {});
        //tool = new tools['Walkthrough3D']();
        DocObj.curcontrol3D = 'Walkthrough3D';


    }


    function RxCore_MoveTo3DPart(){
        if(docpagNotReady()){
            return;
        }

        if (DocObj.getCurrentpage().usevector3DGLTF){
            new_moveto3dpart();
            return;
        }


        if (DocObj.getCurrentpage().usevector3Dxml) {
            var partid = DocObj.getCurrentpage().Vector3DPageObj.getSelectedPart();
            if (partid !=-1){
                DocObj.getCurrentpage().Vector3DPageObj.scene.updateMatrixWorld();

                var origox = DocObj.getCurrentpage().Vector3DPageObj.scene.position.x;
                var origoy = DocObj.getCurrentpage().Vector3DPageObj.scene.position.y;
                var origoz = DocObj.getCurrentpage().Vector3DPageObj.scene.position.z;
                var modelscale = DocObj.getCurrentpage().Vector3DPageObj.scale;

                //var partx = -(origox - DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].center.x) * modelscale;
                //var party = -(origoy - DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].center.y) * modelscale;
                //var partz = -(origoz - DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].center.z) * modelscale;

                //vcentroid
                //centroid

                var partx = -DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].vcentroid.x * modelscale;
                var party = -DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].vcentroid.y * modelscale;
                var partz = -DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].vcentroid.z * modelscale;
                var zdiff = DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].vcentroid.z - DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].minz;


                var camerax = origox - partx; //- (DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].radius * 2);
                var cameray = origoy - party; //- (DocObj.getCurrentpage().Vector3DPageObj.partlist[partid].radius * 2);
                var cameraz = origoz - partz;
                var partPos = new THREE.Vector3(camerax, cameray, cameraz);



                var format = DocObj.Format.substring(0, 3);
                if (format == 'IFC') {
                    DocObj.getCurrentpage().camera.up.set(0, 0, 1);
                    //DocObj.getCurrentpage().camera.rotation.set(90 * Math.PI / 180, 0, 0);

                } else {
                    //DocObj.getCurrentpage().camera.rotation.set(0, 90 * Math.PI / 180, 0);
                    DocObj.getCurrentpage().camera.up.set(0, 1, 0);
                }

                var floorheight = DocObj.getCurrentpage().Vector3DPageObj.getfloorheight();
                var meterunit = DocObj.getCurrentpage().Vector3DPageObj.getmeterunit();
                var offset = modelscale * meterunit;
                var zoffset = (floorheight - zdiff) * modelscale;

                DocObj.getCurrentpage().camera.position.x = camerax;
                DocObj.getCurrentpage().camera.position.y = cameray - offset;
                DocObj.getCurrentpage().camera.position.z = cameraz + zoffset;
                DocObj.getCurrentpage().camera.lookAt(partPos);

                var xrot = DocObj.getCurrentpage().camera.rotation.x;
                var yrot = DocObj.getCurrentpage().camera.rotation.y;
                var zrot = DocObj.getCurrentpage().camera.rotation.z;


                DocObj.getCurrentpage().walkthroughcontrol.setInitial(-(xrot * (180 / Math.PI)),90,0,0);


            }
        }

        if (RxCore_GUI_3DWalkthrough != undefined) {
            if(bIsmobile){
                RxCore_GUI_3DWalkthrough.setWalkthroughGUI(true);
            }

            //$('div.wheelPanel').css('visibility', 'visible');
        }
        set_tool('Walkthrough3D', {});
        //tool = new tools['Walkthrough3D']();
        DocObj.curcontrol3D = 'Walkthrough3D';
    }

