    function RxCore_CreateServerContent(fileurl, refresh, callback, progressCallBack) {

        bUseCustomrelpath = false;


        if (typeof(fileurl) == 'object'){
            var szquery = "";
            var bopenfile = false;

            if(fileurl.filepath != undefined){
                if(fileurl.filepath != null){
                    szquery = fileurl.filepath;
                    bopenfile = true;
                }
            }

            //CacheID

            var openfileobj = {filename: szquery, displayname : null, auth : null, xrefurl : null, cacheid : null, refresh : false};

            if(refresh){
                openfileobj.refresh = true;
            }


            if(fileurl.mime != undefined){
                if (fileurl.mime != null){

                    //openfileobj.filename = openfileobj.filename + "?x-mimetype=" + fileurl.mime;
                    openfileobj.mime = fileurl.mime;
                    //szquery = szquery + "?x-mimetype=" + fileurl.mime;
                    //"?x-mimetype=" + mime + "&amp;cacheid=" + cacheid
                }
            }

            if(fileurl.cacheid != undefined){
                if (fileurl.cacheid != null){
                    //szquery = szquery + "&amp;cacheid=" + fileurl.cacheid;
                    //openfileobj.filename = openfileobj.filename + "&amp;cacheid=" + fileurl.cacheid;
                    openfileobj.cacheid = fileurl.cacheid;
                    //szquery += fileurl.cacheid;
                }
            }
            if(fileurl.auth != undefined){
                if (fileurl.auth != null){
                    openfileobj.auth = fileurl.auth;
                }
            }

            if(fileurl.xrefurl != undefined){
                if (fileurl.xrefurl != null){
                    openfileobj.xrefurl = fileurl.xrefurl;
                }
            }


            if(fileurl.requestheaders != undefined){
                //console.log(requestheders);
            }



            if(fileurl.displayname != undefined){
                if (fileurl.displayname != null){
                    openfileobj.displayname = fileurl.displayname;
                }
            }

            if(bopenfile){
                //getFile(openfileobj, callback, progressCallBack);

                createContent(openfileobj, callback, progressCallBack);

            }


        }else if (typeof(fileurl) == 'string'){

            openfileobj = {filename: fileurl, displayname : null, refresh : false};

            if(refresh){
                openfileobj.refresh = true;
            }

            createContent(openfileobj, callback, progressCallBack);

        }
    }

    function getFileObject (fileurl){


        var openfileobj = undefined;

        if (typeof(fileurl) == 'object'){

            var szquery = "";
            //var bopenfile = false;

            if(fileurl.filename != undefined){
                if(fileurl.filename != null){
                    szquery = fileurl.filename;
                    //bopenfile = true;
                }
            }

            if(fileurl.filepath != undefined){
                if(fileurl.filepath != null){
                    szquery = fileurl.filepath;
                    //bopenfile = true;
                }
            }

            openfileobj = {filename: szquery, displayname : null, auth : null, xrefurl : null, cacheid : null};



            if(fileurl.mime != undefined){
                if (fileurl.mime != null){
                    //szquery = szquery + "?x-mimetype=" + fileurl.mime;
                    openfileobj.mime = fileurl.mime;
                    //"?x-mimetype=" + mime + "&amp;cacheid=" + cacheid
                }
            }

            if(fileurl.cacheid != undefined){
                if (fileurl.cacheid != null){
                    openfileobj.cacheid = fileurl.cacheid;
                    //szquery = szquery + "&amp;cacheid=" + fileurl.cacheid;
                    //szquery += fileurl.cacheid;
                }
            }

            if(fileurl.auth != undefined){
                if (fileurl.auth != null){
                    openfileobj.auth = fileurl.auth;
                }
            }

            if(fileurl.xrefurl != undefined){
                if (fileurl.xrefurl != null){
                    openfileobj.xrefurl = fileurl.xrefurl;
                }
            }


            if(fileurl.requestheaders != undefined){
                //console.log(requestheders);
            }


            //var openfileobj = {filename: szquery, displayname : null};

            if(fileurl.displayname != undefined){
                if (fileurl.displayname != null){
                    openfileobj.displayname = fileurl.displayname;
                }
            }



        }else if (typeof(fileurl) == 'string'){

            openfileobj = {filename: fileurl, displayname : null};

            //getFile(openfileobj, callback, progressCallBack);
        }

        return openfileobj;
    }

