    function comparedrawcheck(){

        var page1isvector = false;
        var page0isvector = false;

        if(CompareObj.pages[1].VectorPageObj){

            if(CompareObj.pages[1].VectorPageObj.firstdrawcompare){
                CompareObj.pages[1].VectorPageObj.firstdrawcompare = false;
                //CompareObj.pages[0].VectorPageObj.firstdrawcompare = false;
                page1isvector = true;

            }

        }

        if(CompareObj.pages[0].VectorPageObj){
            if (CompareObj.pages[0].VectorPageObj.firstdrawcompare){
                CompareObj.pages[0].VectorPageObj.firstdrawcompare = false;

                page0isvector = true;
            }

        }

        if(page1isvector && page0isvector){
            CompareObj.draw_compare(true);
        }

    }

    function comparecheckFoxit(bready){
        if (doCompare) {

            if(CompareFiles.length != 0){
                for (var ci = 0; ci < CompareFiles.length; ci++){
                    if(CompareFiles[ci].state == 2){
                        CompareFiles[ci].requirefoxit = true;
                        CompareFiles[ci].foxitready = bready;
                    }
                }
            }

        }

    }

    function comparecheckFileLoad(fileName){
        if (doCompare) {

            if(CompareFiles.length != 0){


                for (var ci = 0; ci < CompareFiles.length; ci++){
                    if (fileName == CompareFiles[ci].Name) {
                        CompareFiles[ci].loaded = true;
                    }
                }
            }

        }

    }

    function comparecheck() {
        var compareReady = true;

        if(CompareFiles.length == 0 && !doCompare){
            compareReady = false;
        }

        for (var i = 0; i < CompareFiles.length; i++) {

            if(CompareFiles[i].state == 2 && !CompareFiles[i].loaded){

                if(CompareFiles[i].requirefoxit){
                    if(CompareFiles[i].foxitready){
                        getFile(CompareFiles[i].openobj);
                    }

                }else{
                    getFile(CompareFiles[i].openobj);
                }

            }

            if (compareReady) {
                compareReady = CompareFiles[i].loaded;
            }

        }

        if (compareReady) {
            RxCore_GetOpenFiles();
            doCompare = false;
            CompareFiles = [];
            //RxCore_Compare(true);
            RxCore_CompareEx(true);


        }

    }

