    function RxCore_getDPI() {
        const dpi = {
            x: 96,
            y: 96,
        };

        // For browsers that support deviceXDPI and deviceYDPI (mainly Internet Explorer)
        if (
            window.screen.deviceXDPI !== undefined &&
            window.screen.deviceYDPI !== undefined
        ) {
            dpi.x = window.screen.deviceXDPI;
            dpi.y = window.screen.deviceYDPI;
        } else {
            // For other modern browsers
            const div = document.createElement("div");
            div.style.width = "1in";
            div.style.height = "1in";
            div.style.position = "fixed";
            div.style.left = "-100%";
            document.body.appendChild(div);
            dpi.x = div.offsetWidth;
            dpi.y = div.offsetHeight;
            console.log(div.offsetHeight, div.offsetWidth);
            document.body.removeChild(div);
        }
        return dpi;
    }

