      function RxCore_getCurrentFileInfo() {

        if (docpagNotReady()) {
            return;
        }

        if (!documentopen) {
            return;
        }

        if(DocObj.thumbnails != undefined){

            const thumbnailobj = DocObj.thumbnails[0].thumbnailobj;
            if (thumbnailobj.imageData != null) {
                return {
                    path: DocObj.FileNameSRC,
                    name: DocObj.FileName,
                    date: new Date(),
                    width: thumbnailobj.thumbnail.width,
                    height: thumbnailobj.thumbnail.height,
                    buffer: thumbnailobj.imageData.data
                }
            } else {
                //this.imagectx = this.imagecnv.getContext('2d', { willReadFrequently: true });
                //const thctx = thumbnailobj.thumbnail.getContext('2d', );

                const buffer = thumbnailobj.ctx.getImageData(0, 0, thumbnailobj.thumbnail.width, thumbnailobj.thumbnail.height);

                //const buffer = thumbnailobj.thumbnail.getContext('2d', { willReadFrequently: true }).getImageData(0, 0, thumbnailobj.thumbnail.width, thumbnailobj.thumbnail.height)

                return {
                    path: DocObj.FileNameSRC,
                    name: DocObj.FileName,
                    date: new Date(),
                    width: thumbnailobj.thumbnail.width,
                    height: thumbnailobj.thumbnail.height,
                    buffer: buffer.data
                }
            }

        }else{

                return {
                    path: DocObj.FileNameSRC,
                    name: DocObj.FileName,
                    date: new Date(),
                }

        }




      }

    function RxCore_zoomWithMarkup(markup) {
        return new Promise((resolve, reject) => {
          if (docpagNotReady()) {
            reject()
          }
          if (!documentopen) {
            reject();
          }

          if(DocObj.getCurrentpage().usepdfjs) {
            DocObj.pages[DocObj.currentpage].foxitdirectZoom(markup.documentScale / DocObj.getCurrentpage().getPDFpageScale()).then(() => {
                DocObj.pages[DocObj.currentpage].redrawMarkup()
                setTimeout(() => {
                    resolve()
                }, 50)

            })
          } else {
            DocObj.getCurrentpage().setPagestats(markup.documentScale)
            DocObj.pages[DocObj.currentpage].redrawMarkup()
            setTimeout(() => {
                resolve()
            }, 50)
          }
        })
      }



