    function RxCore_FileInfodialog() {
        if(docpagNotReady()){
            return;
        }

        var ImageWidth = Math.floor(DocObj.getCurrentpage().MainImageWidth / DocObj.getCurrentpage().MainImageScaling);
        var imagewidthunits = getUnitlength(DocObj.getCurrentpage().MainImageWidth);
        var ImageHeight = Math.floor(DocObj.getCurrentpage().MainImageHeight / DocObj.getCurrentpage().MainImageScaling);
        var imageheightunits = getUnitlength(DocObj.getCurrentpage().MainImageHeight);
        var ImageDepth = undefined;
        var ImageDepthunits = undefined;

        if (DocObj.getCurrentpage().usevectorxml && DocObj.getCurrentpage().VectorPageObj) {
            ImageWidth = Math.floor(DocObj.getCurrentpage().VectorPageObj.width);
            imagewidthunits = getUnitlength(ImageWidth);
            ImageHeight = Math.floor(DocObj.getCurrentpage().VectorPageObj.height);
            imageheightunits = getUnitlength(ImageHeight);

        } else if (DocObj.getCurrentpage().usepdfjs) {
            ImageWidth = Math.floor(DocObj.getCurrentpage().pdfpagewidth);
            imagewidthunits = getUnitlength(ImageWidth);
            ImageHeight = Math.floor(DocObj.getCurrentpage().pdfpageheight);
            imageheightunits = getUnitlength(ImageHeight);

        } else if (DocObj.getCurrentpage().usevector3Dxml && DocObj.getCurrentpage().Vector3DPageObj) {

            if(DocObj.getCurrentpage().usevector3DGLTF ){

                ImageWidth = Math.floor(DocObj.getCurrentpage().Vector3DPageObj.curwidth);
                imagewidthunits = getUnitlength(ImageWidth);
                ImageHeight = Math.floor(DocObj.getCurrentpage().Vector3DPageObj.curheight);
                imageheightunits = getUnitlength(ImageHeight);
                ImageDepth = Math.floor(DocObj.getCurrentpage().Vector3DPageObj.curdepth);
                ImageDepthunits = getUnitlength(ImageDepth);

                //vector3Dref.curwidth = width;
                //vector3Dref.curdepth = depth;
                //vector3Dref.curheight = height;

            }else{
                ImageWidth = Math.floor(DocObj.getCurrentpage().Vector3DPageObj.w);
                imagewidthunits = getUnitlength(ImageWidth);
                ImageHeight = Math.floor(DocObj.getCurrentpage().Vector3DPageObj.h);
                imageheightunits = getUnitlength(ImageHeight);

            }
        }

        var OffsetX = DocObj.getCurrentpage().OffsetX;
        var OffsetY = DocObj.getCurrentpage().OffsetY;
        var OriginalScale = DocObj.getCurrentpage().OriginalScale;
        var fileformat = DocObj.Format;
        var fileURL = DocObj.FileName;
        var fileSize = Math.floor(DocObj.FileSizeLow / 1024);
        var fileCompression = DocObj.getCurrentpage().Compression;
        var fileDPI = DocObj.getCurrentpage().DPI;
        var filePages = DocObj.NumPages;



        var FileInformation = {
            FileFormat:fileformat,
            FileName:fileURL,
            FileSize:fileSize,
            Compression:fileCompression,
            DPI:fileDPI,
            Pages:filePages,
            ImageWidth:ImageWidth,
            imagewidthunits:imagewidthunits,
            ImageHeight:ImageHeight,
            imageheightunits:imageheightunits,
            OffsetX:OffsetX,
            OffsetY:OffsetY,
            OriginalScale:OriginalScale,
            XRefs:DocObj.xrefs,
            Fonts:DocObj.fonts,
            Properties : DocObj.documentproperties
        };

        if (ImageDepth){
            FileInformation.ImageDepth = ImageDepth;
        }
        if (ImageDepthunits){
            FileInformation.ImageDepthunits = ImageDepthunits;
        }

        if (DocObj.CadMeasurement != undefined){
            FileInformation.CADMeasurement = DocObj.CadMeasurement;
        }


        if (documentcompare) {
            FileInformation = {
                FileFormat:'Overlay Composite',
                FileName:CompareObj.pages[0].DocRef.FileName + "-" + CompareObj.pages[1].DocRef.FileName,
                FileSize:"-",
                Compression:"-",
                DPI:"-",
                Pages:"-",
                ImageWidth:"-",
                imagewidthunits:imagewidthunits,
                ImageHeight:"-",
                imageheightunits:imageheightunits,
                OffsetX:"-",
                OffsetY:"-",
                OriginalScale:"-"
            };
        }

        if (RxCore_GUI_FileInfo != undefined) {
            RxCore_GUI_FileInfo.setFileInfo(FileInformation);
        }


    }


