    function flipImageData(imagedata){
        var canvsource = document.createElement('canvas');
        var canvtarget = document.createElement('canvas');
        var ctxsource = canvsource.getContext('2d');
        var ctxtarget = canvtarget.getContext('2d');

        canvsource.width = imagedata.width;
        canvsource.height = imagedata.height;

        canvtarget.width = imagedata.width;
        canvtarget.height = imagedata.height;

        //clipboardctx.scale(-1, 1);
        ctxsource.putImageData(imagedata, 0, 0);

        ctxtarget.save();
        ctxtarget.translate(0, canvsource.height);
        ctxtarget.scale(1, -1);


        /*var tx = canvsource.width * 0.5;
        var ty = canvsource.height * 0.5;

        ctxtarget.save();
        ctxtarget.translate(tx, ty);
        ctxtarget.rotate(180 * (Math.PI / 180));
        ctxtarget.translate(-tx, -ty);*/

        ctxtarget.drawImage(canvsource, 0, 0);

        ctxtarget.restore();


        return ctxtarget.getImageData(0, 0, imagedata.width, imagedata.height);

    }


