    function belowlimitExtentEx(zoomscalefactor, mousepoint){
        var belowlimit = true;


        //var pixelRatio = getPixelRatio();

        var pagedim = DocObj.getCurrentpage().getpagedim();


        if (DocObj.getCurrentpage().usepdfjs){

            var wlimit = canvasowidthsize - 60;
            var hlimit = canvasoheightsize - 60;

            //var wlimit = canvasowidth - 60;
            //var hlimit = canvasoheight - 60;


        }else{
            wlimit = canvasowidth - 60;
            hlimit = canvasoheight - 60;

        }



        if((pagedim.w / zoomscalefactor) < wlimit && (pagedim.h / zoomscalefactor) < hlimit){
            belowlimit = false;
            //scalechanged = false;
            //DocObj.getCurrentpage().zoomall();
        }

        var pagerect = DocObj.getCurrentpage().ZoomOutTest(zoomscalefactor, false, mousepoint);


        if (DocObj.getCurrentpage().usepdfjs){
            var heightlimit = canvasoheightsize - (nPanlimit*2);
            var widthlimit = canvasowidthsize - (nPanlimit*2);
            var widthheightratio = (canvasowidthsize / canvasoheightsize);

            //var heightlimit = canvasoheight - (nPanlimit*2);
            //var widthlimit = canvasowidth - (nPanlimit*2);
            //var widthheightratio = (canvasowidth / canvasoheight);


        }else{
            heightlimit = canvasoheight - (nPanlimit*2);
            widthlimit = canvasowidth - (nPanlimit*2);
            widthheightratio = (canvasowidth / canvasoheight);

        }

        //var toplimit = 15;
        var bottomlimit = ((pagerect.y + pagerect.h) <= heightlimit);
        var toplimit = (pagerect.y >= nPanlimit);


        //pixelRatio



        // need to return these to reset the top and bottom positions.scroll|| bottomlimit || toplimit
        if ((pagerect.w / pagerect.h) < widthheightratio){
            if(pagerect.h <= heightlimit){
                belowlimit = false;
            }

        }else{
            if(pagerect.w <= widthlimit){
                belowlimit = false;
            }

        }


        if(!bLimitZoomOut){
            belowlimit = true;
        }

        return belowlimit;
    }

