                            //var leadermarkupAlternative = arrowleader.Entity.Alternative; // getElementsByTagName("Alternative")[0].firstChild.nodeValue;
                            //var leadermarkupID = !arrowleader.getAttribute('ID') ? null : arrowleader.getAttribute('ID');
