    const setimageButton = function (target, source, markupobj){
        const loadpromise = new Promise(function(resolve,reject){


            target.onload = function(ev){

                markupobj.savemetolistDraw();

                img_update();
                drawmarkupAll(cntximg);

                resolve(markupobj);

                /*if (this.status == 200) {
                    resolve(xhr.response);
                }else{
                    reject(this);
                }*/
            };

            target.onerror = function(ev){

                reject();

            };


            target.src = source.src;

        });

        return loadpromise;

    }


