    function RxCore_MarkupLinkRect(bmarker, rect, pagenum, link, padding){
        if(docpagNotReady()){
            return;
        }
        if (readonlymode || documentcompare) {
            return;
        }

        unselelectallmarkup();
        unselecteditmarkupall();

        var type = 3;
        var subtype = 0;
        var fillstyle = 0;

        if(bmarker){
           subtype = 3;
        }

        var rectmarkupobj = new MarkupObject(type, subtype, fillstyle);

       if(bmarker){
            rectmarkupobj.transparency = 30;
            rectmarkupobj.fillcolor = setTransp(rectmarkupobj.fillcolor,rectmarkupobj.transparency);
       }

       rectmarkupobj.scaling = getCurrentPageScale();
       var offset = getCurrentPageOffset();
       rectmarkupobj.xoffset = offset.x;
       rectmarkupobj.yoffset = offset.y;
       rectmarkupobj.pagenumber = pagenum;

       rectmarkupobj.viewname = getCurrentViewName();

       if(rectmarkupobj.viewname != null){
           rectmarkupobj.bfor3D = true;
           rectmarkupobj.pageheight = canvasoheight;
           rectmarkupobj.pagewidth = canvasowidth;
       }



        if (padding){

            rectmarkupobj.x = rect.x - padding.left;
            rectmarkupobj.y = rect.y - padding.top;

            rectmarkupobj.w = rect.w + padding.right;
            rectmarkupobj.h = rect.h + padding.bottom;

        }else{
            rectmarkupobj.x = rect.x;
            rectmarkupobj.y = rect.y;

            rectmarkupobj.w = rect.w;
            rectmarkupobj.h = rect.h;

        }

        rectmarkupobj.savemetolistDraw();

        if(link && link != ""){
            rectmarkupobj.setLink(link, true);
        }

        img_update();
        drawmarkupAll(cntximg);

        rectmarkupobj = null;

    }

