    function startAreaTool(markup) {
        var type = 8;
        var subtype = 0;
        var rotatedrect = markup.rotatedrect;
        var mousePos = {
            x:rotatedrect.x,
            y:rotatedrect.y
        };

        var areamarkupobj = new MarkupObject(type, subtype, fillstyle);
        areamarkupobj.pagenumber = DocObj.getcurPage();
        areamarkupobj.viewname = DocObj.getcur3DView();

        if(areamarkupobj.viewname != null){
            areamarkupobj.bfor3D = true;
            areamarkupobj.pageheight = canvasoheight;
            areamarkupobj.pagewidth = canvasowidth;
        }
        var scaleoffset = {scale : undefined, xoffset : undefined, yoffset : undefined};
        scaleoffset.scale = getCurrentPageScale();
        var offset = getCurrentPageOffset();
        scaleoffset.xoffset = offset.x;
        scaleoffset.yoffset = offset.y;

        areamarkupobj.scaling = scaleoffset.scale;
        areamarkupobj.xoffset = scaleoffset.xoffset;
        areamarkupobj.yoffset = scaleoffset.yoffset;
        areamarkupobj.x = mousePos.x;
        areamarkupobj.y = mousePos.y;
        areamarkupobj.seteditaction(0);
        if(DocObj){
            DocObj.bMarkupchanged = true;
        }
        completeRectToArea(markup, areamarkupobj);
    }

    function completeRectToArea(markup, areamarkupobj) {

        if (areamarkupobj == null){
            return;
        }
        let rotatedrect = markup.rotatedrect;
        let points = [{x: rotatedrect.x, y: rotatedrect.y},
            {x: rotatedrect.x+rotatedrect.w, y: rotatedrect.y},
            {x: rotatedrect.x+rotatedrect.w, y: rotatedrect.y+rotatedrect.h},
            {x: rotatedrect.x, y: rotatedrect.y+rotatedrect.h}];
        areamarkupobj.points = points;
        areamarkupobj.findrectangle();
        if (!bMultimarkupadd) {
            bMarkupcrated = true;
        }

        nMarkupcreated = DocObj.markuplist.length;

        areamarkupobj.savemetolistDraw();
        var bsaved = areamarkupobj.saved;
        areamarkupobj = null;
        img_update();
        drawmarkupAll(cntximg);

        RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[nMarkupcreated], {created : true, modified : false, deleted : false});
    }


