    function addCurrentUser(){


        var buserexist = false;
        var nuserindex = 0;

        for (var ui = 0; ui < Userlist.length; ui ++){
            if(Userlist[ui].Signature == signature){
                buserexist = true;
                nuserindex = ui;
                Userlist[ui].DisplayName = DisplayName;
            }
        }

        if (buserexist){
            //signature = Userlist[nuserindex].Signature;
            //DisplayName = Userlist[nuserindex].DisplayName;
        }else{
            //Userlist[0] = new Users(signature, DisplayName, markuplayer, markupcolor);
            Userlist.push(new Users(signature, DisplayName, markuplayer, markupcolor, false));
            numUsers ++;

        }

        //Userlist[0] = new Users(signature, DisplayName, markuplayer, markupcolor, true);
    }

    function clearUsers(){

        var curUserSign = signature;
        var curDisplayName = DisplayName;
        numUsers = 0;

        for (var ui = 0; ui < Userlist.length; ui ++){
            if(Userlist[ui].default){
                curUserSign = Userlist[ui].Signature;
                curDisplayName = Userlist[ui].DisplayName;
            }
        }

        Userlist = [];

        Userlist.push(new Users(curUserSign, curDisplayName, markuplayer, markupcolor, true));
        numUsers = 1;

    }

    function restoreDefaultUser(){

        var curUserSign = signature;
        var curDisplayName = DisplayName;

        for (var ui = 0; ui < Userlist.length; ui ++){
            if(Userlist[ui].default){
                curUserSign = Userlist[ui].Signature;
                curDisplayName = Userlist[ui].DisplayName;
            }
        }

        signature = curUserSign;
        DisplayName =curDisplayName;

    }

    function RxCore_setUser(sign, disp){




        if(bCanChangeSignature){

            unselelectallmarkup();
            unselecteditmarkupall();

            if (sign != "") {
                signature = sign;
            }else{
                restoreDefaultUser();
                return;
            }
            if (disp != "") {
                DisplayName = disp;
            }
            var buserexist = false;
            var nuserindex = 0;


            for (var ui = 0; ui < Userlist.length; ui ++){
                if(Userlist[ui].Signature == sign){
                    buserexist = true;
                    nuserindex = ui;
                }
            }

            if (buserexist){
                signature = Userlist[nuserindex].Signature;
                DisplayName = Userlist[nuserindex].DisplayName;
            }else{
                //Userlist[0] = new Users(signature, DisplayName, markuplayer, markupcolor);
                Userlist.push(new Users(signature, DisplayName, markuplayer, markupcolor, false));

            }


            if (RxCore_GUI_Users != undefined) {
                RxCore_GUI_Users.setUserlist(Userlist, true);
            }

        }


    }

