    function RxCore_MetricUnit(unit) {


        if(docpagNotReady()){

            if (unit == 'Millimeter') {
                SubmeasureUnit = 1;
            }
            if (unit == 'Centimeter') {
                SubmeasureUnit = 2;
            }
            if (unit == 'Decimeter') {
                SubmeasureUnit = 3;
            }
            if (unit == 'Meter') {
                SubmeasureUnit = 4;
            }
            if (unit == 'Kilometer') {
                SubmeasureUnit = 5;
            }
            if (unit == 'Nautical Miles') {
                SubmeasureUnit = 6;
            }

            switch (SubmeasureUnit) {
                case 1:
                    Unitlabel = "mm";
                    AreaUnitlabel = "mm\u00B2";
                    unitscale = 1;
                    break;
                case 2:
                    Unitlabel = "cm";
                    AreaUnitlabel = "cm\u00B2";
                    unitscale = 10;
                    break;
                case 3:
                    Unitlabel = "dm";
                    AreaUnitlabel = "dm\u00B2";
                    unitscale = 100;
                    break;
                case 4:
                    Unitlabel = "m";
                    AreaUnitlabel = "m\u00B2";
                    unitscale = 1000;
                    break;
                case 5:
                    Unitlabel = "km";
                    AreaUnitlabel = "km\u00B2";
                    unitscale = 1000000;
                    break;
                case 6:
                    Unitlabel = "nmi";
                    AreaUnitlabel = "nmi\u00B2";
                    unitscale = 185200000;
                    break;

            }

            return;
        }else{

            DocObj.getCurrentpage().scaleObject.metricUnit(unit);
            //DocObj.getCurrentpage().metricUnit(unit);

            //RxCore_metricUnit
        }


    }

