    function pentagram( ctx, x, y, radius, rotate, circle ){
        ctx.beginPath();

         for ( var i = 0; i <= 4 * Math.PI; i += ( 4 * Math.PI ) / 5 ) {
             ctx.lineTo( x + radius * Math.cos(i + rotate), y + radius * Math.sin(i + rotate));
         }

         if ( circle ) {
             ctx.moveTo( x + radius, y );
             ctx.arc(x, y, radius, 0, Math.PI * 2, false);
         }

         ctx.stroke();

    }

    function drawCountShape(ctx, x, y, shape, outerRadius, innerRadius, linewidth, fillcolor, strokecolor){

        switch (shape){
            case 0: //star
                drawStar(ctx, x, y, outerRadius, innerRadius, linewidth, fillcolor, strokecolor);
                break;

        }

    }
    function drawCircle(ctx, cx, cy, outerRadius, innerRadius, linewidth, fillcolor, strokecolor){
        ctx.save(); // save the context so we don't mess up others

        ctx.beginPath();

        ctx.arc(cx, cy, outerRadius, 0, 2 * Math.PI);

        ctx.closePath();

        ctx.lineWidth=linewidth;
        ctx.fillStyle = fillcolor;
        ctx.strokeStyle = strokecolor

        ctx.fill();
        ctx.stroke();


        ctx.restore(); // restore context to what it was on entry
    }


    function drawDiamond(ctx, cx, cy, outerRadius, innerRadius, linewidth, fillcolor, strokecolor){
        ctx.save(); // save the context so we don't mess up others
        ctx.beginPath();

        ctx.moveTo(cx, cy - outerRadius);
        ctx.lineTo(cx + outerRadius, cy);

        ctx.lineTo(cx, cy + outerRadius);

        ctx.lineTo(cx - outerRadius, cy);

        ctx.lineTo(cx, cy - outerRadius);

        ctx.closePath();

        ctx.lineWidth=linewidth;
        ctx.fillStyle = fillcolor;
        ctx.strokeStyle = strokecolor

        ctx.fill();
        ctx.stroke();

        ctx.restore(); // restore context to what it was on entry


    }

    function drawTriangle(ctx, cx, cy, outerRadius, innerRadius, linewidth, fillcolor, strokecolor){
        ctx.save(); // save the context so we don't mess up others
        ctx.beginPath();

        ctx.moveTo(cx - outerRadius, cy - outerRadius);
        ctx.lineTo(cx + outerRadius, cy - outerRadius);
        ctx.lineTo(cx, cy + outerRadius); //bottom point
        ctx.lineTo(cx - outerRadius, cy - outerRadius);

        ctx.closePath();

        ctx.lineWidth=linewidth;
        ctx.fillStyle = fillcolor;
        ctx.strokeStyle = strokecolor

        ctx.fill();
        ctx.stroke();

        ctx.restore(); // restore context to what it was on entry


    }

    function drawSquare(ctx, cx, cy, outerRadius, innerRadius, linewidth, fillcolor, strokecolor){
        ctx.save(); // save the context so we don't mess up others
        ctx.beginPath();

        ctx.moveTo(cx - outerRadius, cy - outerRadius);
        ctx.lineTo(cx + outerRadius, cy - outerRadius);
        ctx.lineTo(cx + outerRadius, cy + outerRadius);
        ctx.lineTo(cx - outerRadius, cy + outerRadius);
        ctx.lineTo(cx - outerRadius, cy - outerRadius);

        ctx.closePath();

        ctx.lineWidth=linewidth;
        ctx.fillStyle = fillcolor;
        ctx.strokeStyle = strokecolor

        ctx.fill();
        ctx.stroke();

        ctx.restore(); // restore context to what it was on entry


    }

    function drawDiagonalCross(ctx, cx, cy, outerRadius, innerRadius, linewidth, fillcolor, strokecolor){
        ctx.save(); // save the context so we don't mess up others

        //draw tick
        ctx.beginPath();

        //var halfrad = outerRadius * 0.5;

        ctx.moveTo(cx - outerRadius, cy - outerRadius);

        ctx.lineTo(cx + outerRadius, cy + outerRadius);

        ctx.moveTo(cx - outerRadius, cy + outerRadius );

        ctx.lineTo(cx + outerRadius, cy - outerRadius);

        //ctx.closePath();

        ctx.lineWidth = linewidth;
        ctx.strokeStyle = strokecolor;
        ctx.stroke();

        ctx.restore(); // restore context to what it was on entry
    }


    function drawCross(ctx, cx, cy, outerRadius, innerRadius, linewidth, fillcolor, strokecolor){
        ctx.save(); // save the context so we don't mess up others

        //draw tick
        ctx.beginPath();

        //var halfrad = outerRadius * 0.5;

        ctx.moveTo(cx, cy - outerRadius);

        ctx.lineTo(cx, cy + outerRadius);

        ctx.moveTo(cx - outerRadius, cy);

        ctx.lineTo(cx + outerRadius, cy);

        //ctx.closePath();

        ctx.lineWidth = linewidth;
        ctx.strokeStyle = strokecolor;
        ctx.stroke();

        ctx.restore(); // restore context to what it was on entry
    }

    function drawTick(ctx, cx, cy, outerRadius, innerRadius, linewidth, fillcolor, strokecolor){
        ctx.save(); // save the context so we don't mess up others

        //draw tick
        ctx.beginPath();

        //var halfrad = outerRadius * 0.5;

        ctx.moveTo(cx - innerRadius, cy);

        ctx.lineTo(cx, cy + innerRadius);

        ctx.lineTo(cx + outerRadius, cy - innerRadius);

        //ctx.closePath();

        ctx.lineWidth = linewidth;
        ctx.strokeStyle = strokecolor;
        ctx.stroke();

        ctx.restore(); // restore context to what it was on entry
    }

    function drawStar(ctx, cx, cy, outerRadius, innerRadius, linewidth, fillcolor, strokecolor){
        ctx.save(); // save the context so we don't mess up others

        var spikes = 5;
        var i = 0;
        //var rot= (Math.PI/2) * 3;
        var rot = Math.PI / 2 * 3;
        var x=cx;
        var y=cy;
        var step=Math.PI/spikes;

        ctx.beginPath();

        ctx.moveTo(cx,cy-outerRadius);

        for(i=0;i<spikes;i++){

            x=cx+Math.cos(rot)*outerRadius;
            y=cy+Math.sin(rot)*outerRadius;
            ctx.lineTo(x,y);
            rot+=step;

            x=cx+Math.cos(rot)*innerRadius;
            y=cy+Math.sin(rot)*innerRadius;
            ctx.lineTo(x,y);
            rot+=step;
        }


        ctx.lineTo(cx,cy-outerRadius);
        ctx.closePath();

        ctx.lineWidth=linewidth;
        ctx.fillStyle = fillcolor;
        ctx.strokeStyle = strokecolor;

        ctx.fill();
        ctx.stroke();

        ctx.restore(); // restore context to what it was on entry
    }

    function RxCore_drawRoundedRect(ctx, x, y, width, height, rotation, radius, linewidth, fill, stroke, fillcolor, strokecolor){

        ctx.save(); // save the context so we don't mess up others
        ctx.strokeStyle = strokecolor;
        ctx.fillStyle = fillcolor;
        ctx.lineWidth = linewidth;
        if (rotation != 0) {
            var tx = x + (width / 2);
            var ty = y + (height / 2);
            ctx.translate(tx, ty);
            ctx.rotate(markupobject.rotation);
            ctx.translate(-tx, -ty);
        }
        //alternative 2 start
        ctx.beginPath();
        ctx.moveTo(x + radius, y);
        ctx.lineTo(x + width - radius, y);
        ctx.arcTo(x + width, y, x + width, y + radius, radius);
        ctx.lineTo(x + width, y + height - radius);
        ctx.arcTo(x + width, y + height, x + width - radius, y + height, radius);
        ctx.lineTo(x + radius, y + height);
        ctx.arcTo(x, y + height, x, y + height - radius, radius);
        ctx.lineTo(x, y + radius);
        ctx.arcTo(x, y, x + radius, y, radius);
        //alternative 2 end
        /*ctx.beginPath();

         // draw top and top right corner
         ctx.moveTo(x+radius,y);
         ctx.arcTo(x+width,y,x+width,y+radius,radius);

         // draw right side and bottom right corner
         ctx.arcTo(x+width,y+height,x+width-radius,y+height,radius);

         // draw bottom and bottom left corner
         ctx.arcTo(x,y+height,x,y+height-radius,radius);

         // draw left and top left corner
         ctx.arcTo(x,y,x+radius,y,radius);*/
        if (fill) {
            ctx.fill();
        }
        if (stroke) {
            ctx.stroke();
        }
        ctx.restore(); // restore context to what it was on entry
    }

