    const getThumbcanvas = function(source, thumbwidth){


        const loadpromise = new Promise(function(resolve,reject){

            var target = document.createElement('img');
            var cameracanvas = document.createElement('canvas');

            target.onload = function(ev){

                var image = ev.target || ev.srcElement;

                //var imagewidth = GetImageWidth(image);
                //var imageheight = GetImageHeight(image);

                cameracanvas.width = image.naturalWidth;
                cameracanvas.height = image.naturalHeight;

                //naturalHeight: 874
                //naturalWidth: 1612

                if(cameracanvas.width > 0){
                    var scale = thumbwidth / cameracanvas.width;
                }else{
                    scale = 1;
                }

                var camctx = cameracanvas.getContext('2d');
                camctx.drawImage(target, 0, 0);

                var thumbcnv = downScaleCanvas(cameracanvas, scale);


                source.thumbnail = thumbcnv;
                source.width = thumbcnv.width;
                source.height = thumbcnv.height;


                resolve(source);

            };

            target.onerror = function(ev){

                reject();

            };


            target.src = source.image.src;

            //camobj.image.src

        });

        return loadpromise;



    }

    const setimage = function (target, source){
        const loadpromise = new Promise(function(resolve,reject){


            target.onload = function(ev){

                resolve();

                /*if (this.status == 200) {
                    resolve(xhr.response);
                }else{
                    reject(this);
                }*/
            };

            target.onerror = function(ev){

                reject();

            };


            target.src = source.src;

        });

        return loadpromise;

    }

