    function RxCore_MarkupStamp(Text) {
        if (!documentopen) {
            return;
        }
        if (readonlymode || documentcompare) {
            return;
        }

        unselelectallmarkup();
        unselecteditmarkupall();
        var stamptype = 0;
        //var szstamp = Text;

        for (var i = 0; i < Stamplist.length; i++) {
            if (Stamplist[i] == Text) {
                stamptype = i;
            }
        }


        //width of stamp = 200 pixels.
        //1/3 from top of display.
        //height of stamp = 1/4 of width
        //font size = 62 for main text 31 for small text.
        //height of stamp = height of text + 30 percent

        var stampmarkupobj;
        if (stamptype < Stamplist.length - 2) {
            stampmarkupobj = new MarkupObject(12, stamptype, 0);
            stampmarkupobj.w = 200;
            stampmarkupobj.h = 124;
            var endx = 0;
            var startx = 0;
            var endy = 0;
            var starty = 0;

            stampmarkupobj.scaling = getCurrentPageScale();
            var offset = getCurrentPageOffset();
            stampmarkupobj.xoffset = offset.x;
            stampmarkupobj.yoffset = offset.y;
            startx = offset.x;
            endx = DocObj.getCurrentpage().endx;
            starty = offset.y;
            endy = DocObj.getCurrentpage().endy;


            stampmarkupobj.pagenumber = DocObj.getcurPage();
            stampmarkupobj.viewname = DocObj.getcur3DView();

            if(stampmarkupobj.viewname != null){
                stampmarkupobj.bfor3D = true;
                stampmarkupobj.pageheight = canvasoheight;
                stampmarkupobj.pagewidth = canvasowidth;

            }

            stampmarkupobj.seteditaction(0);


            stampmarkupobj.textheight = 32;
            stampmarkupobj.stampsmalltheight = 16;

            stampmarkupobj.x = (startx + ((endx - startx) / 2)) - (stampmarkupobj.w / 2);
            stampmarkupobj.y = (starty + ((endy - starty) / 2)) - (stampmarkupobj.h / 2);


            if (!bMultimarkupadd) {
                bMarkupcrated = true;
                //ft 08.08.2018 changed from separate index to direct array length
                //nMarkupcreated = DocObj.nummarkups;

            }

            nMarkupcreated = DocObj.markuplist.length;

            stampmarkupobj.drawme(context);
            stampmarkupobj.savemetolistDraw();


        } else {
            stampmarkupobj = new MarkupObject(9, 0, 0);
            if (DocObj.getCurrentpage().usevectorxml) {
                stampmarkupobj.scaling = DocObj.getCurrentpage().dscalevector;
                stampmarkupobj.xoffset = DocObj.getCurrentpage().dxvector;
                stampmarkupobj.yoffset = DocObj.getCurrentpage().dyvector;
                stampmarkupobj.x = (DocObj.getCurrentpage().dxvector + (DocObj.getCurrentpage().endx / 2)) - ntexwtsize; // - (stampmarkupobj.w / 2);
                stampmarkupobj.y = (DocObj.getCurrentpage().dyvector + (DocObj.getCurrentpage().endy / 2)) + (stampmarkupobj.textheight / 2);


            } else if (DocObj.getCurrentpage().usepdfjs) {
                stampmarkupobj.scaling = (DocObj.getCurrentpage().curpagescale * DocObj.getCurrentpage().dscalepdf);
                stampmarkupobj.xoffset = DocObj.getCurrentpage().dxpdf;
                stampmarkupobj.yoffset = DocObj.getCurrentpage().dypdf;
                stampmarkupobj.x = (DocObj.getCurrentpage().dxpdf + (DocObj.getCurrentpage().endx / 2)) - ntexwtsize; // - (stampmarkupobj.w / 2);
                stampmarkupobj.y = (DocObj.getCurrentpage().dypdf + (DocObj.getCurrentpage().endy / 2)) + (stampmarkupobj.textheight / 2);


            } else {
                stampmarkupobj.scaling = DocObj.getCurrentpage().dscale;
                stampmarkupobj.xoffset = DocObj.getCurrentpage().dx;
                stampmarkupobj.yoffset = DocObj.getCurrentpage().dy;
                stampmarkupobj.x = (DocObj.getCurrentpage().dx + (DocObj.getCurrentpage().endx / 2)) - ntexwtsize; // - (stampmarkupobj.w / 2);
                stampmarkupobj.y = (DocObj.getCurrentpage().dy + (DocObj.getCurrentpage().endy / 2)) + (stampmarkupobj.textheight / 2);


            }
            stampmarkupobj.pagenumber = DocObj.getcurPage();
            stampmarkupobj.viewname = DocObj.getcur3DView();

            if(stampmarkupobj.viewname != null){
                stampmarkupobj.bfor3D = true;
                stampmarkupobj.pageheight = canvasoheight;
                stampmarkupobj.pagewidth = canvasowidth;
            }

            stampmarkupobj.seteditaction(0);
            stampmarkupobj.textheight = 32;
            var ntexwtsize = 100;
            if (Stamplist[stamptype] == 'Date') {
                stampmarkupobj.text = stampmarkupobj.GetDateTime(false);
                ntexwtsize = 90;
            }

            if (Stamplist[stamptype] == 'User Name') {
                stampmarkupobj.text = GetDisplayName(stampmarkupobj.signature);
            }

            //stampmarkupobj.text = Stamplist[stamptype];

            //stampmarkupobj.w = 200;
            //stampmarkupobj.h = 124;

            //stampmarkupobj.x = (canvas.width / 2)-ntexwtsize;// - (stampmarkupobj.w / 2);
            //stampmarkupobj.y = (canvas.height / 2) + (stampmarkupobj.textheight / 2);

            //stampmarkupobj.stampsmalltheight = 16;


            stampmarkupobj.drawme(context);
            if (!bMultimarkupadd) {

                bMarkupcrated = true;
                //ft 08.08.2018 changed from separate index to direct array length
                //nMarkupcreated = DocObj.nummarkups;

            }
            nMarkupcreated = DocObj.markuplist.length;

            stampmarkupobj.savemetolistDraw();

        }
        img_update();
        if(DocObj){
            DocObj.bMarkupchanged = true;
        }


        stampmarkupobj = null;


        if(bAlwaysMarkupCallback){
            if (RxCore_GUI_Markup != undefined) {
                RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[nMarkupcreated], {created : true, modified : false, deleted : false, multi : bMultimarkupadd});
            }

        }else{

            if (!bMultimarkupadd) {

                //need to move to connection object.
                //markupcreated();
                if (RxCore_GUI_Markup != undefined) {

                    RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[nMarkupcreated], {created : true, modified : false, deleted : false});
                }

            }

        }



    }

