    function RxCore_togglebackground(changekeepvectorcolor) {
        if(docpagNotReady()){
            return;
        }


        if (DocObj.getCurrentpage().usepdfjs) {
            DocObj.backgroundColor = "#FFFFFF";
        } else {
            if(bCustomColor){
                if (DocObj.backgroundColor == backgroundCustomColor) {
                    DocObj.backgroundColor = "#A0A0A0";
                }else if (DocObj.backgroundColor == "#A0A0A0") {
                    DocObj.backgroundColor = "#FFFFFF";
                } else if (DocObj.backgroundColor == "#FFFFFF") {

                    DocObj.backgroundColor = "#000000";

                } else if (DocObj.backgroundColor == "#000000") {
                    DocObj.backgroundColor = backgroundCustomColor;

                    if(changekeepvectorcolor){
                        bKeepVectorColor = !bKeepVectorColor;
                    }


                }
            }else{
                if (DocObj.backgroundColor == "#A0A0A0") {
                    DocObj.backgroundColor = "#FFFFFF";
                } else if (DocObj.backgroundColor == "#FFFFFF") {

                    DocObj.backgroundColor = "#000000";

                } else if (DocObj.backgroundColor == "#000000") {
                    DocObj.backgroundColor = "#A0A0A0";

                    if(changekeepvectorcolor){
                        bKeepVectorColor = !bKeepVectorColor;
                    }


                }

            }

        }
        if (DocObj.getCurrentpage().usevectorxml) {

            if (DocObj.backgroundColor == "#FFFFFF" || DocObj.backgroundColor == "#000000") {
                DocObj.getCurrentpage().invert_images(DocObj.backgroundColor);
            }

            DocObj.getCurrentpage().draw_vector(true);
            DocObj.refreshBirdsEye();
            DocObj.renderBirdsEye();

        }
        drawmarkupAll(cntximg);
    }

    function resetCursor(){
        //set for all canvas elements

        //document.body.style.cursor = 'default';

        canvaso.style.cursor = 'default';
        renderer.domElement.style.cursor = 'default';
        canvimg.style.cursor = 'default';
        canvas.style.cursor = 'default';

    }



    function setCursor(cursor){

        canvaso.style.cursor = cursor;
        renderer.domElement.style.cursor = cursor;
        canvimg.style.cursor = cursor;
        canvas.style.cursor = cursor;

    }


    function set3DToolType(selected, type, params) {
        if(docpagNotReady()){
            return;
        }

        if (DocObj.getCurrentpage().usevector3Dxml) {
            //unselelectallmarkup();

            var has3dSelect = ((DocObj.curcontrol3D == 'Walkthrough3D') || (DocObj.curcontrol3D == 'orbitControl'));



            if(has3dSelect && type == 'select3d'){

                if(tool.name != 'Walkthrough3D' && tool.name != 'orbitControl'){

                    if (params == null){
                        set_tool(DocObj.curcontrol3D, {});
                    }else{
                        set_tool(DocObj.curcontrol3D, params);
                    }

                }

                if(!selected){
                    //unselect all meshes.
                    DocObj.getCurrentpage().unselect3DBlockAll();
                }

                if (tool){
                    tool.setSelect(selected, params.p1);
                }


            }else{
                var toolType = (selected) ? type : DocObj.curcontrol3D;

                resetCursor();

                if(toolType != 'select3d'){
                    //unselect all meshes.
                    DocObj.getCurrentpage().unselect3DBlockAll();
                }


                unselelectallmarkup();
                unselecteditmarkupall();
                DocObj.getCurrentpage().unSelect3DmarkupAll();

                if(toolType == 'markupedit'){
                    params = {p1 : false};
                }

                //tool = new tools[toolType]();
                if (params == null){
                    set_tool(toolType, {});
                }else{
                    set_tool(toolType, params);
                }

            }


        }
    }

