    function RxCore_getinitPDFScale(pwidth, pheight){

                var yscale = canvasoheight / (pheight);
                var xscale = canvasowidth / (pwidth);
                var dscale = Math.min(xscale, yscale);

                return dscale;
    }



    function drawcanvasext (cnv, transscale, xoffset, yoffset){
        if(cnv){
            imagewidth = cnv.width;
            imageheight = cnv.height;

            var dscale = 1.0;

            //imagewidth = splashimage.naturalWidth;
            //imageheight = splashimage.naturalHeight;


            //calculate zoom to extent initial scaling and offset
            //zoom to fit

            var dx = (canvasowidth - (imagewidth * dscale * transscale)) / 2;
            //var dy = (canvasoheight - (imageheight * dscale)) / 2;
            //var dx = 0.0;
            var dy = 0.0;

            if (!documentopen) {

                var localdx = 0.0;
                var localdy = 0.0;
                var localdscale = 1.0;


                localdx = dx + xoffset;
                localdy = dy + yoffset;
                localdscale = dscale;
                //contexto.save();
                //contexto.transform(transscale,0,0,transscale,0,0);
                if (transscale == 1){
                    contexto.drawImage(cnv, localdx, localdy, imagewidth * transscale, imageheight * transscale);
                }else{
                    var scaledcnv = downScaleCanvas(cnv, transscale);
                    contexto.drawImage(scaledcnv, localdx, localdy, imagewidth * transscale, imageheight * transscale);

                    scaledcnv = null;
                }



                //contexto.restore();


            }

        }
    }

