    function RxCore_FoxitAnnotlist(annotationlist) {
        if (docpagNotReady()) {
          return;
        }

        if(!convertPDFAnnots){
          return;
        }

        if (DocObj) {
          DocObj.setFoxitAnnotlist(annotationlist);

          if (RxCore_GUI_FoxitAnnotlist != undefined) {
            let annotList = [];
            let ct = 0;
            let annotreplies = [];

            for (let item of annotationlist) {
              //console.log(item);
              let annotItem;
              const jsonInfo = item.exportToJSON();
              //console.log(jsonInfo);
              const annotRect = item.getPage().getDeviceRect(item.getRect(),PixelToPoint);
              //console.log(annotRect);


              let txtcontent = jsonInfo.contents.replace("\r\r", '\n\n');
              txtcontent = txtcontent.replace("\r", '\n');


              switch (item.getType()) {
                case "freetext":


                if(jsonInfo.intent == "FreeTextCallout"){

                    if(item.info.calloutLinePoints){

                      const startPointtxt = item.info.calloutLinePoints[0];
                      const endPointtxt = item.info.calloutLinePoints[2];

                      var startpointarrayclout = [startPointtxt.x, startPointtxt.y];
                      var endpointarrayclout = [endPointtxt.x, endPointtxt.y];

                      const deviceStartPointclout = item.getPage().getDevicePoint(startpointarrayclout,PixelToPoint);
                      const deviceEndPointclout = item.getPage().getDevicePoint(endpointarrayclout,PixelToPoint);

                      var calloutarrow = new MarkupObject(6, 6, 0);

                      calloutarrow.linewidth = jsonInfo.width;
                      calloutarrow.arrowlength = 10 + calloutarrow.linewidth;
                      calloutarrow.x = deviceStartPointclout[0];
                      calloutarrow.y = deviceStartPointclout[1];
                      calloutarrow.w = deviceEndPointclout[0];
                      calloutarrow.h = deviceEndPointclout[1];
                      calloutarrow.pagenumber = jsonInfo.page;
                      calloutarrow.signature = Object.keys(jsonInfo).includes("title")  ? jsonInfo.title : null;

                      calloutarrow.pdfannotref = ct;
                      calloutarrow.pdfannot = true;

                      if(proxyPDFAnnots){
                        calloutarrow.pdfannotproxy = true;
                    }


                      calloutarrow.savemetolistLoad(DocObj);

                      if(!calloutarrow.pdfannotproxy){
                        item.getPage().removeAnnotById(item.getUniqueID());
                      }






                    }


                    if(item.info.innerRect){
                      const annotRectinner = item.getPage().getDeviceRect(item.info.innerRect,PixelToPoint);



                      annotItem = CreateTextRectdirect(
                        annotRectinner.left,
                        annotRectinner.top,
                        annotRectinner.right - annotRectinner.left,
                        annotRectinner.bottom - annotRectinner.top,
                        calloutarrow,
                        txtcontent
                      );

                      annotItem.textcolor = jsonInfo.fontColor;
                      annotItem.fillcolor = "rgba(255,255,255, 0)";
                      annotItem.font = new FontObject(item.info.fontName, (item.info.defaultAppearance.textSize * PixelToPoint));

                    }


                  }else{
                    annotItem = new MarkupObject(9, 1, 0);
                    annotItem.text = txtcontent;
                    annotItem.textcolor = jsonInfo.fontColor;
                    annotItem.strokecolor = jsonInfo.color;
                    annotItem.fillcolor = "rgba(255,255,255, 0)";
                    annotItem.font = new FontObject(item.info.fontName, (item.info.defaultAppearance.textSize * PixelToPoint));

                    annotItem.x = annotRect.left;
                    annotItem.y = annotRect.top;
                    annotItem.w = annotRect.right - annotRect.left;
                    annotItem.h = annotRect.bottom - annotRect.top;

                  }



                  break;

                case "text":
                  if(jsonInfo.inreplyto == undefined){
                    annotItem = new MarkupObject(10, 0, 0);
                    annotItem.text = txtcontent;

                    annotItem.x = annotRect.left;
                    annotItem.y = annotRect.top;

                    annotItem.w = noteimage.width;
                    annotItem.h = noteimage.height;
                  }else{
                    annotreplies.push({inreplyto : jsonInfo.inreplyto, text : txtcontent});
                  }

                  break;

                case "line":
                  const startPoint = item.getStartPoint();
                  const endPoint = item.getEndPoint();
                  var startpointarray = [startPoint.x, startPoint.y];
                  var endpointarray = [endPoint.x, endPoint.y];

                  const deviceStartPoint = item.getPage().getDevicePoint(startpointarray,PixelToPoint);
                  const deviceEndPoint = item.getPage().getDevicePoint(endpointarray,PixelToPoint);


                  if(jsonInfo.intent == "LineArrow"){

                    var subtype = 0;


                    if((jsonInfo.tail == "OpenArrow") && (jsonInfo.head == "OpenArrow")){
                      subtype = 2;
                    }

                    annotItem = new MarkupObject(6, subtype, 0);
                    annotItem.linewidth = jsonInfo.width;
                    annotItem.arrowlength = 10 + annotItem.linewidth;
                    annotItem.x = deviceStartPoint[0];
                    annotItem.y = deviceStartPoint[1];
                    annotItem.w = deviceEndPoint[0];
                    annotItem.h = deviceEndPoint[1];

                    annotItem.strokecolor = jsonInfo.color;

                  } else if(jsonInfo.intent == "LineDimension") {
                    annotItem = new MarkupObject(7, 0, 0);

                    annotItem.x = deviceStartPoint[0];
                    annotItem.y = deviceStartPoint[1];
                    annotItem.w = deviceEndPoint[0];
                    annotItem.h = deviceEndPoint[1];

                    annotItem.strokecolor = jsonInfo.color;

                    DocObj.scalesOptions = [{value: jsonInfo.measureRatio, label: jsonInfo.measureRatio}];

                  } else{
                    annotItem = new MarkupObject(1, 1, 0);

                    annotItem.addpoint(deviceStartPoint[0], deviceStartPoint[1]);
                    annotItem.addpoint(deviceEndPoint[0], deviceEndPoint[1]);

                    annotItem.strokecolor = jsonInfo.color;

                  }

                  break;
                case "circle":
                  annotItem = new MarkupObject(4, 0, 0);

                  annotItem.x = annotRect.left;
                  annotItem.y = annotRect.top;
                  annotItem.w = annotRect.right - annotRect.left;
                  annotItem.h = annotRect.bottom - annotRect.top;

                  annotItem.strokecolor = jsonInfo.color;


                  break;
                case "square":

                //console.log(jsonInfo);
                //break;
                  if(jsonInfo.intent != "SquareImage"){
                    annotItem = new MarkupObject(3, 0, 0);

                    annotItem.x = annotRect.left;
                    annotItem.y = annotRect.top;
                    annotItem.w = annotRect.right - annotRect.left;
                    annotItem.h = annotRect.bottom - annotRect.top;

                    if(jsonInfo.style == "solid" && jsonInfo.interiorColor){
                      //annotItem.fillcolor = jsonInfo.interior-color;
                      annotItem.fillcolor = convertHex(jsonInfo.interiorColor, jsonInfo.opacity * 80);
                      annotItem.alternative = 1;

                    }


                    annotItem.strokecolor = jsonInfo.color;

                    //if(jsonInfo.solid)

                  }else{
                    annotItem = new MarkupObject(3, 0, 0);

                    annotItem.x = annotRect.left;
                    annotItem.y = annotRect.top;
                    annotItem.w = annotRect.right - annotRect.left;
                    annotItem.h = annotRect.bottom - annotRect.top;

                    annotItem.strokecolor = jsonInfo.color;
                    annotItem.pdfannotproxy = true;
                    annotItem.pdfannotproxyType = "image";

                  }

                 break;

                case "ink":
                  annotItem = new MarkupObject(0, 0, 0);
                  const inkList = item.getInkList();
                  for(let index = 0 ; index < inkList.length ; ++ index) {
                    const point = inkList[index];
                    const pointarray = [point.x, point.y];
                    const devicePoint = item.getPage().getDevicePoint(pointarray, PixelToPoint);
                    annotItem.addpoint(devicePoint[0], devicePoint[1]);
                  }
                  annotItem.addline();
                  console.log(annotItem.pointlist);

                  annotItem.strokecolor = jsonInfo.color;

                  break;

                case "polygon":
                  if(jsonInfo.intent === "PolygonDimension") {
                    annotItem = new MarkupObject(8, 0, 0);
                  }
                  else if(jsonInfo.style === "solid") {

                    if(jsonInfo.interiorColor){
                      annotItem = new MarkupObject(1, 2, 1);
                      annotItem.fillcolor = jsonInfo.interiorColor;
                    }else{
                      annotItem = new MarkupObject(1, 2, 0);
                      annotItem.fillcolor = jsonInfo.interiorColor;

                    }





                  } else if(jsonInfo.style === "cloudy") {
                    annotItem = new MarkupObject(1, 7, 0);

                  }

                  const vertexes = item.getVertexes();
                  for(let index = 0 ; index < vertexes.length ; ++ index) {
                    const point = vertexes[index];
                    const pointarray = [point.x, point.y];
                    const devicePoint = item.getPage().getDevicePoint(pointarray, PixelToPoint);
                    annotItem.addpoint(devicePoint[0], devicePoint[1]);
                  }

                  annotItem.strokecolor = jsonInfo.color;

                  break;

                case "polyline":
                  if(jsonInfo.intent === "PolyLineDimension") {
                    annotItem = new MarkupObject(1, 3, 0);
                  } else {
                    annotItem = new MarkupObject(1, 1, 0);
                  }
                  const vertices = item.getVertexes();
                    for(let index = 0 ; index < vertices.length ; ++ index) {
                      const point = vertices[index];
                      const pointarray = [point.x, point.y];
                      const devicePoint = item.getPage().getDevicePoint(pointarray, PixelToPoint);
                      annotItem.addpoint(devicePoint[0], devicePoint[1]);
                    }

                    annotItem.strokecolor = jsonInfo.color;

                  break;

                case "stamp":


                    annotItem = new MarkupObject(3, 0, 0);

                    annotItem.x = annotRect.left;
                    annotItem.y = annotRect.top;
                    annotItem.w = annotRect.right - annotRect.left;
                    annotItem.h = annotRect.bottom - annotRect.top;

                    annotItem.strokecolor = jsonInfo.color;
                    annotItem.pdfannotproxy = true;
                    annotItem.pdfannotproxyType = "stamp";


                  //annotItem = new MarkupObject(11, 1, 0);

                  //var imgbuf = item.getImage('buffer');

                  //const offscreen = new OffscreenCanvas(256, 256);

                  //DocObj.foxitdoc.getStampImage(item);


                  /*const imageBuf = item.getImage("buffer");
                  const blob = new Blob([imageBuf], {type: 'image/png'});
                  const url = URL.createObjectURL(blob);
                  console.log(url);
                  annotItem.imagehref = url;*/
                  break;
                case "strikeout" :

                    annotItem = new MarkupObject(3, 0, 0);

                    annotItem.x = annotRect.left;
                    annotItem.y = annotRect.top;
                    annotItem.w = annotRect.right - annotRect.left;
                    annotItem.h = annotRect.bottom - annotRect.top;

                    annotItem.strokecolor = jsonInfo.color;
                    annotItem.pdfannotproxy = true;
                    annotItem.pdfannotproxyType = "strikeout";


                    break;
                case "highlight" :
                    annotItem = new MarkupObject(3, 0, 0);

                    annotItem.x = annotRect.left;
                    annotItem.y = annotRect.top;
                    annotItem.w = annotRect.right - annotRect.left;
                    annotItem.h = annotRect.bottom - annotRect.top;

                    annotItem.strokecolor = jsonInfo.color;
                    annotItem.pdfannotproxy = true;
                    annotItem.pdfannotproxyType = "highlight";


                    break;
                case "underline" :

                    annotItem = new MarkupObject(3, 0, 0);

                    annotItem.x = annotRect.left;
                    annotItem.y = annotRect.top;
                    annotItem.w = annotRect.right - annotRect.left;
                    annotItem.h = annotRect.bottom - annotRect.top;

                    annotItem.strokecolor = jsonInfo.color;
                    annotItem.pdfannotproxy = true;
                    annotItem.pdfannotproxyType = "underline";

                    break;

              }


              if(annotItem != undefined){
                annotItem.pdfannotref = ct;
                annotItem.pdfannot = true;
                annotItem.title = Object.keys(jsonInfo).includes("title")  ? jsonInfo.title : null;

                if(!GetUserexist(annotItem.title)){
                  Userlist.push(new Users(annotItem.title, annotItem.title, markuplayer, markupcolor, false));
                }

                annotItem.signature = Object.keys(jsonInfo).includes("title")  ? jsonInfo.title : null;
                annotItem.timestamp = item.info.creationTimestamp;
                annotItem.uniqueID = item.getUniqueID();
                annotItem.pagenumber = jsonInfo.page;

                annotItem.linewidth = jsonInfo.width;

                if(jsonInfo.style == "solid"){
                  annotItem.linestyle = 0;
                }
                if(jsonInfo.style == "dashed"){
                  annotItem.linestyle = 1;
                  annotItem.linewidth = 1;
                }

                if(proxyPDFAnnots){
                    annotItem.pdfannotproxy = true;
                }

                annotItem.color = jsonInfo.color;

                annotItem.savemetolistLoad(DocObj);

                if(!annotItem.pdfannotproxy){
                    item.getPage().removeAnnotById(item.getUniqueID());
                }



              }
              ct++;
            }

            for (let repl of annotreplies) {
              var markup = RxCore_getmarkupobjByGUID(repl.inreplyto);
              if(markup) {
                markup.AddCommentInternal(markup.comments.length, markup.signature, repl.text);
              }
            }
          }
        }
    }
