                                        bPlaneY = (addedintersects[i][j].point.y > -DocObj.getCurrentpage().Vector3DPageObj.globalPlaneY.constant);
                                        bPlaneZ = (addedintersects[i][j].point.z < DocObj.getCurrentpage().Vector3DPageObj.globalPlaneZ.constant);
