            tools.interactiveStamp = function(params) {
                var tool = this;
                var canvasLeft = canvas.offsetLeft;
                var canvasTop = canvas.offsetTop;
                var startOffsetX = 0;
                var startOffsetY = 0;
                var imagemarkupobj;
                var curmarkup = DocObj.markuplist.length;

                this.name = 'interactiveStamp';
                this.anglelengthsupport = false;
                this.refreshSupport = false;
                this.started = false;

                if (params.p1 !== undefined) {
                    this.subtype = params.p1;
                } else {
                    this.subtype = 21;
                }

                setCursor(getMarkupCursor('interactiveStamp'));

                this.dragover = function(ev) {
                    ev.preventDefault();
                };

                this.drop = function(ev) {
                    //debugger
                    ev.preventDefault();

                    var mousePos = getMousePos(canvas, ev);
                    imagemarkupobj = new MarkupObject(11, tool.subtype, 0);

                    imagemarkupobj.scaling = getCurrentPageScale();
                    var offset = getCurrentPageOffset();
                    imagemarkupobj.xoffset = offset.x;
                    imagemarkupobj.yoffset = offset.y;

                    imagemarkupobj.pagenumber = DocObj.getcurPage();
                    imagemarkupobj.viewname = DocObj.getcur3DView();

                    if (imagemarkupobj.viewname != null) {
                        imagemarkupobj.bfor3D = true;
                        imagemarkupobj.pageheight = canvasoheight;
                        imagemarkupobj.pagewidth = canvasowidth;
                    }

                    imagemarkupobj.seteditaction(0);
                    var bWithin = MousePosdrwext(mousePos);

                    var dropdata = JSON.parse(ev.dataTransfer.getData("Text"));
                    var rect = { x: mousePos.x - (dropdata.width / 2), y: mousePos.y - (dropdata.height / 2), w: dropdata.width, h: dropdata.height };
                    bWithin = MousePosdrwextRect(rect);

                    if (bWithin || !bLimMarkupExtent) {
                        imagemarkupobj.x = mousePos.x - (dropdata.width / 2);
                        imagemarkupobj.y = mousePos.y - (dropdata.height / 2);
                        imagemarkupobj.w = dropdata.width;
                        imagemarkupobj.h = dropdata.height;

                        var createimage = new Image();
                        createimage.src = dropdata.src;
                        imagemarkupobj.image = createimage;
                        imagemarkupobj.imageloaded = true;
                        context.clearRect(0, 0, canvas.width, canvas.height);

                        if (!bMultimarkupadd) {
                            bMarkupcrated = true;
                            nMarkupcreated = DocObj.markuplist.length;
                        }

                        nMarkupcreated = DocObj.markuplist.length;
                        imagemarkupobj.savemetolistDraw();

                        // Insert the SVG into the iframe for editing
                        var iframe = document.getElementById('foxitframe');
                        var iframeDoc = iframe.contentDocument || iframe.contentWindow.document;
                        iframeDoc.open();
                        iframeDoc.write('<html><body>' + createimage.outerHTML + '</body></html>');
                        iframeDoc.close();

                        // Make the SVG editable inside the iframe
                        var svgElement = iframeDoc.querySelector('svg');
                        if (svgElement) {
                            svgElement.setAttribute('contenteditable', 'true');
                        }
                    }

                    if (!bWithin) {
                        if (Rxcore_GUI_SymbolAddFailed !== undefined) {
                            Rxcore_GUI_SymbolAddFailed.markupSaved();
                        }
                    }

                    img_update();
                    imagemarkupobj = null;

                    if (bAlwaysMarkupCallback && bWithin) {
                        if (RxCore_GUI_Markup !== undefined) {
                            var operation = { created: true, modified: false, deleted: false, multi: bMultimarkupadd };
                            RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[nMarkupcreated], operation);
                        }
                    } else {
                        if (!bMultimarkupadd && bWithin) {
                            if (RxCore_GUI_Markup !== undefined) {
                                var operation = { created: true, modified: false, deleted: false };
                                RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[nMarkupcreated], operation);
                            }
                        }
                    }
                };

                this.mousedown = function(ev) {
                    // Custom logic for mousedown
                };
            };


