                this.name = 'measure';
                this.anglelengthsupport = false;
                this.refreshSupport = false;

                this.startx = 0;
                this.starty = 0;
                this.orgscale = 1.0;
                this.orgdx = 0.0;
                this.orgdy = 0.0;
