                //this.curmousepos = {x:0,y:0};
                this.curmousepos = {x:0,y:0,xus:0,yus:0};


                setCursor(getMarkupCursor('measure'));


                this.scrollhandling = function (movey) {
                    if (!documentopen || DocObj.getCurrentpage().usevector3Dxml) {
                        return;
                    }

                    if (movey < 0) {


                        //if (DocObj.getCurrentpage().usepdfjs && DocObj.pages.length > 1) {
                        if (DocObj.getCurrentpage().usepdfjs && DocObj.pages.length > 1 && !enableZoomOnScrollMultipage) {
                            //DocObj.getCurrentpage().pan_update(0,-movey);
                            if (DocObj.currentpage == DocObj.NumPages - 1) {
                                /*if (DocObj.getCurrentpage().endy <= canvas.height) {
                                    movey = 0;
                                }*/
                            }
                            DocObj.getCurrentpage().pan_update(0, -movey);



                        } else {

                            if(belowlimitExtentEx(1.1, tool.curmousepos)){
                                DocObj.getCurrentpage().ZoomOut(1.1, false, false, tool.curmousepos);

                                if(tool.started){
                                    tool.setdimoffset(false);
                                }

                            }else{
                                RxCore_foxitForceRedraw();
                            }



                            if(tool.started){

                                //tool.setdimoffset(false);

                                /*dimensionmarkupobj.w = tool.curmousepos.x;
                                dimensionmarkupobj.h = tool.curmousepos.y;

                                if(type == 3){
                                    //dimensionmarkupobj.w = Math.abs(tool.curmousepos.x - dimensionmarkupobj.x);
                                    //dimensionmarkupobj.h = Math.abs(tool.curmousepos.y - dimensionmarkupobj.y);

                                    dimensionmarkupobj.w = dimensionmarkupobj.w - dimensionmarkupobj.x;
                                    dimensionmarkupobj.h = dimensionmarkupobj.h - dimensionmarkupobj.y;

                                }*/

                                //tool.mousemove();

                                tool.drawDimension({x : tool.curmousepos.x, y : tool.curmousepos.y});


                                if(dimensionmarkupobj != null){
                                    context.clearRect(0, 0, canvas.width, canvas.height);
                                    dimensionmarkupobj.drawme(context);
                                }

                            }



                        }


                    } else {

                        //if (DocObj.getCurrentpage().usepdfjs && DocObj.pages.length > 1) {
                        if (DocObj.getCurrentpage().usepdfjs && DocObj.pages.length > 1 && !enableZoomOnScrollMultipage) {

                            if (DocObj.currentpage == 0) {
                                /*if (DocObj.getCurrentpage().starty >= 0) {
                                    movey = 0;
                                }*/

                            }
                            DocObj.getCurrentpage().pan_update(0, -movey);


                        } else {


                            DocObj.getCurrentpage().ZoomIn(1.1, false, false, tool.curmousepos);


                            if(tool.started){

                                tool.setdimoffset(false);

                                /*dimensionmarkupobj.w = tool.curmousepos.x;
                                dimensionmarkupobj.h = tool.curmousepos.y;


                                if(type == 3){
                                    //dimensionmarkupobj.w = Math.abs(tool.curmousepos.x - tool.x0);
                                    //dimensionmarkupobj.h = Math.abs(tool.curmousepos.y - tool.y0);

                                    //dimensionmarkupobj.w = Math.abs(tool.curmousepos.x - dimensionmarkupobj.x);
                                    //dimensionmarkupobj.h = Math.abs(tool.curmousepos.y - dimensionmarkupobj.y);

                                    dimensionmarkupobj.w = dimensionmarkupobj.w - dimensionmarkupobj.x;
                                    dimensionmarkupobj.h = dimensionmarkupobj.h - dimensionmarkupobj.y;

                                }*/

                                tool.drawDimension({x : tool.curmousepos.x, y : tool.curmousepos.y});
                                //tool.mousemove();

                                //dimensionmarkupobj.w = tool.curmousepos.x;
                                //dimensionmarkupobj.h = tool.curmousepos.y;

                                if(dimensionmarkupobj != null){
                                    dimensionmarkupobj.drawme(context);
                                }



                            }


                        }

                    }


                };

                this.belowlimitExtent = function(zoomscalefactor){
                    var belowlimit = true;


                    var pagedim = DocObj.getCurrentpage().getpagedim();

                    var wlimit = canvasowidth - 60;
                    var hlimit = canvasoheight - 60;

                    if((pagedim.w / zoomscalefactor) < wlimit && (pagedim.h / zoomscalefactor) < hlimit){
                        belowlimit = false;
                        //scalechanged = false;
                        //DocObj.getCurrentpage().zoomall();
                    }

                    var pagerect = DocObj.getCurrentpage().ZoomOutTest(zoomscalefactor, false, tool.curmousepos);

                    var heightlimit = canvasoheight - (nPanlimit*2);
                    var widthlimit = canvasowidth - (nPanlimit*2);
                    //var toplimit = 15;
                    var bottomlimit = ((pagerect.y + pagerect.h) <= heightlimit);
                    var toplimit = (pagerect.y >= nPanlimit);

                    // need to return these to reset the top and bottom positions.scroll|| bottomlimit || toplimit
                    if ((pagerect.w / pagerect.h) < (canvasowidth / canvasoheight)){
                        if(pagerect.h <= heightlimit){
                            belowlimit = false;
                        }

                    }else{
                        if(pagerect.w <= widthlimit){
                            belowlimit = false;
                        }

                    }


                    if(!bLimitZoomOut){
                        belowlimit = true;
                    }

                    return belowlimit;
                };

                this.wheel = function (ev) {

                    var delta = 0;
                    if (ev.wheelDelta !== undefined) { // WebKit / Opera / Explorer 9

                        delta = ev.wheelDelta;

                    } else if (ev.deltaY !== undefined) { // Firefox

                        delta = -ev.deltaY*50;

                    }

                    tool.scrollhandling(delta);


                };

                this.setdimoffset = function(initial){

                    if(initial){


                        dimensionmarkupobj.scaling = getCurrentPageScale();
                        var offset = getCurrentPageOffset();
                        dimensionmarkupobj.xoffset = offset.x;
                        dimensionmarkupobj.yoffset = offset.y;


                        tool.orgscale = dimensionmarkupobj.scaling;
                        tool.orgdx = dimensionmarkupobj.xoffset;
                        tool.orgdy = dimensionmarkupobj.yoffset;


                    }

                    var curscale = DocObj.getCurrentpage().getdscale();
                    var pagedx = DocObj.getCurrentpage().getdx();
                    var pagedy = DocObj.getCurrentpage().getdy();

                    if(dimensionmarkupobj){

                        var scalediff = (curscale / dimensionmarkupobj.scaling);

                        var changex = ((dimensionmarkupobj.w - pagedx) / scalediff) + dimensionmarkupobj.xoffset;
                        var changey = ((dimensionmarkupobj.h - pagedy) / scalediff) + dimensionmarkupobj.yoffset;

                    }

                    //var newx = (tool.startx - tool.orgdx) * scalediff;
                    //var newy = (tool.starty - tool.orgdy) * scalediff;
                    //newx += pagedx;
                    //newy += pagedy;

                    //this.wscaled = (this.w - this.xoffset) * scalefactor;
                    //this.hscaled = (this.h - this.yoffset) * scalefactor;

                    //this.wscaled += pagedx;
                    //this.hscaled += pagedy;
                    //changex = ((this.wscaled + pagedx) / scalefactor) + this.xoffset;


                    //dimensionmarkupobj.w = changex;
                    //dimensionmarkupobj.h = changey;



                };

                this.pointermove = function (ev) {
                    tool.MSPointerMove(ev);
                };
                this.pointerdown = function (ev) {
                    tool.MSPointerDown(ev);
                };

                this.pointerup = function (ev) {
                    tool.MSPointerUp(ev);
                };


                this.MSPointerDown = function (ev) {
                    ev.preventDefault();
                    ev.stopPropagation();

                    var mousePos = getMousePos(canvas, ev);
                    var bWithin = MousePosdrwext(mousePos);
                    if(ev.button == 0){
                        if (!tool.started) {
                            tool.started = true;
                            if(DocObj){
                                DocObj.bMarkupchanged = true;
                            }

                            if (!bWithin && bLimMarkupExtent) {
                                tool.started = false;
                                if(DocObj){
                                    DocObj.bMarkupchanged = false;
                                }

                                return;
                            }
                            if (havesnap) {
                                if(DocObj.getCurrentpage().getpageRotation() != 0){
                                    var rotatedpoint = snap_rotated(snapPoint);
                                }else{
                                    rotatedpoint = snapPoint;
                                }

                                tool.x0 = rotatedpoint.x;
                                tool.y0 = rotatedpoint.y;

                            } else {
                                tool.x0 = mousePos.x;
                                tool.y0 = mousePos.y;
                            }

                            dimensionmarkupobj = new MarkupObject(7, subtype, 0);
                            dimensionmarkupobj.pagenumber = DocObj.getcurPage();

                            dimensionmarkupobj.viewname = DocObj.getcur3DView();

                            if(dimensionmarkupobj.viewname != null){
                                dimensionmarkupobj.bfor3D = true;
                                dimensionmarkupobj.pageheight = canvasoheight;
                                dimensionmarkupobj.pagewidth = canvasowidth;
                            }

                            dimensionmarkupobj.pagerotation = DocObj.getCurrentpage().getpageRotation();

                            tool.setdimoffset(true);
                            tool.startx = tool.x0;
                            tool.starty = tool.y0;

                            dimensionmarkupobj.seteditaction(0);

                        } else {
                            if (bWithin || !bLimMarkupExtent) {
                                if (havesnap) {
                                    if(DocObj.getCurrentpage().getpageRotation() != 0){
                                        rotatedpoint = snap_rotated(snapPoint);
                                    }else{
                                        rotatedpoint = snapPoint;
                                    }

                                    dimensionmarkupobj.w = rotatedpoint.x;
                                    dimensionmarkupobj.h = rotatedpoint.y;

                                } else {
                                    dimensionmarkupobj.w = mousePos.x;
                                    dimensionmarkupobj.h = mousePos.y;

                                }
                                //tool.mousemove(ev);
                                context.clearRect(0, 0, canvas.width, canvas.height);
                                tool.setdimoffset(false);
                                dimensionmarkupobj.drawme(context);

                                if (!bMultimarkupadd) {

                                    bMarkupcrated = true;
                                    //ft 08.08.2018 changed from separate index to direct array length
                                    //nMarkupcreated = DocObj.nummarkups;

                                }
                                nMarkupcreated = DocObj.markuplist.length;

                                dimensionmarkupobj.savemetolistDraw();
                                dimensionmarkupobj = null;
                                tool.started = false;
                                img_update();


                                if(bAlwaysMarkupCallback){
                                    if (RxCore_GUI_Markup != undefined) {

                                        RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[nMarkupcreated], {created : true, modified : false, deleted : false, multi : bMultimarkupadd});
                                    }

                                }else{
                                    if (!bMultimarkupadd) {
                                        //need to move to connection object.
                                        //markupcreated();
                                        if (RxCore_GUI_Markup != undefined) {
                                            //RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[index],true);
                                            RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[nMarkupcreated], {created : true, modified : false, deleted : false});
                                        }

                                    }

                                }


                            }


                        }
                    }else{
                        prevx = mousePos.x;
                        prevy = mousePos.y;

                    }

                };

                this.startDimension = function(bWithin, mousePos){
                    if (bWithin || !bLimMarkupExtent) {
                        tool.started = true;
                        if(DocObj){
                            DocObj.bMarkupchanged = true;
                        }

                        if (havesnap) {
                            if(DocObj.getCurrentpage().getpageRotation() != 0){
                                var rotatedpoint = snap_rotated(snapPoint);
                            }else{
                                rotatedpoint = snapPoint;
                            }

                            tool.x0 = rotatedpoint.x;
                            tool.y0 = rotatedpoint.y;

                        } else {
                            tool.x0 = mousePos.x;
                            tool.y0 = mousePos.y;
                        }

                        dimensionmarkupobj = new MarkupObject(7, subtype, 0);
                        dimensionmarkupobj.pagenumber = DocObj.getcurPage();
                        dimensionmarkupobj.viewname = DocObj.getcur3DView();

                        if(dimensionmarkupobj.viewname != null){
                            dimensionmarkupobj.bfor3D = true;
                            dimensionmarkupobj.pageheight = canvasoheight;
                            dimensionmarkupobj.pagewidth = canvasowidth;
                        }

                        dimensionmarkupobj.pagerotation = DocObj.getCurrentpage().getpageRotation();
                        tool.setdimoffset(true);

                        tool.startx = tool.x0;
                        tool.starty = tool.y0;

                        //dimensionmarkupobj.x = tool.x0;
                        //dimensionmarkupobj.y = tool.y0;

                        dimensionmarkupobj.seteditaction(0);


                    }

                };

                this.completeDimension = function(bWithin, mousePos){


                    if(bOrthoOn){
                        bOrthoOn = false;
                        tempOrtho = true;
                    }

                    if (bWithin || !bLimMarkupExtent) {
                        tool.started = false;

                        if (havesnap) {
                            if(DocObj.getCurrentpage().getpageRotation() != 0){
                                var rotatedpoint = snap_rotated(snapPoint);
                            }else{
                                rotatedpoint = snapPoint;
                            }

                            dimensionmarkupobj.w = rotatedpoint.x;
                            dimensionmarkupobj.h = rotatedpoint.y;

                        } else {

                            /*console.log(tool.bUsemouseinput);
                            if (tool.bUsemouseinput){
                            }*/


                            if(DocObj.getCurrentpage().getpageRotation() != 0){

                                dimensionmarkupobj.w = mousePos.x;
                                dimensionmarkupobj.h = mousePos.y;
                            }else{

                                dimensionmarkupobj.w = mousePos.x;
                                dimensionmarkupobj.h = mousePos.y;

                            }


                        }

                        context.clearRect(0, 0, canvas.width, canvas.height);
                        tool.setdimoffset(false);
                        dimensionmarkupobj.drawme(context);

                        if (!bMultimarkupadd) {

                            bMarkupcrated = true;
                            //ft 08.08.2018 changed from separate index to direct array length

                            //nMarkupcreated = DocObj.nummarkups;
                        }
                        nMarkupcreated = DocObj.markuplist.length;

                        dimensionmarkupobj.savemetolistDraw();

                        if (tempOrtho) {

                            var curpoint = dimensionmarkupobj.calculateOrthoDraw({x: dimensionmarkupobj.x, y: dimensionmarkupobj.y}, { x: dimensionmarkupobj.w, y: dimensionmarkupobj.h });

                            dimensionmarkupobj.w = curpoint.w;
                            dimensionmarkupobj.h = curpoint.h;

                        }

                        dimensionmarkupobj = null;
                        img_update();

                        RxCore_MarkupRedraw();

                        if(bAlwaysMarkupCallback){
                            if (RxCore_GUI_Markup != undefined) {

                                RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[nMarkupcreated], {created : true, modified : false, deleted : false, multi : bMultimarkupadd});
                            }

                        }else{
                            if (!bMultimarkupadd) {
                                //need to move to connection object.
                                //markupcreated();
                                if (RxCore_GUI_Markup != undefined) {
                                    //RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[index],true);
                                    // RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[DocObj.nummarkups], true);
                                    RxCore_GUI_Markup.setMarkupSelected(DocObj.markuplist[nMarkupcreated], {created : true, modified : false, deleted : false});
                                }

                            }
                        }


                        if(tempOrtho){
                            bOrthoOn = true;
                            tempOrtho = false;
                        }



                    }
                };

                this.drawDimension = function(mousePos){

                    if (havesnap) {
                        if(DocObj.getCurrentpage().getpageRotation() != 0){
                            var rotatedpoint = snap_rotated(snapPoint);
                        }else{
                            rotatedpoint = snapPoint;
                        }

                        dimensionmarkupobj.x = tool.x0;
                        dimensionmarkupobj.y = tool.y0;
                        dimensionmarkupobj.w = rotatedpoint.x;
                        dimensionmarkupobj.h = rotatedpoint.y;


                        if(type == 3){
                            dimensionmarkupobj.w = dimensionmarkupobj.w - dimensionmarkupobj.x;
                            dimensionmarkupobj.h = dimensionmarkupobj.h - dimensionmarkupobj.y;

                            //dimensionmarkupobj.w = Math.abs(dimensionmarkupobj.w - dimensionmarkupobj.x);
                            //dimensionmarkupobj.h = Math.abs(dimensionmarkupobj.h - dimensionmarkupobj.y);


                        }
                        tool.bfirstpointset = true;

                        limprevx = rotatedpoint.x;
                        limprevy = rotatedpoint.y;

                    } else {
                        dimensionmarkupobj.x = tool.x0;
                        dimensionmarkupobj.y = tool.y0;
                        dimensionmarkupobj.w = mousePos.x;
                        dimensionmarkupobj.h = mousePos.y;

                        if(type == 3){
                            dimensionmarkupobj.w = dimensionmarkupobj.w - dimensionmarkupobj.x;
                            dimensionmarkupobj.h = dimensionmarkupobj.h - dimensionmarkupobj.y;

                            //dimensionmarkupobj.w = Math.abs(dimensionmarkupobj.w - dimensionmarkupobj.x);
                            //dimensionmarkupobj.h = Math.abs(dimensionmarkupobj.h - dimensionmarkupobj.y);

                        }

                        tool.bfirstpointset = true;

                        limprevx = mousePos.x;
                        limprevy = mousePos.y;

                    }

                };

                this.startRect = function (bWithin, mousePos) {

                    if(bLimMarkupExtent && !bWithin){
                        return;
                    }

                    tool.started = true;
                        if(DocObj){
                            DocObj.bMarkupchanged = true;
                        }

                        if (havesnap) {
                            if(DocObj.getCurrentpage().getpageRotation() != 0){
                                var rotatedpoint = snap_rotated(snapPoint);
                            }else{
                                rotatedpoint = snapPoint;
                            }

                            tool.x0 = rotatedpoint.x;
                            tool.y0 = rotatedpoint.y;
                        } else {
                            tool.x0 = mousePos.x;
                            tool.y0 = mousePos.y;
                        }


                        dimensionmarkupobj = new MarkupObject(type, subtype, fillstyle);


                        /*if (subtype == 3){

                            dimensionmarkupobj.transparency = 30;
                            dimensionmarkupobj.fillcolor = setTransp(rectmarkupobj.fillcolor,rectmarkupobj.transparency);
                        }*/

                        tool.setdimoffset(true);

                        //dimensionmarkupobj.scaling = getCurrentPageScale();
                        //var offset = getCurrentPageOffset();
                        //dimensionmarkupobj.xoffset = offset.x;
                        //dimensionmarkupobj.yoffset = offset.y;

                        dimensionmarkupobj.pagenumber = DocObj.getcurPage();

                        dimensionmarkupobj.viewname = DocObj.getcur3DView();

                        if(dimensionmarkupobj.viewname != null){
                            dimensionmarkupobj.bfor3D = true;
                            dimensionmarkupobj.pageheight = canvasoheight;
                            dimensionmarkupobj.pagewidth = canvasowidth;
                        }


                        dimensionmarkupobj.seteditaction(0);

                };

                this.drawRect = function (mousePos) {
                    /*if (!tool.bUsemouseinput){
                        return;
                    }*/

                    if (havesnap) {
                        if(DocObj.getCurrentpage().getpageRotation() != 0){
                            var rotatedpoint = snap_rotated(snapPoint);
                        }else{
                            rotatedpoint = snapPoint;
                        }

                        /*dimensionmarkupobj.x = tool.x0;
                        dimensionmarkupobj.y = tool.y0;
                        dimensionmarkupobj.w = rotatedpoint.x;
                        dimensionmarkupobj.h = rotatedpoint.y;
                        limprevx = rotatedpoint.x;
                        limprevy = rotatedpoint.y;*/


                        dimensionmarkupobj.x = Math.min(rotatedpoint.x, tool.x0);
                        dimensionmarkupobj.y = Math.min(rotatedpoint.y, tool.y0);

                        dimensionmarkupobj.w = Math.abs(rotatedpoint.x - dimensionmarkupobj.x);
                        dimensionmarkupobj.h = Math.abs(rotatedpoint.y - dimensionmarkupobj.y);

                        tool.bfirstpointset = true;

                        limprevx = rotatedpoint.x;
                        limprevy = rotatedpoint.y;

                        //prevx = rotatedpoint.x;
                        //prevy = rotatedpoint.y;


                    } else {
                        dimensionmarkupobj.x = Math.min(mousePos.x, tool.x0);
                        dimensionmarkupobj.y = Math.min(mousePos.y, tool.y0);
                        dimensionmarkupobj.w = Math.abs(mousePos.x - dimensionmarkupobj.x);
                        dimensionmarkupobj.h = Math.abs(mousePos.y - dimensionmarkupobj.y);

                        tool.bfirstpointset = true;

                        limprevx = mousePos.x;
                        limprevy = mousePos.y;


                    }
                };

