                this.name = 'overlayscale';
                this.anglelengthsupport = false;
                this.refreshSupport = false;

                this.startx = 0;
                this.starty = 0;
                this.x = 0;
                this.y = 0;

                this.w = 0;
                this.h = 0;
                this.distance = 0.0;
                this.orgscale = 1.0;
                this.orgdx = 0.0;
                this.orgdy = 0.0;
