                    ctx.beginPath();
                    ctx.moveTo(this.x, this.y);
                    ctx.lineTo(this.w, this.h);
                    ctx.closePath();
                    ctx.stroke();

                    ctx.strokeRect(this.x-15, this.y-15,30,30);


                    ctx.beginPath();
                    ctx.moveTo(this.x, this.y-15);
                    ctx.lineTo(this.x, this.y-1);
                    ctx.moveTo(this.x, this.y+15);
                    ctx.lineTo(this.x, this.y+1);
                    ctx.moveTo(this.x-15, this.y);
                    ctx.lineTo(this.x-1, this.y);
                    ctx.moveTo(this.x+15, this.y);
