    function setCanvasSize(cv, width, height){

        var aw = width;
        var ah = height;
        var sw = width;
        var sh = height;


        const scale = getPixelRatio();
        var style = cv.style;

        cv.width = Math.floor(width * scale);
        cv.height = Math.floor(height * scale);

        aw = Math.floor(width * scale);
        ah = Math.floor(height * scale);

        if(scale != 1){

            style.width  = '' + width + 'px';
            style.height = '' + height + 'px';

            sw = width;
            sh = height;

        }

        return {awidth : aw, aheight : ah, swidth : sw, sheight : sh};

        //cv.width = width;
        //cv.height = height;

        //cv.style.width = width + 'px';
        //cv.style.height = height + 'px';



    }

    function resizeCanvas(offsetWidth, offsetHeight) {
        //console.log(rxcontainer.clientWidth);
        //console.log(rxcontainer.clientHeight);

        const scale = getPixelRatio();

        offsetWidth = offsetWidth || defaultLayout.offsetWidth;
        offsetHeight = offsetHeight || defaultLayout.offsetHeight;

        /* offsetParent offsets are 0 when no position:fixed menus available */
        if (rxcontainer.offsetParent){

            if(!defaultLayout.absolute){
                offsetWidth += rxcontainer.offsetParent.offsetLeft;
                offsetHeight += rxcontainer.offsetParent.offsetTop;
                //console.log(rxcontainer.offsetParent.offsetWidth);
            }

        }

        //canvaso.width = rxcontainer.offsetWidth;
        //canvaso.height = rxcontainer.offsetHeight;


        if(defaultLayout.absolute){


            var retsize = setCanvasSize(canvaso, offsetWidth, offsetHeight);
            //setCanvasSize(canvaso, offsetWidth, offsetHeight);


            //canvaso.width = Math.floor(offsetWidth * scale);
            //canvaso.height = Math.floor(offsetHeight * scale);

            //canvaso.width = offsetWidth;
            //canvaso.height = offsetHeight;
            //canvasowidth = canvaso.width;
            //canvasoheight = canvaso.height;

            canvasowidth = retsize.awidth;// / scale;
            canvasoheight = retsize.aheight;// / scale;

            canvasowidthsize = retsize.swidth;
            canvasoheightsize = retsize.sheight;

            //canvas.style.width = offsetWidth + 'px';
            //canvas.style.height = offsetHeight + 'px';


        }else{

            //canvaso.width = window.innerWidth - offsetWidth;
            //canvaso.height = window.innerHeight - offsetHeight;
            //setCanvasSize(canvaso, window.innerWidth - offsetWidth, window.innerHeight - offsetHeight);

            retsize = setCanvasSize(canvaso, window.innerWidth - offsetWidth, window.innerHeight - offsetHeight);

            //canvaso.width = Math.floor((window.innerWidth - offsetWidth) * scale);
            //canvaso.height = Math.floor((window.innerHeight - offsetHeight) * scale);

            //canvas.style.width = window.innerWidth - offsetWidth + 'px';
            //canvas.style.height = window.innerHeight - offsetHeight + 'px';


            //canvasowidth = canvaso.width;
            //canvasoheight = canvaso.height;

            canvasowidth = retsize.awidth;// / scale;
            canvasoheight = retsize.aheight;// / scale;

            canvasowidthsize = retsize.swidth;
            canvasoheightsize = retsize.sheight;


        }

        if(docpagNotReady()){
            return;
        }

        if (documentopen && !DocObj.getCurrentpage().usevector3Dxml) {

            var curwidth = canvasowidth;
            //var curheight = canvasoheight;


            var scalefactor = (window.innerWidth - offsetWidth) / curwidth;

            /*if(DocObj.getCurrentpage().usevectorxml){
                //var tempdx = DocObj.getCurrentpage().dxvector;
                //var tempdy = DocObj.getCurrentpage().dyvector;
            }*/


            /*if(DocObj.getCurrentpage().usevectorxml){
                //DocObj.getCurrentpage().dxvector = tempdx;
                //DocObj.getCurrentpage().dyvector = tempdy;

            }*/

            if(documentopen && DocObj.getCurrentpage().usepdfjs){
                setSmoothingEnabled(false);
            }else{
                setSmoothingEnabled(false);
            }


        }



    }

    function doResize(binternal , offsetWidth, offsetHeight) {



        if (!canvaso) {
            //alert('Error: I cannot find the canvas element!');
            return;
        }

        resizeCanvas(offsetWidth, offsetHeight);

        setCanvasSize(canvimg, canvasowidthsize, canvasoheightsize);
        setCanvasSize(canvas, canvasowidthsize, canvasoheightsize);
        setCanvasSize(renderer.domElement, canvasowidthsize, canvasoheightsize);

        //canvimg.width = canvasowidth;
        //canvimg.height = canvasoheight;

        //canvas.width = canvasowidth;
        //canvas.height = canvasoheight;

        //renderer.domElement.width = canvasowidth;
        //renderer.domElement.height = canvasoheight;


        if(docpagNotReady()){
            if(!bwelcomedisabled){
                imagewidth = splashimage.naturalWidth;
                imageheight = splashimage.naturalHeight;

                var yscale = canvasoheight / imageheight;
                var xscale = canvasowidth / imagewidth;
                var dscale = Math.min(xscale, yscale);

                var dx = (canvasowidth - (imagewidth * dscale)) / 2;
                var dy = (canvasoheight - (imageheight * dscale)) / 2;

                context.clearRect(0, 0, canvas.width, canvas.height);
                cntximg.clearRect(0, 0, canvas.width, canvas.height);
                contexto.clearRect(0, 0, canvas.width, canvas.height);

                //numLayers = 0;
                draw_image(splashimage, dx, dy, dscale);

            }

        }else{
            if (documentopen && DocObj.getCurrentpage().usevector3Dxml) {
                //renderer.setSize(canvasowidth, canvasoheight);
                renderer.setSize(canvasowidthsize, canvasoheightsize);


                if (DocObj.getCurrentpage().camera) {
                    //DocObj.getCurrentpage().camera.aspect = canvasowidth / canvasoheight;
                    DocObj.getCurrentpage().camera.aspect = canvasowidthsize / canvasoheightsize;
                    DocObj.getCurrentpage().camera.updateProjectionMatrix();

                    if (bUsePostprocess){
                        //DocObj.getCurrentpage().Vector3DPageObj.effectComposer.setSize( canvaso.width, canvaso.height );
                        DocObj.getCurrentpage().Vector3DPageObj.effectComposer.setSize( canvasowidthsize, canvasoheightsize );
                    }

                }

            }

            DocObj.getCurrentpage().resize();
        }


        //RxCore_scrollBarCheck();

        if (binternal){
            if (RxCore_GUI_Resize != undefined) {
                var canvasSize = {
                    w:canvasowidth,
                    h:canvasoheight
                };
                RxCore_GUI_Resize.onResize(canvasSize);
            }
        }else{
            if (RxCore_GUI_Resize_ext != undefined) {
                var canvasSize = {
                    w:canvasowidth,
                    h:canvasoheight
                };
                RxCore_GUI_Resize_ext.onResize(canvasSize);
            }

        }


    }

    function resizeCanvasdirect(width, height) {


        if(defaultLayout.absolute){
            width = width || defaultLayout.offsetWidth;
            height = height || defaultLayout.offsetHeight;
        }else{
            return;
        }

        var retsize = setCanvasSize(canvaso, width, height);


        canvasowidth = retsize.swidth;// / scale;
        canvasoheight = retsize.sheight;// / scale;

        canvasowidthsize = retsize.awidth;
        canvasoheightsize = retsize.aheight;

        //canvaso.width = width;
        //canvaso.height = height;
        //canvasowidth = canvaso.width;
        //canvasoheight = canvaso.height;

        if(documentopen && DocObj.getCurrentpage().usepdfjs){
            setSmoothingEnabled(false);
        }else{
            setSmoothingEnabled(false);
        }


    }

    function doResizeEx(width, height){

        if (!canvaso) {
            //alert('Error: I cannot find the canvas element!');
            return;
        }

        resizeCanvasdirect(width, height);

        if(docpagNotReady()){
            if(!bwelcomedisabled){

                imagewidth = splashimage.naturalWidth;
                imageheight = splashimage.naturalHeight;

                var yscale = canvaso.height / imageheight;
                var xscale = canvaso.width / imagewidth;
                var dscale = Math.min(xscale, yscale);

                var dx = (canvaso.width - (imagewidth * dscale)) / 2;
                var dy = (canvaso.height - (imageheight * dscale)) / 2;

                context.clearRect(0, 0, canvas.width, canvas.height);
                cntximg.clearRect(0, 0, canvas.width, canvas.height);
                contexto.clearRect(0, 0, canvas.width, canvas.height);

                //numLayers = 0;

                draw_image(splashimage, dx, dy, dscale);

            }
        }else{
            if (documentopen && DocObj.getCurrentpage().usevector3Dxml) {
                renderer.setSize(canvaso.width, canvaso.height);


                if (DocObj.getCurrentpage().camera) {
                    DocObj.getCurrentpage().camera.aspect = canvaso.width / canvaso.height;
                    DocObj.getCurrentpage().camera.updateProjectionMatrix();

                    if (bUsePostprocess){
                        DocObj.getCurrentpage().Vector3DPageObj.effectComposer.setSize( canvaso.width, canvaso.height );
                    }
                }

            }

            DocObj.getCurrentpage().resize();
        }


        setCanvasSize(canvimg, canvasowidthsize, canvasoheightsize);
        setCanvasSize(canvas, canvasowidthsize, canvasoheightsize);
        setCanvasSize(renderer.domElement, canvasowidthsize, canvasoheightsize);


        //canvimg.width = canvaso.width;
        //canvimg.height = canvaso.height;

        //canvas.width = canvaso.width;
        //canvas.height = canvaso.height;

        //renderer.domElement.width = canvaso.width;
        //renderer.domElement.height = canvaso.height;


    }

    function RxCore_hideTextInput() {
        if (RxCore_GUI_TextInput != undefined) {
            if(DocObj && DocObj.selectedmarkup && DocObj.selectedmarkup.edit){
                RxCore_GUI_TextInput.operation.edit = false;
                RxCore_GUI_TextInput.operation.start = false;
                RxCore_GUI_TextInput.operation.create = false;
                RxCore_GUI_TextInput.operation.save = true;
                RxCore_GUI_TextInput.operation.markup = DocObj.markuplist[DocObj.selectedmarkup.id];

                var rect = canvas.getBoundingClientRect();
                var xrect  = DocObj.markuplist[DocObj.selectedmarkup.id].rotatedrect.x + rect.left;
                var yrect = DocObj.markuplist[DocObj.selectedmarkup.id].rotatedrect.y + rect.top;

                //var xrect  = DocObj.markuplist[DocObj.selectedmarkup.id].xscaled + rect.left;
                //var yrect = DocObj.markuplist[DocObj.selectedmarkup.id].yscaled + rect.top;

                var wrect = DocObj.markuplist[DocObj.selectedmarkup.id].wscaled;
                var hrect = DocObj.markuplist[DocObj.selectedmarkup.id].hscaled;

                var txtrect = new Rectangle(xrect,yrect,wrect,hrect);
                txtrect.rotation = DocObj.getCurrentpage().getpageRotation();

                var pixelRatio = getPixelRatio();
                //txtrect.x = txtrect.x / pixelRatio;
                //txtrect.y = txtrect.y / pixelRatio;

                txtrect.x = ((txtrect.x - rect.left) / pixelRatio) + rect.left;
                txtrect.y = ((txtrect.y - rect.top) / pixelRatio) + rect.top;

                txtrect.w = txtrect.w / pixelRatio;
                txtrect.h = txtrect.h / pixelRatio;


                RxCore_GUI_TextInput.setTextInput(txtrect);


                DocObj.markuplist[DocObj.selectedmarkup.id].selectedit = false;
                DocObj.markuplist[DocObj.selectedmarkup.id].setselect(false);

                DocObj.selectedmarkup.edit = false;
                //DocObj.setMarkupMultiselected();

            }
        }
    }

